    (g) =>
      !context.memory?.observations.some(
        (o) =>
          o.goal === g &&
          (semantic
            ? ['covered', 'inconclusive', 'not_applicable']
            : ['covered', 'not_applicable']
          ).includes(o.state),
      ),
  );
