  const knowledgeChunks = knowledgeReady(grounding) ? context.retrieval.chunks : [];
  const policy = interviewPolicy(interview.configuration);
  const pacing = interviewPacing(interview, {
    ...context.memory!,
    conversation: grounding.conversation,
