export interface ReportIndicatorAssessment {
  indicator_id: ReportIndicatorId;
  status: 'scored' | 'not_observed';
  level: 0 | 1 | 2 | 3 | 4 | null;
  text: string;
  evidence_refs: InterviewEvidence[];
}

/** Applicability is decided from the question and frozen reference, never from a fluent answer. */
export function applicableReportIndicators(
  turn: InterviewTurn,
  snapshot: InterviewSnapshot,
): ReportRubricIndicator[] {
  const question = turn.text;
  const reference = snapshot.knowledge.questions.some(
    (q) =>
      (q.id === turn.knowledge_question_id || q.topic === turn.topic) &&
      q.report_reference?.cards.length,
  );
  return REPORT_INDICATORS.filter((i) => {
    if (i.id === 'relevance' || i.id === 'structure') return true;
    if (turn.stage === 'introduction') return false;
    if (i.id === 'personal_ownership')
      return (
        /负责|职责|贡献|你(?:具体)?做了|本人|你如何|你怎么/.test(question) &&
        turn.stage === 'experience'
      );
    if (i.id === 'verification')
      return (
        turn.stage === 'experience' && /验证|测试|结果|效果|指标|对比|复盘|证明|衡量/.test(question)
      );
    if (i.id === 'technical_accuracy') return reference && turn.stage === 'technical';
    return (
      reference &&
      ['technical', 'business'].includes(turn.stage ?? '') &&
      /为什么|为何|原因|取舍|选择|比较|对比|权衡|适合|方案|设计/.test(question)
    );
  });
}

/** Equal indicators within dimensions; repeated follow-ups do not increase an indicator's weight. */
export function aggregateIndicatorScores(evaluations: InterviewEvaluation[]) {
  return REPORT_INDICATORS.flatMap((indicator) => {
    const ratings = evaluations
      .filter((e) => e.scoring_rubric_version === FRONTEND_RUBRIC_VERSION)
      .flatMap((e) =>
        (e.indicator_assessments ?? []).filter(
          (a) =>
            a.indicator_id === indicator.id &&
            a.status === 'scored' &&
            a.level !== null &&
            Number.isInteger(a.level) &&
            a.level >= 0 &&
            a.level <= 4 &&
            a.evidence_refs.length,
        ),
      );
    if (!ratings.length) return [];
    return [
      {
        ...indicator,
        score: ratings.reduce((sum, a) => sum + a.level! * 25, 0) / ratings.length,
        evidence_refs: ratings.flatMap((a) => a.evidence_refs),
        observations: ratings.length,
      },
    ];
  });
}

export const RESUME_FIELDS = {"full_name": "姓名", "phone": "联系电话", "email": "邮箱", "city": "所在城市", "education": "教育背景", "skills": "专业技能", "projects": "项目经历（职责、行动、技术取舍、结果）", "internships": "实习与工作经历", "awards": "竞赛与荣誉", "summary": "个人优势与自我介绍"} as const;
export type ResumeTemplate = Record<keyof typeof RESUME_FIELDS,string>;
export const emptyResumeTemplate = (): ResumeTemplate => Object.fromEntries(Object.keys(RESUME_FIELDS).map(k=>[k,''])) as ResumeTemplate;
export function extractResumeTemplate(text: string): ResumeTemplate {
 const result = emptyResumeTemplate();
 const normalized = text.replace(//r/n?/g, '/n').replace(//u00a0/g, ' ');
 result.email = normalized.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+/.[A-Za-z]{2,}/)?.[0] ?? '';
 result.phone = normalized.match(/(?<!/d)(?:/+86[ -]?)?1[3-9](?:[ -]?/d){9}(?!/d)/)?.[0] ?? '';
 const sections: [RegExp, keyof ResumeTemplate][] = [
  [/^(教育背景|教育经历|学历信息|教育|education(?: background)?)$/i, 'education'],
  [/^(专业技能|技术技能|技能清单|技能特长|个人技能|技能|skills|technical skills)$/i, 'skills'],
  [/^(项目经历|项目经验|个人项目|科研经历|项目|projects|project experience)$/i, 'projects'],
  [/^(实习经历|工作经历|工作经验|实习与工作经历|实践经历|实习|experience|work experience|internships?)$/i, 'internships'],
  [/^(竞赛与荣誉|荣誉奖项|获奖经历|获奖情况|竞赛经历|荣誉|奖项|awards|honors)$/i, 'awards'],
  [/^(个人优势|自我评价|个人简介|自我介绍|个人总结|summary|profile)$/i, 'summary'],
 ];
 let current: keyof ResumeTemplate | undefined;
 for (const raw of normalized.split('/n')) {
  const line = raw.trim();
  if (!line) {
   if (current && result[current] && !result[current].endsWith('/n')) result[current] += '/n';
   continue;
  }
  const candidate = line.replace(/^[/s•●■◆#一二三四五六七八九十0-9、.（）()]+/, '').trim();
  const colon = candidate.search(/[:：]/);
  const title = (colon < 0 ? candidate : candidate.slice(0, colon)).replace(//s/g, '');
  const section = sections.find(([pattern]) => pattern.test(title));
  if (section) {
   current = section[1];
   const rest = colon < 0 ? '' : candidate.slice(colon + 1).trim();
   if (rest) result[current] += (result[current] ? '/n' : '') + rest;
   continue;
  }
  const name = line.match(/(?:^|[|｜])/s*(?:姓名|名字)/s*[:：]/s*([^|｜,，;；/s]{2,30})/);
  if (name) result.full_name = name[1];
  const city = line.match(/(?:^|[|｜])/s*(?:城市|所在城市|现居地|所在地|现居)/s*[:：]/s*([^|｜;；]{2,40})/);
  if (city) result.city = city[1].trim();
  if (current) result[current] += (result[current] ? '/n' : '') + line;
 }
 return result;
}

'use client';
import { useEffect, useState } from 'react';
import { usePathname, useRouter } from 'next/navigation';
import { businessTarget, loginDestination, requiresLogin } from '../lib/access';
import { useSession } from './session-provider';
import { AuthForm } from './auth-form';
import { Header, Loading, Modal } from './shared';
import { Button } from './ui/button';

export function AccountAccess({ children }: { children: React.ReactNode }) {
  const { state, refresh } = useSession();
  const path = usePathname();
  const router = useRouter();
  const [target, setTarget] = useState<string | null>(null);
  const protectedPage = requiresLogin(path);
  useEffect(() => {
    if (protectedPage && state.status === 'signed_out') {
      setTarget(
        businessTarget(window.location.pathname + window.location.search + window.location.hash) ??
          '/me',
      );
      router.replace('/');
    }
  }, [protectedPage, path, state.status, router]);
  useEffect(() => {
    if (target && state.status === 'signed_in' && path === '/') {
      setTarget(null);
      router.push(target);
    }
  }, [target, state.status, path, router]);
  const content =
    !protectedPage || state.status === 'signed_in' ? (
      children
    ) : state.status === 'loading' || state.status === 'signed_out' ? (
      <>
        <Header />
        <main id="main-content" className="container section">
          <Loading />
        </main>
      </>
    ) : (
      <>
        <Header />
        <main id="main-content" className="container section">
          <p role="alert">无法确认登录状态，业务内容暂不可用。</p>
          <Button onClick={() => void refresh()}>重新连接</Button>
        </main>
      </>
    );
  return (
    <div
      onClickCapture={(event) => {
        if (
          state.status === 'signed_in' ||
          event.button !== 0 ||
          event.metaKey ||
          event.ctrlKey ||
          event.shiftKey ||
          event.altKey
        )
          return;
        const anchor = (event.target as Element).closest('a[href]');
        if (
          !(anchor instanceof HTMLAnchorElement) ||
          anchor.target === '_blank' ||
          anchor.hasAttribute('download')
        )
          return;
        const url = new URL(anchor.href);
        if (url.origin !== window.location.origin) return;
        const next = businessTarget(url.pathname + url.search + url.hash);
        if (!next && (url.pathname !== '/login' || path !== '/')) return;
        event.preventDefault();
        event.stopPropagation();
        setTarget(
          next ??
            loginDestination(
              url.searchParams.get('next') ??
                window.location.pathname + window.location.search + window.location.hash,
            ),
        );
      }}
    >
      <div key={state.status === 'signed_in' ? state.session.user.id : 'guest'}>{content}</div>
      <Modal
        open={Boolean(target) && path === '/' && state.status !== 'signed_in'}
        onOpenChange={(open) => {
          if (!open) setTarget(null);
        }}
        title="登录或注册"
        description="登录后使用当前账号的真实面试和记录。"
      >
        {state.status === 'loading' ? <Loading /> : <AuthForm />}
      </Modal>
    </div>
  );
}

'use client';
import { useState } from 'react';
import { authClient } from '../lib/api/auth';
import { ApiClientError } from '../lib/api/http';
import { useSession } from './session-provider';
import { Button } from './ui/button';

export function AuthForm({ onSuccess }: { onSuccess?: () => void }) {
  const { state, refresh } = useSession();
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState('');
  async function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = event.currentTarget;
    const values = new FormData(form);
    const password = String(values.get('password'));
    if (mode === 'register' && password !== values.get('confirmation')) {
      setMessage('两次输入的密码不一致。');
      return;
    }
    setBusy(true);
    setMessage('');
    try {
      const email = String(values.get('email')).trim();
      if (mode === 'register')
        await authClient.signUp({ email, password, name: String(values.get('name')).trim() });
      else
        await authClient.signIn({ email, password, rememberMe: values.get('remember') === 'on' });
      form.reset();
      const session = await refresh();
      if (!session) {
        setMessage('操作已完成，但无法确认登录状态。请重试登录或重新连接。');
        return;
      }
      onSuccess?.();
    } catch (error) {
      setMessage(
        error instanceof ApiClientError && error.status === 401
          ? '邮箱或密码不正确。'
          : error instanceof ApiClientError && error.status === 429
            ? '操作过于频繁，请稍后重试。'
            : error instanceof Error
              ? error.message
              : '操作失败，请重试。',
      );
    } finally {
      setBusy(false);
    }
  }
  if (state.status === 'unavailable' || state.status === 'error')
    return (
      <div role="alert">
        <p>账号服务暂时不可用，请检查服务配置或稍后重试。</p>
        <Button onClick={() => void refresh()}>重新连接</Button>
      </div>
    );
  return (
    <>
      <div className="row-actions" role="group" aria-label="账号操作">
        <Button
          type="button"
          variant={mode === 'login' ? 'default' : 'outline'}
          disabled={busy}
          aria-pressed={mode === 'login'}
          onClick={() => {
            setMode('login');
            setMessage('');
          }}
        >
          登录
        </Button>
        <Button
          type="button"
          variant={mode === 'register' ? 'default' : 'outline'}
          disabled={busy}
          aria-pressed={mode === 'register'}
          onClick={() => {
            setMode('register');
            setMessage('');
          }}
        >
          注册
        </Button>
      </div>
      <form key={mode} onSubmit={submit} className="auth-form">
        {mode === 'register' && (
          <label>
            显示名
            <input
              name="name"
              autoComplete="nickname"
              minLength={1}
              maxLength={100}
              required
              disabled={busy}
            />
          </label>
        )}
        <label>
          邮箱
          <input
            name="email"
            type="email"
            autoComplete="username"
            maxLength={254}
            required
            disabled={busy}
          />
        </label>
        <label>
          密码
          <input
            name="password"
            type="password"
            autoComplete={mode === 'register' ? 'new-password' : 'current-password'}
            minLength={mode === 'register' ? 9 : 1}
            maxLength={mode === 'register' ? 20 : 128}
            required
            disabled={busy}
          />
        </label>
        {mode === 'register' ? (
          <>
            <label>
              确认密码
              <input
                name="confirmation"
                type="password"
                autoComplete="new-password"
                minLength={9}
                maxLength={mode === 'register' ? 20 : 128}
                required
                disabled={busy}
              />
            </label>
            <p className="muted">密码为 9–20 个字符。暂不支持找回密码。</p>
          </>
        ) : (
          <label className="row-actions">
            <input name="remember" type="checkbox" disabled={busy} />
            记住登录状态
          </label>
        )}
        <Button type="submit" disabled={busy || state.status === 'loading'}>
          {busy ? '正在处理…' : mode === 'register' ? '注册并登录' : '登录账号'}
        </Button>
      </form>
      {message && <p role="alert">{message}</p>}
    </>
  );
}

'use client';
import { useEffect, useRef, type ReactNode } from 'react';
import {
  ArrowLeft,
  ArrowUp,
  CameraOff,
  Check,
  CheckCheck,
  Clock3,
  FileText,
  Keyboard,
  Pause,
  Play,
  SkipForward,
  Square,
  VolumeX,
} from 'lucide-react';
import Link from 'next/link';
import { Brand, formatTime } from './shared';
import { Button } from './ui/button';

export interface WorkspaceTurn {
  id: string;
  text: string;
  label: string;
  acknowledgement?: string;
  status: 'waiting' | 'answered' | 'skipped';
  answer: string | null;
  inputMode?: 'text_fallback' | 'voice';
}
interface Props {
  jobTitle: string;
  typeLabel: string;
  interviewerLabel: string;
  interviewerStatus: string;
  seconds: number;
  durationMinutes: number;
  turns: WorkspaceTurn[];
  current?: WorkspaceTurn;
  draft: string;
  maxAnswer: number;
  canAnswer: boolean;
  blocked?: boolean;
  paused: boolean;
  ended: boolean;
  saveLabel: string;
  draftHint?: string;
  explanation?: string | null;
  notice?: ReactNode;
  conversationNotice?: ReactNode;
  interviewerNote: ReactNode;
  workspace?: ReactNode;
  tools?: ReactNode;
  voiceActive?: boolean;
  voiceView?: boolean;
  recordsHref: string;
  reportHref?: string;
  onText: (text: string) => void;
  onSubmit: () => void;
  onSkip: () => void;
  onRepeat: () => void;
  onClarify?: () => void;
  onPause: () => void;
  onFinish: () => void;
  onStart?: () => void;
}

/** Original interview layout shared by the HTTP and explicit demo controllers. */
export function InterviewWorkspace(p: Props) {
  const log = useRef<HTMLDivElement>(null);
  const history = useRef<HTMLDivElement>(null);
  const last = p.turns.at(-1);
  useEffect(() => {
    if (log.current) log.current.scrollTop = log.current.scrollHeight;
  }, [last?.id, last?.status, p.interviewerStatus, p.explanation]);
  useEffect(() => {
    if (history.current) history.current.scrollTop = history.current.scrollHeight;
  }, [last?.id]);
  return (
    <div className="session-shell">
      <header className="session-header">
        <Brand />
        <div className="session-title">
          <strong>{p.jobTitle}</strong>
          <span>/</span>
          <span>{p.typeLabel}</span>
        </div>
        <div className="session-header-right">
          <span className={`timer ${p.seconds >= p.durationMinutes * 60 ? 'timer-warning' : ''}`}>
            <Clock3 size={16} />
            {formatTime(p.seconds)}
            <small>/ {formatTime(p.durationMinutes * 60)}</small>
          </span>
          {p.onStart ? (
            <Button size="sm" disabled={p.blocked} onClick={p.onStart}>
              <Play size={14} />
              开始面试
            </Button>
          ) : (
            !p.ended && (
              <>
                <Button variant="outline" size="sm" disabled={p.blocked} onClick={p.onPause}>
                  {p.paused ? <Play size={14} /> : <Pause size={14} />}
                  {p.paused ? '继续' : '暂停'}
                </Button>
                <Button variant="danger" size="sm" disabled={p.blocked} onClick={p.onFinish}>
                  <Square size={12} />
                  结束面试
                </Button>
              </>
            )
          )}
          {p.ended && p.reportHref && (
            <Button asChild size="sm">
              <Link href={p.reportHref}>查看复盘</Link>
            </Button>
          )}
        </div>
      </header>
      <main className="session-main" id="main-content">
        {p.notice}
        <div className={`session-grid${p.voiceView ? ' session-grid-voice' : ''}`}>
          <aside className="panel interviewer-panel">
            <div className="interviewer-person">
              <span className="avatar avatar-mint">面</span>
              <div>
                <h2>面试官</h2>
                <span>
                  <span className="status-dot" />
                  {p.interviewerStatus}
                </span>
              </div>
              <span className="badge badge-neutral">{p.interviewerLabel}</span>
            </div>
            <div className="current-question">
              <div className="question-meta">
                <span className="badge badge-yellow">当前问题</span>
                <span>{p.current?.label ?? (p.ended ? '已结束' : '准备开始')}</span>
              </div>
              <h1>
                {p.current?.text ?? (p.ended ? '本场面试已结束。' : '准备好后，点击开始面试。')}
              </h1>
              {p.current && (
                <button className="text-link" disabled={!p.canAnswer} onClick={p.onRepeat}>
                  <VolumeX size={14} />
                  再看一遍题目
                </button>
              )}
              {p.explanation && (
                <p className="repeated-question" role="status">
                  {p.explanation}
                </p>
              )}
            </div>
            <div
              className="question-history"
              ref={history}
              role="region"
              aria-label="题目轨迹"
              tabIndex={0}
            >
              <div className="panel-heading">
                <h2>题目轨迹</h2>
                <span>{p.turns.filter((t) => t.status !== 'waiting').length} 次已记录</span>
              </div>
              {p.turns.map((t) => (
                <div
                  className={`history-question ${t.status === 'waiting' ? 'history-current' : ''}`}
                  key={t.id}
                >
                  <span className={t.status === 'skipped' ? 'question-skipped' : 'question-done'}>
                    {t.status === 'skipped' ? (
                      <SkipForward size={11} />
                    ) : t.status === 'answered' ? (
                      <Check size={11} />
                    ) : (
                      '·'
                    )}
                  </span>
                  <div>
                    <small>
                      {t.status === 'waiting' ? (p.ended ? '未回答' : '正在作答') : t.label}
                    </small>
                    <p>{t.text}</p>
                    {t.status === 'skipped' && <em>已跳过</em>}
                  </div>
                </div>
              ))}
            </div>
            <div className="interviewer-foot">
              <FileText size={15} />
              <p>{p.interviewerNote}</p>
            </div>
          </aside>
          <section className="panel answer-panel">
            <div className="answer-panel-header">
              <h2>{p.voiceView ? '语音面试' : '作答记录'}</h2>
              <span>
                <CheckCheck size={14} />
                {p.saveLabel}
              </span>
            </div>
            {!p.voiceView && (
              <div className="conversation" ref={log} role="log" aria-label="面试对话记录">
                {!p.turns.some((t) => t.status !== 'waiting') && (
                  <div className="conversation-intro">
                    <span className="badge badge-mint">从认识你开始</span>
                    <p>
                      准备好后，在下方输入你的回答。
                      <br />
                      不用追求一次说得完美。
                    </p>
                  </div>
                )}
                {p.turns.map((t) => (
                  <div className="conversation-turn" key={t.id}>
                    <div
                      className={`message message-interviewer ${t.status === 'waiting' ? 'message-current' : ''}`}
                    >
                      <span className="avatar avatar-mint">面</span>
                      <div>
                        <small>{t.status === 'waiting' ? '当前问题' : t.label}</small>
                        {t.acknowledgement && <p>{t.acknowledgement}</p>}
                        <p>{t.text}</p>
                      </div>
                    </div>
                    {t.status !== 'waiting' && (
                      <div className="message message-user">
                        <span className="avatar avatar-peach">我</span>
                        <div>
                          <small>
                            {t.inputMode === 'voice' ? '语音转写' : '文字作答'} · 已记录
                          </small>
                          <p>{t.status === 'skipped' ? '已跳过此题' : t.answer}</p>
                        </div>
                      </div>
                    )}
                  </div>
                ))}
                {p.conversationNotice}
                {p.paused && (
                  <div className="pause-notice" role="status">
                    <Pause size={15} />
                    面试已暂停，计时仍继续。点击“继续”恢复作答。
                  </div>
                )}
                {p.ended && (
                  <div className="notice" role="status">
                    本场面试已结束，已提交的回答已保存。
                  </div>
                )}
              </div>
            )}
            {p.workspace}
            {!p.voiceView && (
              <form
                className="answer-composer"
                onSubmit={(e) => {
                  e.preventDefault();
                  if (p.canAnswer && p.draft.trim()) p.onSubmit();
                }}
              >
                <div className="composer-heading">
                  <label htmlFor="answer">你的回答</label>
                  <span>{p.voiceActive ? '语音转写 · 麦克风已开启' : '文字作答 · 麦克风关闭'}</span>
                </div>
                <textarea
                  id="answer"
                  maxLength={p.maxAnswer}
                  disabled={!p.canAnswer && !p.ended}
                  readOnly={p.ended || p.voiceActive}
                  value={p.draft}
                  onChange={(e) => p.onText(e.target.value)}
                  placeholder={
                    p.paused
                      ? '继续面试后即可作答'
                      : p.voiceActive
                        ? '请直接说话，实时转写将显示在这里…'
                        : p.onStart
                          ? '点击右上角“开始面试”后即可作答'
                          : '在这里输入回答，结合自己的经历和理解说明…'
                  }
                  onKeyDown={(e) => {
                    if (
                      (e.ctrlKey || e.metaKey) &&
                      e.key === 'Enter' &&
                      !e.nativeEvent.isComposing
                    ) {
                      e.preventDefault();
                      if (p.canAnswer && p.draft.trim()) p.onSubmit();
                    }
                  }}
                />
                {p.draftHint && (
                  <p className="field-help" role="status">
                    {p.draftHint}
                  </p>
                )}
                <div className="composer-bottom">
                  <span>
                    {p.draft.length}/{p.maxAnswer} <kbd>Ctrl + Enter</kbd>
                  </span>
                  <div>
                    {p.onClarify && (
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        disabled={!p.canAnswer}
                        onClick={p.onClarify}
                      >
                        澄清题意
                      </Button>
                    )}
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      disabled={!p.canAnswer}
                      onClick={p.onSkip}
                    >
                      <SkipForward size={14} />
                      跳过
                    </Button>
                    <Button type="submit" size="sm" disabled={!p.canAnswer || !p.draft.trim()}>
                      提交回答
                      <ArrowUp size={15} />
                    </Button>
                  </div>
                </div>
              </form>
            )}
            <div className="session-tools">
              <span>
                <Keyboard size={14} />
                {p.voiceView ? '语音模式' : '文字模式'}
              </span>
              {p.tools}
              <span className="device-off">
                <CameraOff size={14} />
                镜头关闭
              </span>
              <Link href={p.recordsHref}>
                <ArrowLeft size={13} />
                返回记录
              </Link>
            </div>
          </section>
        </div>
      </main>
    </div>
  );
}

