export interface StartRequest {
  id: string;
  version: number;
  key: string;
}
/** Recovery confirms server state before retrying the same start operation. */
export async function startPreparedInterview(
  id: string,
  options: {
    request: { current: StartRequest | null };
    storageKey: string;
    isCurrent: () => boolean;
    api?: Pick<typeof interviewsApi, 'read' | 'command'>;
    storage?: Pick<Storage, 'getItem' | 'setItem' | 'removeItem'> | null;
  },
): Promise<Interview> {
  const api = options.api ?? interviewsApi;
  let storage = options.storage ?? null;
  if (options.storage === undefined) {
    try {
      storage = typeof sessionStorage === 'undefined' ? null : sessionStorage;
    } catch {}
  }
  const assertCurrent = () => {
    if (!options.isCurrent()) throw new Error('本次准备已取消。');
  };
  const clear = () => {
    options.request.current = null;
    try {
      storage?.removeItem(options.storageKey);
    } catch {}
  };
  const fresh = await api.read(id);
  assertCurrent();
  if (fresh.status === 'in_progress') {
    clear();
    return fresh;
  }
  if (fresh.status !== 'ready')
    throw new Error(
      fresh.status === 'paused' ? '本场已暂停，请从面试间继续。' : '本场面试已结束。',
    );
  if (fresh.preparation && !['ready', 'fallback'].includes(fresh.preparation.status))
    throw new Error('面试仍在准备，请稍候。');
  if (options.request.current?.id !== id) {
    try {
      const saved = JSON.parse(
        storage?.getItem(options.storageKey) ?? 'null',
      ) as StartRequest | null;
      if (saved?.id === id && typeof saved.key === 'string' && Number.isInteger(saved.version))
        options.request.current = saved;
    } catch {}
  }
  if (options.request.current?.id !== id || options.request.current.version !== fresh.version)
    options.request.current = { id, version: fresh.version, key: crypto.randomUUID() };
  const request = options.request.current;
  try {
    storage?.setItem(options.storageKey, JSON.stringify(request));
  } catch {}
  assertCurrent();
  try {
    const next = await api.command(id, 'start', { version: request.version }, request.key);
    assertCurrent();
    clear();
    return next;
  } catch (error) {
    assertCurrent();
    if (
      error instanceof ApiClientError &&
      (error.status === 0 || error.status >= 500 || error.status === 409)
    ) {
      const recovered = await api.read(id);
      assertCurrent();
      if (recovered.status === 'in_progress') {
        clear();
        return recovered;
      }
    }
    throw error;
  }
}

'use client';

import { useEffect, useId, useRef, type ReactNode } from 'react';

export interface TransitionStep {
  label: string;
  state: 'pending' | 'active' | 'done' | 'error';
}

export interface TransitionScreenProps {
  kind: 'preparing' | 'analysis';
  title: string;
  description: string;
  detail?: string;
  steps: TransitionStep[];
  progress?: { value: number; max: number };
  error?: string;
  children?: ReactNode;
  context?: string;
}

/** Values describe completed work, never elapsed-time estimates. */
export function TransitionScreen({
  kind,
  title,
  description,
  detail,
  steps,
  progress,
  error,
  children,
  context,
}: TransitionScreenProps) {
  const titleId = useId();
  const screen = useRef<HTMLElement>(null);
  const completed = steps.filter((step) => step.state === 'done').length;
  const measured =
    progress && Number.isFinite(progress.max) && progress.max > 0 && Number.isFinite(progress.value)
      ? { max: progress.max, value: Math.min(progress.max, Math.max(0, progress.value)) }
      : steps.length
        ? { max: steps.length, value: completed }
        : null;
  const active = steps.find((step) => step.state === 'active');
  const stage = error
    ? '需要处理后继续'
    : (active?.label ??
      (completed === steps.length && steps.length
        ? kind === 'analysis'
          ? '报告已就绪'
          : '准备就绪'
        : description));

  useEffect(() => {
    const element = screen.current;
    const previousFocus =
      document.activeElement instanceof HTMLElement ? document.activeElement : null;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    element?.focus({ preventScroll: true });
    const trapFocus = (event: KeyboardEvent) => {
      if (event.key !== 'Tab' || !element) return;
      const targets = Array.from(
        element.querySelectorAll<HTMLElement>(
          'button:not([disabled]), a[href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex="0"]',
        ),
      ).filter((target) => !target.hidden && target.getAttribute('aria-hidden') !== 'true');
      const first = targets[0],
        last = targets.at(-1);
      if (!first || !last) {
        event.preventDefault();
        element.focus();
      } else if (
        event.shiftKey &&
        (document.activeElement === first || document.activeElement === element)
      ) {
        event.preventDefault();
        last.focus();
      } else if (
        !event.shiftKey &&
        (document.activeElement === last || document.activeElement === element)
      ) {
        event.preventDefault();
        first.focus();
      }
    };
    element?.addEventListener('keydown', trapFocus);
    return () => {
      document.body.style.overflow = previousOverflow;
      element?.removeEventListener('keydown', trapFocus);
      if (previousFocus?.isConnected && element?.contains(document.activeElement))
        previousFocus.focus();
    };
  }, []);

  return (
    <section
      ref={screen}
      className={`interview-transition interview-transition--${kind}${error ? ' interview-transition--error' : ''}`}
      role="dialog"
      aria-modal="true"
      aria-labelledby={titleId}
      tabIndex={-1}
    >
      <div className="interview-transition__wordmark" aria-hidden="true">
        InterviewLab
      </div>
      <div className="interview-transition__content">
        <div className="interview-transition__illustration" aria-hidden="true">
          <span className="interview-transition__halo" />
          <span className="interview-transition__shadow" />
          <div className="interview-transition__float">
            <span className="interview-transition__belt interview-transition__belt--back" />
            <div className="interview-transition__orb">
              <span className="interview-transition__surface" />
              <span className="interview-transition__sheen" />
            </div>
            <span className="interview-transition__belt interview-transition__belt--front" />
            <i className="interview-transition__dot interview-transition__dot--one" />
            <i className="interview-transition__dot interview-transition__dot--two" />
            <i className="interview-transition__dot interview-transition__dot--three" />
          </div>
        </div>
        <h1 id={titleId}>{title}</h1>
        <p
          className={`interview-transition__status${error ? ' interview-transition__status--error' : ''}`}
          role={error ? 'alert' : 'status'}
          aria-live={error ? 'assertive' : 'polite'}
          aria-atomic="true"
        >
          {error || description}
        </p>
        {context && <p className="interview-transition__context">{context}</p>}
        <div
          className="interview-transition__track"
          role="progressbar"
          aria-label={kind === 'preparing' ? '面试准备进度' : '报告分析进度'}
          aria-valuemin={measured ? 0 : undefined}
          aria-valuemax={measured?.max}
          aria-valuenow={measured?.value}
          aria-valuetext={[
            measured ? `${stage}，已完成 ${measured.value} / ${measured.max}` : stage,
            detail,
          ]
            .filter(Boolean)
            .join('。')}
        >
          <span
            className="interview-transition__fill"
            style={{ width: measured ? `${(measured.value / measured.max) * 100}%` : '0%' }}
          />
          {active && !error && <span className="interview-transition__shimmer" />}
        </div>
        {children && <div className="interview-transition__actions">{children}</div>}
      </div>
    </section>
  );
}

import type { VoiceClientEvent, VoiceServerEvent } from '@interviewlab/core';
import { apiVoiceSocket } from '../../../lib/api/http';
import { VoicePlayback } from './playback';
import {
  prepareVoiceDevices,
  resumeVoiceContext,
  voiceDeviceError,
  type PreparedVoiceDevices,
} from './devices';

export class RealtimeVoiceClient {
  private socket?: WebSocket;
  private context?: AudioContext;
  private media?: MediaStream;
  private capture?: AudioWorkletNode;
  private source?: MediaStreamAudioSourceNode;
  private playback?: VoicePlayback;
  private closed = false;
  private ready = false;
  private muted = false;
  private outputActive = false;
  private resumeCapture?: ReturnType<typeof setTimeout>;
  private aliveTimer?: ReturnType<typeof setInterval>;
  private timeout?: ReturnType<typeof setTimeout>;
  private captureTimeout?: ReturnType<typeof setTimeout>;
  private captured = false;
  private captureEpoch = 0;
  private readyEvent?: Extract<VoiceServerEvent, { type: 'ready' }>;
  private initialization?: Promise<void>;
  private preparation?: Promise<void>;
  private connection?: Promise<void>;
  private captureReady?: { resolve: () => void; reject: (error: Error) => void };
  private connectionReady?: { resolve: () => void; reject: (error: Error) => void };

  constructor(
    private readonly id: string,
    private readonly event: (event: VoiceServerEvent) => void,
    private readonly playing: (value: boolean) => void,
    private readonly disconnected: () => void,
    private readonly activity: (speaking: boolean) => void = () => {},
  ) {}
  /** Legacy callers still receive control before server/capture readiness events arrive. */
  async start(beforeConnect?: () => Promise<void>) {
    try {
      await this.initialize();
      await this.openSocket(beforeConnect);
    } catch (error) {
      this.stop();
      throw voiceDeviceError(error);
    }
  }
  /** Establish and verify local capture without sending microphone audio to the server. */
  prepare(devices?: PreparedVoiceDevices): Promise<void> {
    this.preparation ??= this.initialize(devices).then(async () => {
      if (this.closed) throw new Error('语音准备已取消。');
      if (this.captured) return;
      await new Promise<void>((resolve, reject) => {
        this.captureReady = { resolve, reject };
      });
    });
    return this.preparation;
  }
  /** Start the interview only after capture is usable, then await actual server readiness. */
  connect(beforeConnect?: () => Promise<void>): Promise<void> {
    this.connection ??= (async () => {
      try {
        await this.prepare();
        await this.openSocket(beforeConnect);
        if (this.closed) throw new Error('语音连接已取消。');
        if (this.ready && this.captured) return;
        await new Promise<void>((resolve, reject) => {
          this.connectionReady = { resolve, reject };
        });
      } catch (error) {
        this.stop();
        throw voiceDeviceError(error);
      }
    })();
    return this.connection;
  }
  private initialize(prepared?: PreparedVoiceDevices): Promise<void> {
    this.initialization ??= (async () => {
      try {
        const devices = prepared ?? (await prepareVoiceDevices(false));
        if (this.closed) {
          devices.media.getAudioTracks().forEach((track) => track.stop());
          void devices.context.close().catch(() => {});
          throw new Error('语音准备已取消。');
        }
        this.context = devices.context;
        this.media = devices.media;
        const microphone = this.media.getAudioTracks()[0];
        if (!microphone || microphone.readyState === 'ended')
          throw new Error('浏览器未提供可用麦克风音轨，请选择其他输入设备。');
        await resumeVoiceContext(this.context);
        if (this.closed) throw new Error('语音准备已取消。');
        if (this.context.state !== 'running')
          throw new Error('浏览器音频采集尚未启动，请重新开启语音。');
        await this.context.audioWorklet.addModule('/voice-capture.worklet.js');
        if (this.closed) throw new Error('语音准备已取消。');
        this.playback = new VoicePlayback(
          this.context,
          (id, playedMs, interrupted) =>
            this.send({ type: 'playback', speech_id: id, played_ms: playedMs, interrupted }),
          (playing) => this.onPlaybackState(playing),
        );
        this.capture = new AudioWorkletNode(this.context, 'interview-voice-capture');
        this.capture.onprocessorerror = () => this.fail('麦克风音频处理失败，请重新连接语音。');
        this.capture.port.onmessage = ({
          data,
        }: MessageEvent<
          ({ type: 'audio'; pcm: ArrayBuffer } | { type: 'speech_start' | 'speech_end' }) & {
            epoch?: number;
          }
        >) => {
          if (this.closed) return;
          if (data.epoch !== undefined && data.epoch !== this.captureEpoch) return;
          if (data.type === 'audio' && data.pcm instanceof ArrayBuffer && data.pcm.byteLength > 0) {
            this.captured = true;
            clearTimeout(this.captureTimeout);
            this.captureReady?.resolve();
            this.captureReady = undefined;
            this.publishReady();
          }
          const socket = this.socket;
          if (!this.ready || !socket || socket.readyState !== WebSocket.OPEN) return;
          if (data.type === 'audio') {
            if (socket.bufferedAmount > 128000) {
              this.fail('网络发送过慢，已关闭麦克风，文字草稿仍保留。');
              return;
            }
            socket.send(
              this.muted || this.outputActive ? new ArrayBuffer(data.pcm.byteLength) : data.pcm,
            );
          } else {
            if (this.muted || this.outputActive) return;
            this.activity(data.type === 'speech_start');
            this.send({ type: data.type });
          }
        };
        this.source = this.context.createMediaStreamSource(this.media);
        this.source.connect(this.capture);
        this.capture.connect(this.context.destination);
        this.captureTimeout = setTimeout(() => {
          if (!this.closed && !this.captured)
            this.fail('浏览器已授权，但没有产生麦克风音频。请更换输入设备后重新连接。');
        }, 5000);
        this.media.getAudioTracks().forEach((track) =>
          track.addEventListener('ended', () => {
            if (!this.closed) this.fail('麦克风已断开，文字草稿仍保留。');
          }),
        );
        this.context.onstatechange = () => {
          if (!this.closed && this.context?.state !== 'running')
            this.fail('浏览器音频采集已暂停，请重新开启语音。');
        };
      } catch (error) {
        this.stop();
        throw voiceDeviceError(error);
      }
    })();
    return this.initialization;
  }
  private async openSocket(beforeConnect?: () => Promise<void>) {
    if (this.closed || !this.context) throw new Error('语音准备已取消。');
    if (this.socket) return;
    if (this.context.state !== 'running') await resumeVoiceContext(this.context);
    if (this.closed || this.context.state !== 'running')
      throw new Error('浏览器音频尚未启动，请重试连接。');
    if (beforeConnect) await beforeConnect();
    if (this.closed) throw new Error('语音连接已取消。');
    const socket = (this.socket = apiVoiceSocket(`/interviews/${this.id}/voice`));
    this.timeout = setTimeout(() => this.fail('语音连接超时，请重试或使用文字。'), 15000);
    socket.onmessage = ({ data }) => {
      if (this.closed || typeof data !== 'string') return;
      try {
        const event = JSON.parse(data) as VoiceServerEvent;
        if (event.type === 'ready') {
          this.ready = true;
          clearTimeout(this.timeout);
          this.readyEvent = event;
          this.publishReady();
          return;
        }
        if (event.type === 'error' && !this.ready) {
          this.event(event);
          this.rejectPending(new Error(event.message));
          this.stop();
          this.disconnected();
          return;
        }
        if (event.type === 'speech_start') this.playback?.start(event.speech_id);
        if (event.type === 'audio') this.playback?.append(event.speech_id, event.pcm);
        if (event.type === 'speech_end') this.playback?.finish(event.speech_id);
        if (event.type === 'interrupted') this.playback?.interrupt(event.speech_id);
        if (event.type === 'submitting') {
          this.resetCapture();
          this.activity(false);
        }
        this.event(event);
      } catch {
        this.fail('语音数据异常，请重新连接或使用文字。');
      }
    };
    socket.onclose = () => {
      if (!this.closed) {
        this.rejectPending(new Error('语音连接已关闭，请重试连接。'));
        this.stop();
        this.disconnected();
      }
    };
    socket.onerror = () => this.fail('语音连接失败，请检查后端状态或重新连接。');
    this.aliveTimer = setInterval(() => this.send({ type: 'ping' }), 5000);
  }
  private rejectPending(error: Error) {
    this.captureReady?.reject(error);
    this.captureReady = undefined;
    this.connectionReady?.reject(error);
    this.connectionReady = undefined;
  }
  private publishReady() {
    if (this.readyEvent && this.captured) {
      const event = this.readyEvent;
      this.readyEvent = undefined;
      this.event(event);
      this.connectionReady?.resolve();
      this.connectionReady = undefined;
    }
  }
  send(event: VoiceClientEvent) {
    if (this.socket?.readyState === WebSocket.OPEN) this.socket.send(JSON.stringify(event));
  }
  getOutputLevel() {
    return this.playback?.getLevel() ?? 0;
  }
  interrupt() {
    this.playback?.stop(true);
    this.send({ type: 'interrupt' });
  }
  private onPlaybackState(playing: boolean) {
    if (this.closed) return;
    clearTimeout(this.resumeCapture);
    if (playing) {
      this.outputActive = true;
      this.applyCaptureState();
      this.activity(false);
      this.playing(true);
    } else {
      // Network speech_end only seals the queue. This callback runs after local playback drains.
      // A short tail also excludes speaker echo and already queued capture messages.
      this.resumeCapture = setTimeout(() => {
        if (this.closed) return;
        this.outputActive = false;
        this.applyCaptureState();
        this.playing(false);
      }, 300);
    }
  }
  private applyCaptureState() {
    this.media?.getAudioTracks().forEach((track) => {
      track.enabled = !this.muted && !this.outputActive;
    });
    this.resetCapture();
  }
  private resetCapture() {
    this.capture?.port.postMessage({ type: 'reset', epoch: ++this.captureEpoch });
  }
  setMuted(muted: boolean) {
    this.muted = muted;
    this.applyCaptureState();
    if (muted) {
      this.activity(false);
      this.send({ type: 'speech_end' });
    }
  }
  private fail(message: string) {
    if (this.closed) return;
    this.rejectPending(new Error(message));
    this.event({ type: 'error', code: 'voice_client_failed', message, retryable: true });
    this.stop();
    this.disconnected();
  }
  stop() {
    if (this.closed) return;
    this.closed = true;
    this.rejectPending(new Error('语音准备或连接已取消。'));
    this.ready = false;
    clearInterval(this.aliveTimer);
    clearTimeout(this.timeout);
    clearTimeout(this.captureTimeout);
    clearTimeout(this.resumeCapture);
    this.readyEvent = undefined;
    this.playback?.stop(true);
    this.socket?.close();
    if (this.capture) {
      this.capture.port.onmessage = null;
      this.capture.disconnect();
    }
    this.source?.disconnect();
    this.media?.getAudioTracks().forEach((track) => track.stop());
    void this.context?.close().catch(() => {});
  }
}

'use client';
import { useState } from 'react';
import {
  Mic,
  MicOff,
  Keyboard,
  PhoneOff,
  Volume2,
  Hand,
  CircleStop,
  ArrowUp,
  MessageSquare,
} from 'lucide-react';
import { Button } from '../../../components/ui/button';
import type { useInterviewVoice } from './use-voice';

export function VoiceDraftRecovery({
  voice,
}: {
  voice: Pick<ReturnType<typeof useInterviewVoice>, 'supplements' | 'dismissSupplement'>;
}) {
  const [copyStatus, setCopyStatus] = useState('');
  if (!voice.supplements?.length) return null;
  return (
    <section className="voice-call-error" aria-label="未提交的语音补充">
      <strong>有补充内容尚未提交</strong>
      <p>这段内容未加入当前回答，可先复制保存。</p>
      {voice.supplements.map((supplement) => (
        <div key={supplement.turn_id ?? 'unassigned'}>
          {supplement.question && <p>对应问题：{supplement.question}</p>}
          <p style={{ whiteSpace: 'pre-wrap', overflowWrap: 'anywhere' }}>{supplement.text}</p>
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={async () => {
              try {
                await navigator.clipboard.writeText(supplement.text);
                setCopyStatus('已复制补充内容。');
              } catch {
                setCopyStatus('暂时无法复制，可选中上方文字手动复制。');
              }
            }}
          >
            复制补充
          </Button>{' '}
          <Button
            type="button"
            variant="outline"
            size="sm"
            onClick={() => voice.dismissSupplement(supplement.turn_id)}
          >
            关闭补充提示
          </Button>
        </div>
      ))}
      <p role="status">{copyStatus}</p>
    </section>
  );
}

export function VoiceControls({
  voice,
  disabled,
  preferred = false,
}: {
  voice: ReturnType<typeof useInterviewVoice>;
  disabled: boolean;
  preferred?: boolean;
}) {
  if (!voice.display)
    return (
      <section className="voice-controls" aria-label="实时语音面试">
        <div className="voice-heading">
          <div>
            <strong>
              <Mic size={17} />
              实时语音
            </strong>
            <p>像打电话一样交流，面试官说完后自动恢复收音。</p>
          </div>
          <Button
            type="button"
            size="sm"
            disabled={disabled || !voice.capabilities?.available}
            onClick={() => void voice.start()}
          >
            <Mic size={15} />
            开启实时语音
          </Button>
        </div>
        {voice.capabilities?.reason && <p className="field-help">{voice.capabilities.reason}</p>}
        {voice.error && (
          <p className="error-inline" role="alert">
            {voice.error}
          </p>
        )}
        <VoiceDraftRecovery voice={voice} />
      </section>
    );
  const ended = voice.sessionStatus === 'completed' || voice.sessionStatus === 'failed';
  const state = ended
    ? 'ended'
    : voice.connecting
      ? 'connecting'
      : !voice.active
        ? 'idle'
        : voice.muted
          ? 'muted'
          : voice.hold
            ? 'hold'
            : voice.playing
              ? 'speaking'
              : voice.talking
                ? 'hearing'
                : voice.thinking
                  ? 'thinking'
                  : 'listening';
  const labels = {
    ended: '本场通话已结束',
    connecting: '正在连接…',
    idle: voice.sessionStatus === 'ready' ? '准备好，就开始聊吧' : '语音通话待连接',
    muted: '麦克风已静音',
    hold: '慢慢想，我在这里',
    speaking: '面试官正在说话',
    hearing: '正在听你说',
    thinking: '正在思考你的回答',
    listening: '我在听，你可以直接说话',
  };
  const silence = Math.round((voice.capabilities?.silence_ms ?? 3000) / 1000);
  return (
    <section className={`voice-call voice-call-${state}`} aria-label="语音通话">
      <div className="voice-call-topline">
        <span className="voice-call-tag">
          <span />
          {voice.active ? '通话中' : ended ? '通话已结束' : '语音面试'}
        </span>
        <span>AI 面试官</span>
      </div>
      <div className="voice-call-center">
        <div className="voice-orb-scene" aria-hidden="true">
          <div className="voice-orb-halo" />
          <div className="voice-orb">
            <span />
            <span />
            <span />
          </div>
        </div>
        <div className="voice-call-wave" aria-hidden="true">
          {[0, 1, 2, 3, 4].map((i) => (
            <i key={i} style={{ animationDelay: `${i * 0.12}s` }} />
          ))}
        </div>
        <h2 role="status" aria-live="polite">
          {labels[state]}
        </h2>
        <p>
          {voice.active
            ? voice.muted
              ? '取消静音后继续说话'
              : voice.hold
                ? '准备好后点一下“继续接话”'
                : voice.playing
                  ? '麦克风已自动暂停，听完后再回答'
                  : voice.thinking
                    ? '想到新的内容，也可以继续补充'
                    : `说完停顿约 ${silence} 秒，我会接着问`
            : ended
              ? '已提交的讲话内容保存在面试记录中'
              : preferred
                ? voice.sessionStatus === 'ready'
                  ? '点击右上角开始面试，允许麦克风后直接进入通话'
                  : '语音已断开，可重新连接继续回答'
                : '开启麦克风，直接说出你的回答'}
        </p>
      </div>
      {voice.error && (
        <p className="voice-call-error" role="alert">
          {voice.error}
        </p>
      )}
      <VoiceDraftRecovery voice={voice} />
      {!voice.active && !ended && (
        <>
          {voice.sessionStatus !== 'ready' && (
            <Button
              type="button"
              disabled={disabled || !voice.capabilities?.available}
              onClick={() => void voice.start()}
            >
              <Mic size={17} />
              连接语音
            </Button>
          )}
          <p className="voice-call-consent">
            开始语音面试时请求麦克风权限，音频实时发送至火山引擎识别。本站保存转写，不保存原始录音。
          </p>
          {voice.capabilities?.reason && <p className="field-help">{voice.capabilities.reason}</p>}
        </>
      )}
      {voice.active && (
        <div className="voice-call-buttons">
          <button
            type="button"
            className={`voice-round-button ${voice.muted ? 'is-muted' : ''}`}
            disabled={voice.connecting}
            onClick={voice.toggleMute}
            aria-label={voice.muted ? '取消静音' : '静音麦克风'}
            aria-pressed={voice.muted}
          >
            {voice.muted ? <MicOff /> : <Mic />}
            <span>{voice.muted ? '取消静音' : '静音'}</span>
          </button>
          <button
            type="button"
            className="voice-round-button"
            disabled={voice.connecting}
            onClick={voice.toggleHold}
            aria-label={voice.hold ? '继续自动接话' : '让我想想'}
            aria-pressed={voice.hold}
          >
            <Hand />
            <span>{voice.hold ? '继续接话' : '让我想想'}</span>
          </button>
          <button
            type="button"
            className="voice-round-button voice-hangup"
            onClick={voice.stop}
            aria-label="挂断语音，保留面试和记录"
          >
            <PhoneOff />
            <span>挂断语音</span>
          </button>
        </div>
      )}
      <div className="voice-call-secondary">
        {voice.active && (
          <>
            <button
              type="button"
              disabled={voice.connecting || !voice.draft.trim()}
              onClick={voice.commit}
            >
              <ArrowUp size={14} />
              我说完了
            </button>
            <button type="button" disabled={!voice.playing} onClick={voice.interrupt}>
              <CircleStop size={14} />
              停止播报
            </button>
            <button
              type="button"
              disabled={voice.connecting || voice.thinking}
              onClick={voice.repeat}
            >
              <Volume2 size={14} />
              重听
            </button>
          </>
        )}
        <button type="button" onClick={voice.switchToText}>
          <Keyboard size={14} />
          切回文字
        </button>
      </div>
      <p className="voice-call-save">
        {voice.active ? '讲话会自动转写保存，无需逐条点击发送' : '语音与文字共用同一份面试记录'}
      </p>
      <details className="voice-call-transcript">
        <summary>
          <MessageSquare size={14} />
          查看对话记录
        </summary>
        <div>
          {voice.turns.map((turn) => (
            <div key={turn.id}>
              <small>面试官</small>
              <p>{turn.text}</p>
              {turn.answer_text && (
                <>
                  <small>我 · 已保存</small>
                  <p>{turn.answer_text}</p>
                </>
              )}
            </div>
          ))}
          {voice.draft && (
            <div>
              <small>我 · 尚未提交</small>
              <p>{voice.draft}</p>
            </div>
          )}
          {!voice.turns.length && <p>开始面试后，这里会保留对话记录。</p>}
        </div>
      </details>
    </section>
  );
}

export type PreparedVoiceDevices = {
  context: AudioContext;
  media: MediaStream;
  camera: MediaStream | null;
};

/** Autoplay policy may leave resume pending until another gesture; surface a recoverable state. */
export async function resumeVoiceContext(context: AudioContext): Promise<void> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  try {
    await Promise.race([
      context.resume(),
      new Promise<void>((_resolve, reject) => {
        timer = setTimeout(
          () => reject(new Error('浏览器尚未允许声音，请点击重试设备检查。')),
          4000,
        );
      }),
    ]);
    if (context.state !== 'running') throw new Error('浏览器音频尚未启动，请点击重试设备检查。');
  } finally {
    clearTimeout(timer);
  }
}

export function voiceDeviceError(error: unknown, video = false): Error {
  if (error instanceof DOMException && error.name === 'NotAllowedError')
    return new Error(
      video
        ? '未获得麦克风或摄像头权限，请在浏览器地址栏允许后重试。'
        : '未获得麦克风权限，请在浏览器地址栏允许麦克风后重试。',
    );
  if (error instanceof DOMException && error.name === 'NotFoundError')
    return new Error('找不到所选麦克风或摄像头，请选择其他输入设备后重试。');
  if (error instanceof DOMException && error.name === 'NotReadableError')
    return new Error('浏览器无法读取媒体设备，请检查设备占用并重新选择输入设备。');
  if (error instanceof DOMException && error.name === 'OverconstrainedError')
    return new Error('所选媒体设备已不可用，请选择其他输入设备后重试。');
  return error instanceof Error ? error : new Error('无法启动媒体设备。');
}

/** Call directly from the launch click, before waiting for creation or preparation requests. */
export async function prepareVoiceDevices(video: boolean): Promise<PreparedVoiceDevices> {
  if (!navigator.mediaDevices?.getUserMedia || !window.AudioWorkletNode || !window.isSecureContext)
    throw new Error('当前浏览器无法使用实时语音，请使用新版 Chrome 并通过本机地址或 HTTPS 访问。');
  const context = new AudioContext();
  let media: MediaStream | undefined;
  let camera: MediaStream | null = null;
  try {
    await resumeVoiceContext(context);
    media = await navigator.mediaDevices.getUserMedia({
      audio: {
        channelCount: 1,
        echoCancellation: true,
        noiseSuppression: true,
        autoGainControl: true,
      },
      video: false,
    });
    if (!media.getAudioTracks().length)
      throw new Error('浏览器未提供麦克风音轨，请选择其他输入设备。');
    if (video) {
      camera = await navigator.mediaDevices.getUserMedia({
        video: { width: { ideal: 640 }, height: { ideal: 480 }, facingMode: 'user' },
        audio: false,
      });
      if (!camera.getVideoTracks().length)
        throw new Error('浏览器未提供摄像头画面，请选择其他设备。');
    }
    return { context, media, camera };
  } catch (error) {
    media?.getTracks().forEach((track) => track.stop());
    camera?.getTracks().forEach((track) => track.stop());
    await context.close().catch(() => {});
    throw voiceDeviceError(error, video);
  }
}

export function releaseVoiceDevices(devices: PreparedVoiceDevices): void {
  devices.media.getTracks().forEach((track) => track.stop());
  devices.camera?.getTracks().forEach((track) => track.stop());
  if (devices.context.state !== 'closed') void devices.context.close().catch(() => {});
}

/** Schedules PCM incrementally, with an identity fence against late audio after interruption. */
export class VoicePlayback {
  private current?: {
    id: string;
    sources: Set<AudioBufferSourceNode>;
    segments: { start: number; duration: number; levels: number[] }[];
    sealed: boolean;
  };
  private nextTime = 0;
  constructor(
    private readonly context: AudioContext,
    private readonly receipt: (id: string, playedMs: number, interrupted: boolean) => void,
    private readonly state: (playing: boolean) => void,
  ) {}
  start(id: string) {
    this.stop(true);
    this.current = { id, sources: new Set(), segments: [], sealed: false };
    this.nextTime = this.context.currentTime + 0.03;
    this.state(true);
  }
  append(id: string, base64: string) {
    const clip = this.current;
    if (!clip || clip.id !== id || clip.sealed) return;
    const binary = atob(base64);
    if (binary.length % 2 || binary.length > 1024 * 1024) throw new Error('Invalid PCM');
    const pcm = new DataView(Uint8Array.from(binary, (c) => c.charCodeAt(0)).buffer);
    if (!binary.length) return;
    const audio = this.context.createBuffer(1, binary.length / 2, 24000);
    const channel = audio.getChannelData(0);
    for (let i = 0; i < channel.length; i++) channel[i] = pcm.getInt16(i * 2, true) / 32768;
    const start = Math.max(this.context.currentTime + 0.015, this.nextTime);
    if (start - this.context.currentTime > 60) throw new Error('Audio backlog');
    const source = this.context.createBufferSource();
    source.buffer = audio;
    source.connect(this.context.destination);
    clip.sources.add(source);
    const levels: number[] = [];
    for (let offset = 0; offset < channel.length; offset += 480) {
      const end = Math.min(channel.length, offset + 480);
      let power = 0;
      for (let i = offset; i < end; i++) power += channel[i] ** 2;
      levels.push(Math.min(1, Math.sqrt(power / (end - offset)) * 5));
    }
    clip.segments.push({ start, duration: audio.duration, levels });
    source.onended = () => {
      source.disconnect();
      clip.sources.delete(source);
      if (this.current === clip && clip.sealed && clip.sources.size === 0) this.stop(false);
    };
    source.start(start);
    this.nextTime = start + audio.duration;
  }
  /** Read the currently audible envelope, not queued/network audio. */
  getLevel() {
    const now = this.context.currentTime;
    const segment = this.current?.segments.find(
      (s) => now >= s.start && now < s.start + s.duration,
    );
    return segment?.levels[Math.floor((now - segment.start) / 0.02)] ?? 0;
  }
  finish(id: string) {
    if (this.current?.id !== id) return;
    this.current.sealed = true;
    if (!this.current.sources.size) this.stop(false);
  }
  interrupt(id: string | null) {
    if (id === null || this.current?.id === id) this.stop(true);
  }
  stop(interrupted = true) {
    const clip = this.current;
    this.current = undefined;
    if (!clip) return;
    const playedMs = clip.segments.reduce(
      (sum, segment) =>
        sum +
        Math.max(0, Math.min(segment.duration, this.context.currentTime - segment.start)) * 1000,
      0,
    );
    for (const source of clip.sources) {
      source.onended = null;
      try {
        source.stop();
      } catch {}
      source.disconnect();
    }
    this.state(false);
    this.receipt(clip.id, Math.round(playedMs), interrupted);
  }
}

'use client';
import { useEffect, useRef, useState } from 'react';
import type { Interview, VoiceCapabilities, VoiceServerEvent } from '@interviewlab/core';
import { apiRequest } from '../../../lib/api/http';
import { RealtimeVoiceClient } from './client';
import type { PreparedVoiceDevices } from './devices';

export interface UnsubmittedVoiceSupplement {
  turn_id: string | null;
  question: string | null;
  text: string;
}
export function routeVoiceTranscript(
  event: Extract<VoiceServerEvent, { type: 'transcript' }>,
  view: Pick<Interview, 'turns'> | null,
  onDraft: (text: string) => void,
  preserve: (supplement: UnsubmittedVoiceSupplement) => void,
) {
  if (event.turn_id && event.turn_id === view?.turns.at(-1)?.id) {
    onDraft(event.text);
  } else if (event.text.trim()) {
    preserve({
      turn_id: event.turn_id,
      question: view?.turns.find((turn) => turn.id === event.turn_id)?.text ?? null,
      text: event.text,
    });
  }
}

export function useInterviewVoice(options: {
  id: string;
  view: Interview | null;
  draft: string;
  onDraft: (text: string) => void;
  onView: (view: Interview) => void;
}) {
  const latest = useRef(options);
  latest.current = options;
  const confirmedView = useRef(options.view);
  if (
    !confirmedView.current ||
    !options.view ||
    options.view.id !== confirmedView.current.id ||
    options.view.version >= confirmedView.current.version
  )
    confirmedView.current = options.view;
  const client = useRef<RealtimeVoiceClient | null>(null);
  const clientId = useRef('');
  const prepared = useRef<Promise<void> | null>(null);
  const [capabilities, setCapabilities] = useState<VoiceCapabilities | null>(null);
  const [active, setActive] = useState(false);
  const [connecting, setConnecting] = useState(false);
  const [playing, setPlaying] = useState(false);
  const [thinking, setThinking] = useState(false);
  const [talking, setTalking] = useState(false);
  const [hold, setHold] = useState(false);
  const [error, setError] = useState('');
  const [muted, setMuted] = useState(false);
  const [display, setDisplay] = useState(false);
  const [supplements, setSupplements] = useState<UnsubmittedVoiceSupplement[]>([]);
  useEffect(() => {
    setSupplements([]);
  }, [options.id]);
  const modeInitialized = useRef('');
  useEffect(() => {
    if (!options.view || modeInitialized.current === options.view.id) return;
    modeInitialized.current = options.view.id;
    setDisplay(options.view.configuration.interaction_mode === 'realtime_voice');
  }, [options.view]);
  const pending = useRef<{ turn: string; text: string; expected: string } | null>(null);
  useEffect(() => {
    if (!options.id) return;
    const effectId = options.id;
    const controller = new AbortController();
    void apiRequest<VoiceCapabilities>(`/interviews/${options.id}/voice/capabilities`, {
      signal: controller.signal,
    })
      .then((value) => {
        if (!controller.signal.aborted) setCapabilities(value);
      })
      .catch(() => {
        if (!controller.signal.aborted) setError('无法检查语音服务，请确认后端连接正常。');
      });
    return () => {
      controller.abort();
      if (clientId.current === effectId) {
        client.current?.stop();
        client.current = null;
        prepared.current = null;
      }
    };
  }, [options.id]);
  function stop() {
    client.current?.stop();
    client.current = null;
    prepared.current = null;
    clientId.current = '';
    setActive(false);
    setConnecting(false);
    setPlaying(false);
    setThinking(false);
    setTalking(false);
    setHold(false);
    setMuted(false);
  }
  const status = options.view?.status;
  useEffect(() => {
    if (status && !['ready', 'in_progress'].includes(status)) {
      stop();
    }
  }, [status]);
  function createConnection(id: string) {
    const connection = new RealtimeVoiceClient(
      id,
      (event: VoiceServerEvent) => {
        if (client.current !== connection) return;
        if (event.type === 'ready') {
          setConnecting(false);
          setError('');
        }
        if (event.type === 'transcript') {
          routeVoiceTranscript(
            event,
            confirmedView.current,
            latest.current.onDraft,
            (supplement) => {
              // ASR partial/final events are cumulative text for the same captured turn.
              setSupplements((current) => [
                ...current.filter((entry) => entry.turn_id !== supplement.turn_id),
                supplement,
              ]);
            },
          );
        }
        if (event.type === 'submitting') {
          const turn = confirmedView.current?.turns.at(-1);
          pending.current = {
            turn: event.turn_id,
            text: event.text,
            expected:
              turn?.answer_status === 'answered'
                ? [turn.answer_text, event.text].filter(Boolean).join('/n')
                : event.text,
          };
          setThinking(true);
          setTalking(false);
        }
        if (event.type === 'interview') {
          const submitted = pending.current;
          const previousTurn = confirmedView.current?.turns.at(-1)?.id;
          // The next transcript can arrive before React renders this interview event.
          if (!confirmedView.current || event.interview.version >= confirmedView.current.version)
            confirmedView.current = event.interview;
          latest.current.onView(event.interview);
          if (
            submitted &&
            event.interview.turns.some(
              (t) =>
                t.id === submitted.turn &&
                t.answer_status === 'answered' &&
                t.answer_text === submitted.expected,
            )
          ) {
            if (previousTurn === submitted.turn && latest.current.draft === submitted.text)
              latest.current.onDraft('');
            pending.current = null;
          }
        }
        if (event.type === 'status') setThinking(event.state === 'thinking');
        if (event.type === 'error' && event.code !== 'voice_previous_draft')
          setError(event.message);
      },
      setPlaying,
      () => {
        if (client.current !== connection) return;
        stop();
        setError((previous) => previous || '语音连接已关闭，草稿仍保留，可重新连接或使用文字。');
      },
      setTalking,
    );
    client.current = connection;
    clientId.current = id;
    return connection;
  }
  async function start(beforeConnect?: () => Promise<void>) {
    if (client.current) return;
    if (latest.current.draft.trim()) {
      setError('当前有未提交的文字草稿，请先提交或清空，再开启实时语音。');
      return;
    }
    setError('');
    setDisplay(true);
    setConnecting(true);
    setActive(true);
    pending.current = null;
    const connection = createConnection(latest.current.id);
    try {
      await connection.start(beforeConnect);
    } catch (e) {
      if (client.current === connection) {
        stop();
        setError(e instanceof Error ? e.message : '无法启动实时语音。');
      }
    }
  }
  async function prepareFor(id: string, devices: PreparedVoiceDevices) {
    if (client.current && clientId.current === id && prepared.current) return prepared.current;
    stop();
    setError('');
    setDisplay(true);
    const connection = createConnection(id);
    const work = (async () => {
      const available = await apiRequest<VoiceCapabilities>(`/interviews/${id}/voice/capabilities`);
      if (client.current !== connection) throw new Error('设备准备已取消。');
      setCapabilities(available);
      if (!available.available)
        throw new Error(available.reason || '当前语音服务不可用，可改用文字。');
      await connection.prepare(devices);
    })();
    prepared.current = work;
    try {
      await work;
    } catch (e) {
      const isCurrent = client.current === connection;
      if (isCurrent) stop();
      const message = e instanceof Error ? e.message : '设备检查失败，请重试。';
      if (isCurrent) setError(message);
      throw new Error(message);
    }
  }
  async function connectPrepared(beforeConnect?: () => Promise<void>) {
    const connection = client.current;
    if (!connection || !prepared.current) throw new Error('请先完成设备检查。');
    await prepared.current;
    setError('');
    setDisplay(true);
    setConnecting(true);
    setActive(true);
    try {
      await connection.connect(beforeConnect);
    } catch (e) {
      if (client.current === connection) stop();
      const message = e instanceof Error ? e.message : '语音连接失败，请重试。';
      setError(message);
      throw new Error(message);
    }
  }
  return {
    getOutputLevel: () => client.current?.getOutputLevel() ?? 0,
    capabilities,
    display,
    muted,
    sessionStatus: status,
    turns: options.view?.turns ?? [],
    draft: options.draft,
    active,
    connecting,
    playing,
    thinking,
    talking,
    hold,
    error,
    supplements,
    dismissSupplement(turnId: string | null) {
      setSupplements((current) => current.filter((entry) => entry.turn_id !== turnId));
    },
    start,
    stop,
    suspend() {
      const connection = client.current;
      if (!connection) return () => {};
      connection.send({ type: 'hold', enabled: true });
      connection.setMuted(true);
      setHold(true);
      setMuted(true);
      return () => {
        if (client.current !== connection) return;
        connection.send({ type: 'hold', enabled: hold });
        connection.setMuted(muted);
        setHold(hold);
        setMuted(muted);
      };
    },
    prepareFor,
    connectPrepared,
    switchToText() {
      stop();
      setDisplay(false);
    },
    toggleMute() {
      client.current?.setMuted(!muted);
      setMuted(!muted);
    },
    status: connecting
      ? '正在连接语音…'
      : playing
        ? '面试官正在说话，麦克风暂时关闭'
        : thinking
          ? '面试官正在思考，可继续补充'
          : talking
            ? '正在转写，停顿后将自动提交'
            : '正在听，你可以直接说话',
    commit() {
      setHold(false);
      client.current?.send({ type: 'commit' });
    },
    interrupt() {
      client.current?.interrupt();
      setPlaying(false);
    },
    repeat() {
      client.current?.send({ type: 'repeat' });
    },
    toggleHold() {
      setHold(!hold);
      client.current?.send({ type: 'hold', enabled: !hold });
    },
  };
}

