            <PhoneOff />
            <span>结束面试</span>
          </button>
        )}
        {p.ended && p.reportHref && <Link href={p.reportHref}>查看复盘</Link>}
      </footer>
    </div>
  );
}

import type { ApiError } from '@interviewlab/core';

export class ApiClientError extends Error {
  constructor(
    public readonly status: number,
    public readonly detail: ApiError,
  ) {
    super(detail.message);
    this.name = 'ApiClientError';
  }
}
export const SESSION_CHANGED = 'interviewlab:session-changed';
export const SESSION_INVALIDATED = 'interviewlab:session-invalidated';
export function notifySessionChanged() {
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new Event(SESSION_CHANGED));
    if (typeof BroadcastChannel !== 'undefined') {
      const channel = new BroadcastChannel(SESSION_CHANGED);
      channel.postMessage('refresh');
      channel.close();
    }
  }
}
export interface ApiRequestOptions {
  method?: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
  body?: unknown;
  headers?: HeadersInit;
  idempotencyKey?: string;
  signal?: AbortSignal;
  timeoutMs?: number;
}
function isApiError(value: unknown): value is ApiError {
  if (!value || typeof value !== 'object') return false;
  const error = value as Record<string, unknown>;
  return (
    typeof error.code === 'string' &&
    typeof error.message === 'string' &&
    typeof error.retryable === 'boolean' &&
    typeof error.request_id === 'string'
  );
}
/** Browser-only HTTP transport. No token storage, redirects or automatic write retries. */
export function createApiClient(fetcher: typeof fetch = (...args) => fetch(...args)) {
  return async function request<T>(path: string, options: ApiRequestOptions = {}): Promise<T> {
    const target = new URL('/api/v1' + path, 'http://same-origin.invalid');
    if (
      !path.startsWith('/') ||
      path.startsWith('//') ||
      path.includes('//') ||
      target.hash ||
      !target.pathname.startsWith('/api/v1/')
    )
      throw new Error('Use a path relative to /api/v1');
    const headers = new Headers(options.headers);
    headers.set('accept', 'application/json');
    if (options.body !== undefined) headers.set('content-type', 'application/json');
    if (options.idempotencyKey) headers.set('Idempotency-Key', options.idempotencyKey);
    const timeout = AbortSignal.timeout(options.timeoutMs ?? 10000);
    const signal = options.signal ? AbortSignal.any([options.signal, timeout]) : timeout;
    let response: Response | undefined;
    let data: unknown;
    try {
      response = await fetcher(target.pathname + target.search, {
        method: options.method ?? 'GET',
        headers,
        body: options.body === undefined ? undefined : JSON.stringify(options.body),
        credentials: 'same-origin',
        cache: 'no-store',
        redirect: 'error',
        signal,
      });
      if (response.status === 204) return undefined as T;
      if (response.headers.get('content-type')?.includes('application/json'))
        data = await response.json().catch((error) => {
          if (signal.aborted) throw error;
          return undefined;
        });
    } catch {
      if (options.signal?.aborted) throw options.signal.reason;
      throw new ApiClientError(response?.status ?? 0, {
        code: timeout.aborted ? 'request_timeout' : 'backend_unavailable',
        message: timeout.aborted ? '请求超时，请稍后重试。' : '暂时无法连接服务，请稍后重试。',
        retryable: true,
        request_id: response?.headers.get('x-request-id') ?? '',
      });
    }
    if (!response.ok) {
      if (response.status === 401 && !path.startsWith('/auth/') && typeof window !== 'undefined')
        window.dispatchEvent(new Event(SESSION_INVALIDATED));
      throw new ApiClientError(
        response.status,
        isApiError(data)
          ? data
          : {
              code: 'http_error',
              message: '请求未能完成，请稍后重试。',
              retryable: response.status >= 500 || response.status === 429,
              request_id: response.headers.get('x-request-id') ?? '',
            },
      );
    }
    if (data === undefined)
      throw new ApiClientError(response.status, {
        code: 'invalid_response',
        message: '服务返回了无法识别的响应。',
        retryable: false,
        request_id: response.headers.get('x-request-id') ?? '',
      });
    return data as T;
  };
}
export const apiRequest = createApiClient();

/** Same-origin cookie transport for server events; no separate identity or token client. */
export function apiEvents(path: string): EventSource {
  const url = new URL('/api/v1' + path, window.location.origin);
  if (
    !path.startsWith('/') ||
    path.startsWith('//') ||
    path.includes('//') ||
    url.origin !== window.location.origin ||
    !url.pathname.startsWith('/api/v1/')
  )
    throw new Error('Use a relative API event path');
  return new EventSource(url.pathname + url.search);
}

/** Same-origin Cookie-authenticated voice channel, through the existing API proxy. */
export function apiVoiceSocket(path: string): WebSocket {
  const url = new URL('/api/v1' + path, window.location.origin);
  if (
    !path.startsWith('/') ||
    path.startsWith('//') ||
    path.includes('//') ||
    url.hash ||
    url.origin !== window.location.origin ||
    !url.pathname.startsWith('/api/v1/')
  )
    throw new Error('Use a relative API voice path');
  url.protocol = url.protocol === 'https:' ? 'wss:' : 'ws:';
  return new WebSocket(url);
}

import { Pool, type PoolClient } from 'pg';
import { drizzle, type NodePgDatabase } from 'drizzle-orm/node-postgres';
import type { BackendConfig } from '../foundation/config';
import * as foundationSchema from './schema';
import * as authSchema from '../modules/accounts/auth-schema';
import * as interviewSchema from '../modules/interviews/schema';
import * as materialSchema from '../modules/resumes/schema';
import * as reportSchema from '../modules/reports/schema';
const schema = { ...foundationSchema, ...authSchema, ...interviewSchema, ...reportSchema, ...materialSchema };
export interface Transaction {
  client: PoolClient;
  db: NodePgDatabase<typeof schema>;
}
export function createDatabase(config: BackendConfig) {
  if (!config.DATABASE_URL) throw new Error('DATABASE_URL is required');
  const pool = new Pool({
    connectionString: config.DATABASE_URL,
    max: config.DATABASE_POOL_SIZE,
    connectionTimeoutMillis: config.DATABASE_CONNECT_TIMEOUT_MS,
    idleTimeoutMillis: 10000,
    statement_timeout: 10000,
  });
  // Idle clients can fail independently; prevent an unhandled EventEmitter error.
  pool.on('error', () => {
    /* Readiness probes and subsequent operations report failure. */
  });
  const db = drizzle(pool, { schema });
  return {
    pool,
    db,
    async transaction<T>(work: (tx: Transaction) => Promise<T>): Promise<T> {
      const client = await pool.connect();
      try {
        await client.query('BEGIN');
        const result = await work({ client, db: drizzle(client, { schema }) });
        await client.query('COMMIT');
        return result;
      } catch (error) {
        await client.query('ROLLBACK').catch(() => {});
        throw error;
      } finally {
        client.release();
      }
    },
    async ready(workerStaleMs: number, authentication = false) {
      try {
        // Missing migrations are not considered ready.
        await pool.query('SELECT id FROM tasks LIMIT 0');
        if (authentication) {
          for (const table of [
            'auth_users',
            'auth_sessions',
            'auth_accounts',
            'auth_verifications',
            'auth_rate_limits',
          ])
            await pool.query(`SELECT id FROM ${table} LIMIT 0`);
        }
        const result = await pool.query(
          "SELECT EXISTS (SELECT 1 FROM worker_heartbeats WHERE last_seen_at > now() - $1 * interval '1 millisecond') AS worker",
          [workerStaleMs],
        );
        return { database: true, worker: Boolean(result.rows[0].worker) };
      } catch {
        return { database: false, worker: false };
      }
    },
    close: () => pool.end(),
  };
}
export type Database = ReturnType<typeof createDatabase>;

import { z } from 'zod';

const optionalUrl = z.preprocess(
  (value) => (value === '' ? undefined : value),
  z.string().url().optional(),
);
const environmentSchema = z.object({
  NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
  API_HOST: z.string().min(1).default('127.0.0.1'),
  API_PORT: z.coerce.number().int().min(1).max(65535).default(3001),
  PUBLIC_ORIGIN: z.string().url().default('http://127.0.0.1:3000'),
  AUTH_ENABLED: z
    .enum(['true', 'false'])
    .default('false')
    .transform((value) => value === 'true'),
  BETTER_AUTH_SECRET: z.preprocess(
    (value) => (value === '' ? undefined : value),
    z.string().min(32).optional(),
  ),
  LOG_LEVEL: z.enum(['fatal', 'error', 'warn', 'info', 'debug', 'trace', 'silent']).default('info'),
  DATABASE_URL: optionalUrl,
  KNOWLEDGE_DATABASE_URL: optionalUrl,
  KNOWLEDGE_PREVIEW: z
    .enum(['true', 'false'])
    .default('false')
    .transform((v) => v === 'true'),
  EMBEDDING_MODEL: z.literal('ecnu-embedding-small').default('ecnu-embedding-small'),
  DATABASE_POOL_SIZE: z.coerce.number().int().min(1).max(50).default(10),
  DATABASE_CONNECT_TIMEOUT_MS: z.coerce.number().int().min(100).max(30000).default(3000),
  BODY_LIMIT_BYTES: z.coerce.number().int().min(1024).max(10485760).default(1048576),
  WORKER_CONCURRENCY: z.coerce.number().int().min(1).max(32).default(3),
  WORKER_PREPARATION_CONCURRENCY: z.coerce.number().int().min(1).max(8).default(1),
  WORKER_REPORT_CONCURRENCY: z.coerce.number().int().min(1).max(32).default(3),
  WORKER_POLL_MS: z.coerce.number().int().min(100).max(60000).default(1000),
  WORKER_HEARTBEAT_MS: z.coerce.number().int().min(100).max(30000).default(5000),
  WORKER_STALE_MS: z.coerce.number().int().min(1000).max(300000).default(30000),
  LLM_BASE_URL: optionalUrl.default('https://chat.ecnu.edu.cn/open/api/v1'),
  LLM_API_KEY: z
    .string()
    .optional()
    .transform((value) => value?.trim()),
  LLM_MODEL: z.string().min(1).max(200).default('ecnu-plus'),
  LLM_OUTPUT_MODE: z.enum(['json_object', 'json_schema']).default('json_object'),
  LLM_TIMEOUT_MS: z.coerce.number().int().min(100).max(45000).default(25000),
  VOICE_ENABLED: z
    .enum(['true', 'false'])
    .default('false')
    .transform((v) => v === 'true'),
  VOLC_ASR_API_KEY: z
    .string()
    .optional()
    .transform((v) => v?.trim()),
  VOLC_TTS_API_KEY: z
    .string()
    .optional()
    .transform((v) => v?.trim()),
  VOLC_ASR_RESOURCE_ID: z.string().min(1).default('volc.seedasr.sauc.duration'),
  VOLC_TTS_RESOURCE_ID: z.string().min(1).default('seed-tts-2.0'),
  VOLC_TTS_SPEAKER: z.string().min(1).default('zh_male_m191_uranus_bigtts'),
  VOICE_SILENCE_MS: z.coerce.number().int().min(1200).max(6000).default(1800),
});
export type BackendConfig = z.infer<typeof environmentSchema>;
export class ConfigurationError extends Error {}

export function loadConfig(env: Record<string, unknown> = process.env): BackendConfig {
  const parsed = environmentSchema.safeParse(env);
  // Never include environment values or Zod input objects in configuration errors.
  if (!parsed.success)
    throw new ConfigurationError(
      'Invalid configuration: ' +
        parsed.error.issues.map((issue) => issue.path.join('.') + ' ' + issue.message).join('; '),
    );
  const config = parsed.data;
  if (config.KNOWLEDGE_PREVIEW && config.NODE_ENV === 'production')
    throw new ConfigurationError('Knowledge preview is unavailable in production');
  if (config.KNOWLEDGE_DATABASE_URL && !/^postgres(ql)?://///.test(config.KNOWLEDGE_DATABASE_URL))
    throw new ConfigurationError('Knowledge database requires PostgreSQL');
  if (config.LLM_BASE_URL) {
    const endpoint = new URL(config.LLM_BASE_URL);
    if (
      !['https:', 'http:'].includes(endpoint.protocol) ||
      endpoint.username ||
      endpoint.password ||
      endpoint.search ||
      endpoint.hash
    )
      throw new ConfigurationError(
        'Invalid configuration: LLM_BASE_URL must be an HTTP API base URL without credentials, query or fragment',
      );
  }
  const origin = new URL(config.PUBLIC_ORIGIN);
  if (!['http:', 'https:'].includes(origin.protocol) || origin.origin !== config.PUBLIC_ORIGIN) {
    throw new ConfigurationError(
      'Invalid configuration: PUBLIC_ORIGIN must be an HTTP origin without a path',
    );
  }
  if (config.AUTH_ENABLED && (!config.DATABASE_URL || !config.BETTER_AUTH_SECRET)) {
    throw new ConfigurationError(
      'Invalid configuration: authentication requires DATABASE_URL and BETTER_AUTH_SECRET',
    );
  }
  if (config.AUTH_ENABLED && config.NODE_ENV === 'production' && origin.protocol !== 'https:') {
    throw new ConfigurationError('Invalid configuration: production authentication requires HTTPS');
  }
  if (config.DATABASE_URL && !/^postgres(ql)?://///.test(config.DATABASE_URL)) {
    throw new ConfigurationError('Invalid configuration: DATABASE_URL must use PostgreSQL');
  }
  if (config.WORKER_STALE_MS <= config.WORKER_HEARTBEAT_MS * 2) {
    throw new ConfigurationError(
      'Invalid configuration: WORKER_STALE_MS must exceed two heartbeat intervals',
    );
  }
  return config;
}

import type { ApiError } from '@interviewlab/core';
import type { FastifyInstance } from 'fastify';
export class ServiceError extends Error {
  constructor(
    public readonly code: string,
    public readonly statusCode: number,
    message: string,
    public readonly retryable = false,
  ) {
    super(message);
  }
}
export const unavailable = (name: string) =>
  new ServiceError('capability_unavailable', 501, name + ' is not connected');

export function installErrorHandler(app: FastifyInstance) {
  app.setErrorHandler(
    (
      error: Error & { validation?: unknown; statusCode?: number; code?: string },
      request,
      reply,
    ) => {
      let failure = error instanceof ServiceError ? error : undefined;
      if (!failure && (error.validation || error.statusCode === 400))
        failure = new ServiceError(
          'unsupported_input',
          400,
          'Request does not match the API contract',
        );
      if (!failure && error.statusCode === 413)
        failure = new ServiceError('unsupported_input', 413, 'Request body is too large');
      if (!failure && error.statusCode === 415)
        failure = new ServiceError('unsupported_input', 415, 'Unsupported media type');
      if (!failure) {
        // Do not log error.message/stack: database and provider errors can contain private input.
        request.log.error({ error_type: error.name }, 'Unhandled server error');
        failure = new ServiceError('internal_error', 500, 'Internal server error');
      }
      const body: ApiError = {
        code: failure.code,
        message: failure.message,
        retryable: failure.retryable,
        request_id: request.id,
      };
      void reply.code(failure.statusCode).send(body);
    },
  );
  app.setNotFoundHandler((request, reply) => {
    const body: ApiError = {
      code: 'not_found',
      message: 'Resource not found',
      retryable: false,
      request_id: request.id,
    };
    void reply.code(404).send(body);
  });
}

import { z } from 'zod';
import type { AuthSession, SignInInput, SignUpInput } from '@interviewlab/core';
import type { FastifyInstance } from 'fastify';
import type { ZodTypeProvider } from 'fastify-type-provider-zod';
import { errorSchema } from '../../foundation/schemas';
import { unavailable } from '../../foundation/errors';
import type { AuthService } from './auth-service';

const sessionSchema = z.object({
  user: z.object({ id: z.string(), name: z.string(), email: z.email() }),
  roles: z.array(z.enum(['student', 'content_maintainer', 'operator'])),
  expires_at: z.iso.datetime(),
}) satisfies z.ZodType<AuthSession>;
export const signInSchema = z.strictObject({
  email: z
    .email()
    .max(254)
    .transform((email) => email.toLowerCase()),
  password: z.string().min(1).max(128),
  rememberMe: z.boolean().optional(),
}) satisfies z.ZodType<SignInInput>;
export const signUpSchema = z.strictObject({
  name: z.string().trim().min(1).max(100),
  email: z
    .email()
    .max(254)
    .transform((email) => email.toLowerCase()),
  password: z.string().min(9).max(20),
}) satisfies z.ZodType<SignUpInput>;

export async function registerAuthRoutes(instance: FastifyInstance, auth?: AuthService) {
  const app = instance.withTypeProvider<ZodTypeProvider>();
  const errors = {
    400: errorSchema,
    401: errorSchema,
    403: errorSchema,
    409: errorSchema,
    429: errorSchema,
    501: errorSchema,
    503: errorSchema,
  };
  app.get(
    '/auth/session',
    {
      schema: {
        tags: ['authentication'],
        response: { 200: sessionSchema.nullable(), 501: errorSchema, 503: errorSchema },
      },
    },
    async (request) => {
      if (!auth) throw unavailable('Authentication');
      return auth.session(request.headers);
    },
  );
  app.post(
    '/auth/sign-up/email',
    {
      schema: {
        tags: ['authentication'],
        body: signUpSchema,
        response: { 200: z.object({ success: z.literal(true) }), ...errors },
      },
    },
    async (request, reply) => {
      if (!auth) throw unavailable('Authentication');
      const cookies = await auth.signUp(request, request.body);
      if (cookies.length) reply.header('set-cookie', cookies);
      return { success: true as const };
    },
  );
  app.post(
    '/auth/sign-in/email',
    {
      schema: {
        tags: ['authentication'],
        body: signInSchema,
        response: { 200: z.object({ success: z.literal(true) }), ...errors },
      },
    },
    async (request, reply) => {
      if (!auth) throw unavailable('Authentication');
      const cookies = await auth.signIn(request, request.body);
      if (cookies.length) reply.header('set-cookie', cookies);
      return { success: true as const };
    },
  );
  app.post(
    '/auth/sign-out',
    {
      schema: {
        tags: ['authentication'],
        body: z.strictObject({}),
        response: { 200: z.object({ success: z.literal(true) }), ...errors },
      },
    },
    async (request, reply) => {
      if (!auth) throw unavailable('Authentication');
      const cookies = await auth.signOut(request);
      if (cookies.length) reply.header('set-cookie', cookies);
      return { success: true as const };
    },
  );
}

import { betterAuth } from 'better-auth/minimal';
import { drizzleAdapter } from '@better-auth/drizzle-adapter';
import type { AuthSession, SignInInput, SignUpInput } from '@interviewlab/core';
import { eq } from 'drizzle-orm';
import type { FastifyRequest } from 'fastify';
import type { IdentityProvider } from '../../foundation/auth';
import type { BackendConfig } from '../../foundation/config';
import type { Database } from '../../database/connection';
import { ServiceError } from '../../foundation/errors';
import { authAccount, authRateLimit, authSession, authUser, authVerification } from './auth-schema';

export function createAuthService(database: Database, config: BackendConfig) {
  if (!config.AUTH_ENABLED || !config.BETTER_AUTH_SECRET)
    throw new Error('Authentication is not configured');
  const auth = betterAuth({
    appName: 'InterviewLab',
    baseURL: config.PUBLIC_ORIGIN,
    basePath: '/api/v1/auth',
    secret: config.BETTER_AUTH_SECRET,
    database: drizzleAdapter(database.db, {
      provider: 'pg',
      transaction: true,
      schema: {
        user: authUser,
        session: authSession,
        account: authAccount,
        verification: authVerification,
        rateLimit: authRateLimit,
      },
    }),
    emailAndPassword: {
      enabled: true,
      disableSignUp: false,
      autoSignIn: true,
      minPasswordLength: 9,
      maxPasswordLength: 20,
    },
    trustedOrigins: [config.PUBLIC_ORIGIN],
    user: {
      additionalFields: {
        role: {
          type: ['student', 'content_maintainer', 'operator'],
          defaultValue: 'student',
          input: false,
        },
      },
    },
    session: {
      expiresIn: 60 * 60 * 24 * 7,
      disableSessionRefresh: true,
      cookieCache: { enabled: false },
    },
    advanced: {
      cookiePrefix: 'interviewlab',
      useSecureCookies: config.PUBLIC_ORIGIN.startsWith('https://'),
      defaultCookieAttributes: { httpOnly: true, sameSite: 'lax', path: '/' },
      ipAddress: { ipAddressHeaders: ['x-interviewlab-client-ip'] },
    },
    rateLimit: {
      enabled: true,
      storage: 'database',
      window: 60,
      max: 100,
      customRules: {
        '/sign-in/email': { window: 60, max: 10 },
        '/sign-up/email': { window: 60, max: 5 },
      },
    },
    // Provider failures may contain private data. Our HTTP layer logs only a safe error type.
    logger: { disabled: true },
    telemetry: { enabled: false },
  });
  const session = async (headers: FastifyRequest['headers']): Promise<AuthSession | null> => {
    const cookieHeaders = new Headers();
    if (headers.cookie) cookieHeaders.set('cookie', headers.cookie);
    try {
      const result = await auth.api.getSession({
        headers: cookieHeaders,
        query: { disableCookieCache: true },
      });
      if (!result) return null;
      return {
        user: { id: result.user.id, name: result.user.name, email: result.user.email },
        roles: [result.user.role],
        expires_at: result.session.expiresAt.toISOString(),
      };
    } catch {
      throw new ServiceError(
        'dependency_unavailable',
        503,
        'Authentication is temporarily unavailable',
        true,
      );
    }
  };
  const invoke = async (
    path: 'sign-in/email' | 'sign-up/email' | 'sign-out',
    request: FastifyRequest,
    body: unknown,
  ) => {
    const headers = new Headers({
      'content-type': 'application/json',
      'x-interviewlab-client-ip': request.ip,
    });
    if (request.headers.cookie) headers.set('cookie', request.headers.cookie);
    if (request.headers.origin) headers.set('origin', request.headers.origin);
    let response: Response;
    try {
      response = await auth.handler(
        new Request(`${config.PUBLIC_ORIGIN}/api/v1/auth/${path}`, {
          method: 'POST',
          headers,
          body: JSON.stringify(body),
        }),
      );
    } catch {
      throw new ServiceError(
        'dependency_unavailable',
        503,
        'Authentication is temporarily unavailable',
        true,
      );
    }
    if (!response.ok) {
      const status = response.status;
      if (path === 'sign-up/email' && status === 422) {
        // Concurrent signups can hit the unique constraint inside Better Auth's transaction.
        const result = (await response.json().catch(() => null)) as { code?: string } | null;
        if (result?.code === 'USER_ALREADY_EXISTS_USE_ANOTHER_EMAIL')
          throw new ServiceError('email_already_exists', 409, '该邮箱已注册，请登录。');
        if (result?.code === 'FAILED_TO_CREATE_USER') {
          try {
            const existing = await database.db
              .select({ id: authUser.id })
              .from(authUser)
              .where(eq(authUser.email, (body as SignUpInput).email))
              .limit(1);
            if (existing.length)
              throw new ServiceError('email_already_exists', 409, '该邮箱已注册，请登录。');
          } catch (error) {
            if (error instanceof ServiceError) throw error;
          }
          throw new ServiceError(
            'dependency_unavailable',
            503,
            '注册暂时不可用，请稍后重试。',
            true,
          );
        }
      }
      if (status === 401)
        throw new ServiceError('unauthorized', 401, 'Email or password is incorrect');
      if (status === 429)
        throw new ServiceError('rate_limited', 429, 'Too many attempts; try again later', true);
      if (status === 403)
        throw new ServiceError('forbidden', 403, 'Authentication request forbidden');
      if (status >= 500)
        throw new ServiceError(
          'dependency_unavailable',
          503,
          'Authentication is temporarily unavailable',
          true,
        );
      throw new ServiceError('unsupported_input', 400, 'Invalid authentication request');
    }
    // Never return Better Auth's token-bearing JSON to the browser.
    return response.headers.getSetCookie();
  };
  return {
    session,
    authenticate: async (headers) => {
      const current = await session(headers);
      return current ? { owner_id: current.user.id, roles: current.roles } : null;
    },
    signIn: (request: FastifyRequest, input: SignInInput) =>
      invoke('sign-in/email', request, input),
    signUp: (request: FastifyRequest, input: SignUpInput) =>
      invoke('sign-up/email', request, input),
    signOut: (request: FastifyRequest) => invoke('sign-out', request, {}),
  } satisfies IdentityProvider & Record<string, unknown>;
}
export type AuthService = ReturnType<typeof createAuthService>;

import { createAllRoleKnowledge } from './knowledge/all-roles';
import { createResumeAnalysis } from './resumes/analysis';
import { createWorkflowModels, type WorkflowModels } from './interviews/workflow-models';
import { createInterviewPreparation } from './interviews/preparation';
import { createInterviewAgent } from './interviews/agent';
import { createMaterialsService } from './resumes/service';
import type { InterviewKnowledgeProvider, InterviewKnowledgeRuntime } from '@interviewlab/core';
import type { Database } from '../database/connection';
import type { BackendConfig } from '../foundation/config';
import { ServiceError } from '../foundation/errors';
import type { InterviewAgent } from './interviews/model-analysis';
import { createInterviewsService, type InterviewReportHooks } from './interviews/service';
import { createReportsService } from './reports/service';
import { interviewsModule } from './interviews/routes';
import { reportsModule } from './reports/routes';
import type { TaskRow } from '../tasks/service';
import type { VoiceProvider } from './interviews/voice/volcengine';

export interface InterviewRuntimeOptions {
  workflowModels?: WorkflowModels;
  voiceProvider?: VoiceProvider;
  agent?: InterviewAgent;
  knowledge?: InterviewKnowledgeProvider;
  realtimeKnowledge?: InterviewKnowledgeRuntime;
  log?: (entry: object) => void;
  onFinalize?: InterviewReportHooks['seal'];
}
export function createInterviewRuntime(
  database: Database,
  config: BackendConfig,
  options: InterviewRuntimeOptions = {},
) {
  const knowledge = createAllRoleKnowledge(config);
  const content = options.knowledge ?? options.realtimeKnowledge ?? knowledge;
  const models = options.workflowModels ?? createWorkflowModels(config, fetch, options.log);
  const resumeAnalysis = createResumeAnalysis(database, config, models);
  const materials = createMaterialsService(database, resumeAnalysis, true);
  const agent =
    options.agent ??
    createInterviewAgent(config, options.log);
  const interviews = createInterviewsService(
    database,
    content,
    agent,
    {
      prepare: options.onFinalize ? undefined : (tx, state) => reports.prepare(tx, state),
      seal: options.onFinalize ?? ((tx, state) => reports.seal(tx, state)),
      erase: (tx, owner, id) => reports.erase(tx, owner, id),
    },
    options.realtimeKnowledge ?? {
      ...knowledge,
      read: (c) => knowledge.read(c),
      profiles: (c) => knowledge.profiles(c),
      prefetch: (c,k,m) => knowledge.prefetch(c,k,m),
      context: (c,k,m,a,s) => knowledge.context(c,k,m,a,s),
    },
    async (owner,id,version)=>{const versions=await materials.versions(owner,id);const material=versions.find(v=>v.version===version&&v.kind==='resume'&&v.confirmed);if(!material)throw new ServiceError('unsupported_input',400,'请选择本人已确认的简历版本');return material;},
    {
      initialize: (identity,id) => preparation.initialize(identity,id),
      request: (identity,id,body,key) => preparation.request(identity,id,body,key),
    },
  );
  const preparation=createInterviewPreparation(database,config,content,materials,resumeAnalysis,models);
  const reports = createReportsService(database, interviews, agent);
  return {
    agent,
    materials,
    close: async () => {
      await interviews.streams.close();
      await knowledge.close();
    },
    interviews,
    reports,
    modules: [
      interviewsModule(interviews, { config, provider: options.voiceProvider }),
      reportsModule(reports),
    ],
    handlers: { ...interviews.handlers, ...reports.handlers, ...resumeAnalysis.handlers, ...preparation.handlers },
    async maintain() {
      await preparation.maintain();
      await interviews.maintain();
      await reports.maintain();
    },
    async isCancelled(task: Readonly<TaskRow>) {
      const input = task.payload as {
        interview_id?: string;
        generation_id?: string;
        report_id?: string;
        report_version?: number;
        comparison_id?: string;
        version?: number;
      };
      try {
        if (task.type === 'preparation.plan.v1' && input.interview_id) {
          const state=await interviews.read({owner_id:task.owner_id,roles:[]},input.interview_id);
          return state.status !== 'ready' || state.preparation?.task_id !== task.id;
        }
        if (input.interview_id) {
          if (task.type === 'reports.evaluate.v1') return await reports.isEvaluationCancelled(task);
          const current = await interviews.read(
            { owner_id: task.owner_id, roles: [] },
            input.interview_id,
          );
          if (input.report_id) {
            const report = await reports.get(
              { owner_id: task.owner_id, roles: [] },
              input.interview_id,
            );
            return report.id !== input.report_id || report.version !== input.report_version;
          }
          return Boolean(
            input.generation_id &&
              (current.generation_id !== input.generation_id || current.status !== 'in_progress'),
          );
        }
        if (input.comparison_id) {
          const current = await reports.getComparison(
            { owner_id: task.owner_id, roles: [] },
            input.comparison_id,
          );
          return current.version !== input.version;
        }
        return false;
      } catch (error) {
        if (error instanceof ServiceError && error.statusCode === 404) return true;
        throw error;
      }
    },
  };
}

import type { InterviewAgent } from './model-analysis';
import { assertQuestion, createModelAnalysis } from './model-analysis';
import { createStreamingAgent } from './streaming-agent';
import { langChainFetch } from './model';
import { checkedGraph } from './graph';
import type { BackendConfig } from '../../foundation/config';
import { ServiceError } from '../../foundation/errors';

/** The single interview runtime: LangChain transport and a bounded LangGraph turn workflow. */
export function createInterviewAgent(
  config: BackendConfig,
  log: (entry: object) => void = () => {},
  fetcher: typeof fetch = fetch,
): InterviewAgent {
  const transport = langChainFetch(config, fetcher);
  const graphBase = createModelAnalysis(config, transport, log);
  const realtime = createStreamingAgent(graphBase, config, log, transport);
  return {
    ...graphBase,
    async advance(interview, snapshot, clarify, signal, repair, context) {
      if (snapshot.runtime_version !== 'graph-v1')
        throw new ServiceError('unsupported_input', 409, '该面试使用已停用的运行时，请新建面试；原记录仍可查看');
      return checkedGraph(
        'interview_advance',
        { interview, snapshot, context },
        {
          prepare: (input) => {
            if (!input.context || !input.snapshot.knowledge.agent_release)
              throw new ServiceError('invalid_state', 409, '面试准备上下文缺失');
            return input;
          },
          generate: (input) =>
            realtime.advance(
              input.interview,
              input.snapshot,
              clarify,
              signal,
              repair,
              input.context,
            ),
          validate: (raw) => {
            const result = raw as Awaited<ReturnType<InterviewAgent['advance']>>;
            if (result.question) assertQuestion(result.question, snapshot, interview.turns);
            return result;
          },
        },
        signal,
        log,
      );
    },
  };
}

import type {
  Interview,
  InterviewTurn,
  InterviewTopic,
  InterviewConversationState,
  InterviewReplyAct,
  InterviewTopicBoundary,
} from '@interviewlab/core';
import { ServiceError } from '../../foundation/errors';
const refusal =
  /不方便|不想(?:回答|说|聊|谈|透露|介绍)|不愿(?:回答|说|聊|谈|透露)|不便(?:回答|说|聊|谈|透露)|不(?:聊|谈).{0,8}(?:这个|背景|学校|项目)|(?:这个问题|这个话题|这题).{0,6}(?:跳过|不答|保密)|换(?:个|一个)话题|涉及保密|别(?:再)?(?:问|聊|谈)(?:这个|这题)|这个不说了|跳过这个问题/;
export function replyAct(text: string): InterviewReplyAct {
  const value = text.replace(/[/s，,。.!！?？～~、]/g, '').toLowerCase();
  if (!/没有不方便|不是不方便/.test(text) && refusal.test(text)) return 'decline_topic';
  if (/^(?:你好|您好|老师好|面试官好|面试官你好|hi|hello|哈喽)+$/.test(value)) return 'greeting';
  if (
    /^(?:嗯|恩|好的|好|可以|ok|开始吧|准备好了|有|是的|对|会一点|一点点|继续|继续吧)+$/.test(value)
  )
    return 'acknowledgement';
  if (
    /^(?:我)?(?:不太|完全)?(?:不知道|不清楚|不会|不懂|没学过|没接触过|没了解过|想不起来)/.test(
      value,
    ) &&
    !/(?:但|不过|只是|然而)/.test(value)
  )
    return 'dont_know';
  return 'answer';
}
export function questionTopic(
  turn: Pick<InterviewTurn, 'text' | 'stage' | 'topic'>,
): InterviewTopic {
  const sentences = turn.text
    .split(/[。！!；;]/)
    .map((s) => s.trim())
    .filter(Boolean);
  const text = (sentences.at(-1) ?? turn.text).replace(
    /^.{0,35}(?:跳过|不展开|先放下|不再聊)[，,：:]/s*/,
    '',
  );
  if (/薪资|薪酬|待遇|期望收入/.test(text)) return 'expectations';
  if (/到岗|入职|出勤|实习.{0,6}(?:时长|多久|几个月)|工作地点|城市意向/.test(text))
    return 'availability';
  if (
    /学校|学历|毕业院校|教育背景|学习背景|自我介绍|介绍.{0,5}自己/.test(text) ||
    turn.stage === 'introduction'
  )
    return 'personal_background';
  if (
    /(?:应聘|岗位|方向).{0,10}(?:原因|动机)|为什么.{0,10}(?:应聘|选择|前端)|岗位动机/.test(
      text + ' ' + turn.topic,
    )
  )
    return 'motivation';
  if (/学过|课程|练习|接触过|最近.{0,8}技术|熟悉.{0,8}(?:哪些|什么)|学习(?:过程|内容)/.test(text))
    return 'learning_experience';
  if (/项目|游戏|你负责|本人职责|你的分工/.test(text)) return 'project';
  if (turn.stage === 'technical') return 'technical';
  if (turn.stage === 'business') return 'business';
  if (turn.stage === 'behavioral') return 'collaboration';
  return 'other';
}
function namedTopic(text: string): InterviewTopic | null {
  if (/薪资|薪酬|待遇|期望收入/.test(text)) return 'expectations';
  if (/到岗|入职|出勤|实习安排|工作地点/.test(text)) return 'availability';
  if (/学校|学历|背景|个人信息|自我介绍/.test(text)) return 'personal_background';
  if (/应聘原因|岗位动机|选择.{0,8}原因/.test(text)) return 'motivation';
  if (/项目|游戏|实习细节/.test(text)) return 'project';
  if (/课程|练习|学过|学习经历/.test(text)) return 'learning_experience';
  return null;
}
export function conversationPolicy(interview: Interview): InterviewConversationState {
  const boundaries: InterviewTopicBoundary[] = [];
  let lastAct: InterviewReplyAct = 'answer';
  for (const turn of interview.turns) {
    if (turn.answer_status !== 'answered' || !turn.answer_text?.trim()) continue;
    const text = turn.answer_text;
    lastAct = replyAct(text);
    const reopened =
      /(?:现在|还是|可以|愿意|继续).{0,6}(?:聊|谈|介绍|说|回答).{0,12}(?:学校|背景|项目|课程|练习|原因|薪资|薪酬|待遇|到岗|出勤|工作地点)|(?:背景|项目|课程|练习|薪资|薪酬|待遇|到岗|出勤|工作地点).{0,6}(?:现在可以聊|可以继续)/.test(
        text,
      )
        ? namedTopic(text)
        : null;
    if (reopened) lastAct = 'answer';
    if (reopened) {
      for (let i = boundaries.length - 1; i >= 0; i--)
        if (boundaries[i].topic === reopened) boundaries.splice(i, 1);
    }
    if (lastAct !== 'decline_topic' || reopened) continue;
    const explicitTopic = namedTopic(text);
    const topic = explicitTopic ?? questionTopic(turn);
    const scope =
      /只(?:是)?这(?:一)?题|跳过这题|这个问题.{0,4}(?:跳过|不答)/.test(text) ||
      ['technical', 'business', 'other'].includes(topic) ||
      (topic === 'project' && !explicitTopic)
        ? ('question' as const)
        : ('topic' as const);
    const from = Math.max(0, text.search(refusal) - 30);
    const boundary: InterviewTopicBoundary = {
      topic,
      scope,
      question_id: turn.id,
      question: turn.text,
      evidence_ref: {
        turn_id: turn.id,
        revision: turn.revision,
        quote: text.slice(from, from + 240),
      },
    };
    const previous = boundaries.findIndex(
      (b) =>
        b.topic === topic && b.scope === scope && (scope === 'topic' || b.question_id === turn.id),
    );
    if (previous >= 0) boundaries.splice(previous, 1);
    boundaries.push(boundary);
  }
  return { last_act: lastAct, boundaries: boundaries.slice(-18) };
}
const topicForStep: Record<string, InterviewTopic> = {
  introduction: 'personal_background',
  alternative_experience: 'learning_experience',
  learning_basics: 'learning_experience',
  project_discovery: 'project',
  motivation: 'motivation',
};
export function blockedPreparation(step: string, state: InterviewConversationState) {
  const topic = topicForStep[step];
  return !!topic && state.boundaries.some((b) => b.scope === 'topic' && b.topic === topic);
}
export function assertConversationQuestion(
  text: string,
  state: InterviewConversationState,
  complete: boolean,
) {
  if (!complete) return;
  if (
    state.boundaries.length &&
    /如果方便|是否方便|方便.{0,6}(?:聊|介绍|说|分享)|(?:聊|介绍|说|分享).{0,10}方便吗/.test(text)
  )
    throw new ServiceError(
      'invalid_model_output',
      502,
      '应接受话题边界并直接转场，不反复征求方便与否',
    );
  const topic = questionTopic({ text, stage: undefined, topic: '' });
  if (state.boundaries.some((b) => b.scope === 'topic' && b.topic === topic))
    throw new ServiceError('invalid_model_output', 502, '不能继续索取候选人已拒绝的话题');
  if (
    state.boundaries.some(
      (b) => b.scope === 'question' && b.question.replace(//s/g, '') === text.replace(//s/g, ''),
    )
  )
    throw new ServiceError('invalid_model_output', 502, '当前问题已被候选人拒绝');
}

import { z } from 'zod';
import type { FastifyInstance } from 'fastify';
import type { ModuleContext } from '../contracts';
import type { LiveInterviewsService } from './service';
import { interviewConfigSchema } from './schemas';
import { errorSchema } from '../../foundation/schemas';
export function registerInterviewEvents(
  app: FastifyInstance,
  context: ModuleContext,
  ready: () => LiveInterviewsService,
) {
  app.get(
    '/interview-profiles',
    {
      schema: {
        tags: ['interviews'],
        querystring: interviewConfigSchema.pick({ job: true, career_stage: true }),
        response: {
          200: z.object({
            version: z.string(),
            default_type: z.string(),
            profiles: z.array(
              z.object({
                id: z.string(),
                version: z.string(),
                type: z.string(),
                label: z.string(),
                goals: z.array(z.string()),
              }),
            ),
          }),
          401: errorSchema,
          503: errorSchema,
        },
      },
    },
    async (request) => {
      const query = request.query as { job: string; career_stage: 'internship' | 'campus' };
      return ready().profiles(query);
    },
  );
  app.get<{ Params: { id: string }; Querystring: { generation_id: string } }>(
    '/interviews/:id/events',
    {
      schema: {
        tags: ['interviews'],
        params: z.object({ id: z.uuid() }),
        querystring: z.object({ generation_id: z.uuid() }),
        response: { 401: errorSchema, 404: errorSchema },
      },
    },
    async (request, reply) => {
      const service = ready();
      const initial = await context.requireIdentity(request);
      await service.read(initial, request.params.id);
      let closed = false,
        working = false,
        dirty = false,
        unsubscribe: (() => void) | undefined;
      let heartbeat: ReturnType<typeof setInterval> | undefined;
      let last = '';
      const close = () => {
        if (closed) return;
        closed = true;
        clearInterval(heartbeat);
        unsubscribe?.();
        if (!reply.raw.writableEnded) reply.raw.end();
      };
      const send = (type: string, value: unknown) => {
        if (closed || reply.raw.destroyed) return;
        const ok = reply.raw.write(`event: ${type}/ndata: ${JSON.stringify(value)}/n/n`);
        if (!ok) close();
      };
      const refresh = async () => {
        if (working) {
          dirty = true;
          return;
        }
        working = true;
        try {
          do {
            dirty = false;
            if (closed) return;
            const identity = await context.requireIdentity(request);
            if (identity.owner_id !== initial.owner_id) {
              send('invalidated', {});
              close();
              return;
            }
            const view = await service.read(identity, request.params.id);
            if (
              view.generation_id !== request.query.generation_id ||
              view.status !== 'in_progress'
            ) {
              send('invalidated', {});
              close();
              return;
            }
            if (view.generation_status === 'failed') {
              send('failed', {});
              close();
              return;
            }
            if (view.generation_status !== 'pending') {
              send('committed', { interview: view });
              close();
              return;
            }
            const preview = await service.streams.read(view.id, request.query.generation_id);
            if (preview) {
              const value = JSON.stringify(preview);
              if (last !== value) {
                last = value;
                send('question_delta', { generation_id: view.generation_id, ...preview });
              }
            }
          } while (dirty && !closed);
        } catch {
          send('invalidated', {});
          close();
        } finally {
          working = false;
        }
      };
      unsubscribe = await service.streams.subscribe(request.params.id, () => {
        void refresh();
      });
      if (reply.raw.destroyed) {
        unsubscribe();
        return;
      }
      reply.hijack();
      reply.raw.writeHead(200, {
        'Content-Type': 'text/event-stream; charset=utf-8',
        'Cache-Control': 'no-store, no-transform',
        'X-Accel-Buffering': 'no',
        Connection: 'keep-alive',
        'X-Content-Type-Options': 'nosniff',
        'X-Request-Id': request.id,
      });
      reply.raw.on('close', close);
      send('status', { generation_id: request.query.generation_id, state: 'pending' });
      heartbeat = setInterval(() => {
        void refresh().then(() => {
          if (!closed) reply.raw.write(': heartbeat/n/n');
        });
      }, 5000);
      await refresh();
    },
  );
}

import {
  replyAct,
  conversationPolicy,
  blockedPreparation,
  assertConversationQuestion,
} from './conversation';
import type {
  Interview,
  InterviewEvidence,
  InterviewExperienceGrounding,
  InterviewConversationState,
  ResumeAnalysis,
} from '@interviewlab/core';
import { ServiceError } from '../../foundation/errors';

const project = /项目|游戏|网站|网页|页面|系统|平台|小程序|应用|app|课程设计|毕设|个人博客/i;
const switches =
  /换(?:一)?个项目|另一个(?:项目|游戏|网站|系统|平台)|另外(?:一)?个(?:项目|游戏|网站|系统|平台)|再说一个项目|还有(?:一)?个(?:项目|游戏|网站|系统|平台)/;
const purpose =
  /玩法|玩家|用户(?:可以|需要|能够|通过)|用于|用来|目的是|目标是|解决.{1,20}(?:问题|需求)|支持.{1,25}(?:浏览|选课|下单|预约|聊天|上传|查询|闯关)|控制.{1,20}(?:角色|小球|人物)|跑酷|闯关/;
const ownership =
  /我(?:本人|自己|主要|独立|只|仅|仅仅)?(?:负责|承担|实现|编写|设计|开发|搭建)|(?:^|[，,；;])(?:自己|本人)(?:负责|承担|实现|编写|设计|开发|搭建)|由我|我一个人|我独立|都是我|个人项目/;
const generic = /(?:很多|多个|几个|一些|不少|各种)(?:的)?项目/;
function bareLabel(text: string) {
  const value = text.replace(/[/s。！？!?，,]/g, '');
  return /^(?:我(?:做过|做了|参与过)?|是|做了|做过)?(?:一(?:个|款))?(?:3d|2d|三维)?(?:小)?(?:游戏|项目|网站|系统|平台|小程序|应用|app)$/i.test(
    value,
  );
}
function hasDescription(quote: string) {
  if (bareLabel(quote)) return false;
  if (purpose.test(quote)) return true;
  if (generic.test(quote)) return false;
  // Conservative recovery for existing sessions: retain an actual work description,
  // not a project category or a technology name by itself.
  return (
    project.test(quote) &&
    /负责|实现|编写|设计|开发|搭建/.test(quote) &&
    !/(?:整个|全部|这个|一个)(?:的)?项目[。！]?/s*$/.test(quote) &&
    !/(?:3D|2D|三维)?小游戏/.test(quote)
  );
}
function hasRole(quote: string) {
  return ownership.test(quote) && !generic.test(quote) && !bareLabel(quote);
}
function explicitlyUnavailable(text: string) {
  if (/(?:但|不过|只是).{0,20}(?:做过|有|参与).{0,12}(?:项目|练习|课程设计)/.test(text))
    return false;
  return /(?:没有|没做过|没参与过|还没做过)[^，,。；;]{0,12}(?:任何项目|相关项目|项目经历|实际项目|项目|相关实践|相关经历|完整(?:的)?(?:系统|应用)|相关(?:系统|应用))|不想.{0,6}(?:聊项目|谈项目)/.test(
    text,
  );
}
function declinesScenario(text: string) {
  return /(?:不要|别|不想|不需要|不希望).{0,12}(?:假设|情境|场景)/.test(text);
}
function requestsScenario(text: string) {
  if (declinesScenario(text)) return false;
  return /(?:请|想|希望|可以|直接|改成|换成).{0,12}(?:假设题|情境题|场景题|假设场景)|(?:假设题|情境题|场景题).{0,8}(?:吧|就行|可以)/.test(
    text,
  );
}
function openingOnly(text: string) {
  const value = text.replace(/[/s，,。.!！?？～~、]/g, '').toLowerCase();
  if (
    /^(?:你好|您好|老师好|面试官好|面试官你好|hi|hello|哈喽|嗯|恩|好的|好|可以|ok|开始吧|准备好了)+$/.test(
      value,
    )
  )
    return true;
  return (
    !/专业|学生|开发|工程师|工作|学过|学习/.test(value) &&
    /^(?:你好|您好)?我(?:叫|是)[/u4e00-/u9fffA-Za-z]{1,12}$/.test(value)
  );
}
function learningBackground(turns: Interview['turns']): InterviewEvidence | null {
  let result: InterviewEvidence | null = null;
  for (const turn of turns)
    for (const raw of turn.answer_text?.match(/[^，,。！？；;/n]+/g) ?? []) {
      const quote = raw.trim();
      if (replyAct(quote) !== 'answer') continue;
      if (/(?:没|没有|不曾|未|不).{0,4}(?:学过|学习|接触|了解|使用过)/.test(quote)) continue;
      const match =
        /(?:学过|学了|正在学|学习过|接触过|练习过|熟悉|使用过|了解|做过.{0,8}(?:练习|作业))(.+)/.exec(
          quote,
        );
      const intention =
        /(?:想|希望|打算|准备|计划).{0,4}(?:了解|学习|接触|练习|熟悉|使用|自学)/.exec(quote);
      if (intention && (!match || match.index >= intention.index)) continue;
      if (
        !match &&
        !/零基础|没学过|没接触过|完全不会/.test(quote) &&
        /学过|学习|课程|练习|接触|熟悉/.test(turn.text) &&
        !openingOnly(quote) &&
        !/^(?:没有|不知道|不会|还没有|没学过|没接触过|一点|一些|基础|有|学过|接触过|做过|是的|对|会一点|一点点)$/.test(
          quote,
        )
      ) {
        result = { turn_id: turn.id, revision: turn.revision, quote: quote.slice(0, 240) };
        continue;
      }
      if (
        !match ||
        /^(?:一点|一些|一点点|皮毛|基础|一些基础|相关知识|一些内容)[。！]?$/.test(match[1].trim())
      )
        continue;
      const from = Math.max(0, (match.index ?? 0) - 20);
      result = { turn_id: turn.id, revision: turn.revision, quote: quote.slice(from, from + 240) };
    }
