            const task = await tx.client.query(
              'SELECT status,attempts,max_attempts,error_code FROM tasks WHERE id=$1',
              [state.view.task_id],
            );
            const t = task.rows[0];
            if (
              t?.status === 'failed' &&
              (t.attempts >= t.max_attempts || t.error_code === 'unsupported_task_type')
            ) {
