    goalOptions = (
      grounding.learning_background ? ['understanding', 'learning'] : ['learning', 'understanding']
    ).filter(
      (g) =>
        !(g === 'learning' && blocked.has('learning_experience')) &&
        !(g === 'understanding' && blocked.has('technical')),
