    snapshot,
    context,
    semantic,
    modern,
    isHR,
    grounding,
    policy,
    pacing,
    missingFeedback,
    canFinish,
    sourceOptions,
    anchors,
    goalOptions,
    release,
    last,
  } = plan;
  const maxAnchor = Math.max(0, anchors.length - 1),
    maxSource = Math.max(0, sourceOptions.length - 1);
  const actionNames = { f: 'follow_up', n: 'next', e: 'finish', c: 'clarify' } as const;
  const actions = clarify
    ? (['c'] as const)
