  const otherOpportunityIndices = priorityIndices.filter(
    (index) =>
      !currentOpportunity.some((dimension) =>
        (FEEDBACK_INTERVIEW_GOALS[dimension.key] as readonly string[]).includes(goalOptions[index]),
      ),
  );
