    semantic &&
    !isHR &&
    pacing.remaining_seconds > policy.closing_seconds &&
    grounding.next_step !== 'introduction' &&
    remainingMain > 0 &&
    remainingMain <= missingNext.length &&
    priorityIndices.length
      ? otherOpportunityIndices.length
        ? otherOpportunityIndices
        : priorityIndices
      : allGoalIndices;
