        output_rules:
          modern && !semantic
            ? 'b为简短中性承接，无需要时空串，不得说好习惯、思路清晰等评价；q必须向候选人提出实际问题，不能只复述回答。d为决策原因，a=f时只能用probe_gap或clarify_once，a=n时用其他原因。a=f仅在o=0且值得继续时使用；o=1/2/3应转场，澄清后无信息不再追同一缺口。'
            : undefined,
        round_policy:
          interview.configuration.interview_type === 'hr'
            ? '本轮是HR面。自我介绍后了解岗位选择依据，按招聘阶段了解实际安排及薪资期望，有时间再了解协作和反思，不考察专业实现。'
            : interview.configuration.interview_type === 'business_scenario'
              ? '本轮是业务面，围绕用户任务、优先级、约束与结果，不考察代码实现。'
              : '依据当前目标自然交流',
        experience_context: grounding,
        confirmed_resume:
          snapshot.runtime_version === 'graph-v1'
            ? (snapshot.resume_analysis ?? null)
            : snapshot.personal_material,
        preparation_plan: snapshot.preparation_plan
          ? {
              goals: snapshot.preparation_plan.goals,
              limitations: snapshot.preparation_plan.limitations,
            }
          : undefined,
        goal_options: semantic ? goalContracts : goalOptions,
        ...(semantic
          ? {
              next_goal_indices: nextGoalIndices,
              follow_up_goal_indices: followUpGoalIndices,
              current_question_opportunity: {
                goal: currentGoal ?? null,
                dimensions: currentOpportunity.map((dimension) => dimension.key),
                meaning: 'scheduling_only_not_observed_evidence',
              },
            }
          : {}),
        competencies: semantic
          ? undefined
          : release.competencies.filter((x) => goalOptions.includes(x.id)),
        memory: context.memory
          ? {
              focus: context.memory.focus,
              observations: context.memory.observations,
              claims: context.memory.claims.slice(-6).map((c) => c.text),
              asked_intents: context.memory.asked_intents,
            }
          : null,
        knowledge: knowledgeChunks,
        missing_reason: context.retrieval.missing_reason,
        source_options: sourceOptions,
        anchors,
        required_feedback_coverage: missingFeedback.map((d) => ({
          dimension: d.short,
          goals: FEEDBACK_INTERVIEW_GOALS[d.key],
          ...(semantic
            ? {
                goal_indices: goalContracts
                  .filter((goal) => goal.target_dimensions.includes(d.key))
                  .map((goal) => goal.index),
              }
            : {}),
        })),
        coverage_instructions: isHR
          ? '只评价实际观察，不要求补齐六维，不为专业基础转问技术。'
          : '必须主动为六维提供实际考察机会。required_feedback_coverage是当前回答分析前的缺口；先输出v，再用v和h更新缺口，最后选decision.g。当h充分性s或到达边界时，从缺口中删去goal_indices与v相交的维度；remaining_main小于等于剩余非表达缺口数时，n必须选择仍缺维度的g。理解与验证同属专业基础，已经在本轮v考察基础后，不可再选另一个基础目标挤占其他缺口。next_goal_indices是更新前的可选范围，不代表都值得继续选。memory.focus和current_purpose只是先前意图，不能把未问的维度算covered。严格按所选goal_options条目的evidence_wanted和boundary生成q，不能选tradeoffs却只问验证步骤。表达沟通由实际解释观察，不凭问候或单个事实填覆盖。每次只问一个信息点，尊重不会、未参与和拒绝，时间和边界优先。',
        current_question: last.text,
        current_purpose: last.purpose,
        current_stage: last.stage,
        current_answer: last.answer_text,
        clarify,
        can_finish: canFinish,
        remaining_main:
          mainQuestionLimit(interview.configuration.duration_minutes) - last.main_question_index,
        remaining_follow_up: 2 - last.follow_up_index,
      }),
    },
  ];
}
function createAdvanceChecks(plan: AdvancePlan, output: AdvanceSchemas) {
  const {
    interview,
    snapshot,
    context,
    semantic,
    modern,
    isHR,
    grounding,
    policy,
    pacing,
    anchors,
    goalOptions,
    last,
    sourceOptions,
  } = plan;
  const {
    states,
    observableGoals,
    missingNext,
    remainingMain,
    materialIndicesSchema,
    sourceIndicesSchema,
    resumeFacts,
  } = output;
  const assessed = (control: Control): InterviewResponseAssessment | undefined => control.response;
  const statusFor = (control: Control) => {
    const response = assessed(control);
    return response ? responseObservation(response) : states[control.o ?? 0];
  };
  const observedGoalsFor = (control: Control) => {
    if (!semantic) return [context.memory?.focus ?? 'contribution'];
    const indices = control.v ?? [];
    if (new Set(indices).size !== indices.length)
      throw new ServiceError('invalid_model_output', 502, '实际观察目标重复');
    const response = assessed(control);
    if (
      indices.length &&
      (response?.response_eligibility !== 'answer' ||
        control.e === null ||
        last.stage === 'introduction')
    )
      throw new ServiceError('invalid_model_output', 502, '未作答或自我介绍不能填充能力目标');
    return indices.map((index) => observableGoals[index]);
  };
  const recoveringIntroduction = (control: Control) => {
    const response = assessed(control);
    return response
      ? needsIntroduction(response, interview, context.memory)
      : grounding.next_step === 'introduction';
  };
  const groundingFor = (control: Control) => {
    if (recoveringIntroduction(control))
      return { ...grounding, next_step: 'introduction' as const, discovery_required: false };
    if (
      semantic &&
      goalOptions[control.g] !== 'contribution' &&
      grounding.next_step === 'project_discovery'
    )
      return { ...grounding, next_step: 'interview' as const, discovery_required: false };
    return grounding;
  };
  const check = (control: Control) => {
    const response = assessed(control);
    const observedGoals = observedGoalsFor(control);
    if (response) {
      assertResponseAssessment(response, last.answer_text);
      if (response.response_eligibility === 'non_answer' && control.e !== null)
        throw new ServiceError('invalid_model_output', 502, '未作答不产生回答证据');
      if (
        response.response_eligibility === 'answer' &&
        last.answer_status === 'answered' &&
        control.e === null
      )
        throw new ServiceError('invalid_model_output', 502, '有效回答需关联当前原文');
      if (
        control.a === 'f' &&
        (response.continuation === 'at_limit' ||
          (response.response_eligibility === 'answer' && response.sufficiency !== 'needs_detail'))
      )
        throw new ServiceError('invalid_model_output', 502, '当前内容已充分或已到回答边界，应转场');
    }
    if (
      control.e !== null &&
      (!anchors[control.e] || !evidenceMatches(anchors[control.e], interview.turns))
    )
      throw new ServiceError('invalid_model_output', 502, '引用下标无效');
    if (modern && !semantic && control.a === 'f' && 'o' in control && control.o !== 0)
      throw new ServiceError('invalid_model_output', 502, '当前话题已收束，应转场');
    if (
      control.a === 'f' &&
      (!response || response.response_eligibility === 'answer') &&
      (control.e === null || anchors[control.e]?.turn_id !== last.id)
    )
      throw new ServiceError('invalid_model_output', 502, '追问没有当前回答依据');
    const afterObserved = missingNext.filter(
      (dimension) =>
        !(
          ['covered', 'inconclusive'].includes(statusFor(control)) &&
          observedGoals.some((goal) =>
            (FEEDBACK_INTERVIEW_GOALS[dimension.key] as readonly string[]).includes(goal),
          )
        ),
    );
    if (
      semantic &&
      !isHR &&
      control.a === 'n' &&
      !recoveringIntroduction(control) &&
      pacing.remaining_seconds > policy.closing_seconds &&
      remainingMain > 0 &&
      remainingMain <= afterObserved.length &&
      !afterObserved.some((dimension) =>
        (FEEDBACK_INTERVIEW_GOALS[dimension.key] as readonly string[]).includes(
          goalOptions[control.g],
        ),
      )
    )
      throw new ServiceError('invalid_model_output', 502, '剩余题量应留给实际尚缺的考察维度');
  };
  const referencesFor = (fields: { r?: unknown; s?: unknown }) => {
    const materials = materialIndicesSchema.parse(fields.r ?? []);
    const sources = sourceIndicesSchema.parse(fields.s ?? []);
    if (materials.some((index) => !resumeFacts[index]))
      throw new ServiceError('invalid_model_output', 502, '简历依据下标无效');
    const allowed = new Set(snapshot.knowledge.sources.map((source) => source.id));
    if (sources.some((index) => !allowed.has(sourceOptions[index])))
      throw new ServiceError('invalid_model_output', 502, '来源下标无效');
    return { r: materials, s: sources };
  };
  return {
    assessed,
    statusFor,
    observedGoalsFor,
    recoveringIntroduction,
    groundingFor,
    check,
    referencesFor,
  };
}
type AdvanceChecks = ReturnType<typeof createAdvanceChecks>;
function createPreviewHandler(
  plan: AdvancePlan,
  output: AdvanceSchemas,
  checks: AdvanceChecks,
  timing: { onText: () => void; onVisible: () => void },
) {
  const { interview, context, isHR, modern, grounding, last } = plan;
  const { head, controlOf } = output;
  const { check, referencesFor, recoveringIntroduction, groundingFor, statusFor } = checks;
  let preview: InterviewPreview = { acknowledgement: '', text: '' };
  return async (text: string) => {
    timing.onText();
    const parsed = jsonFields(text),
      parsedControl = head.safeParse(parsed.fields);
    if (!parsedControl.success) return;
    const control = controlOf(parsedControl.data);
    check(control);
    // Source/material selections are part of the semantic head when available.
    // Validate them before any question draft can reach text or speech.
    referencesFor(parsed.fields);
    if (control.a === 'e' || control.a === 'c') return;
    // Preparation questions are brief: validate their intent before exposing any draft assumption.
    if (preparingBackground(grounding) && typeof parsed.fields.q !== 'string') return;
    const next = {
      acknowledgement: typeof parsed.fields.b === 'string' ? parsed.fields.b : '',
      text:
        typeof parsed.fields.q === 'string'
          ? parsed.fields.q
          : parsed.partial?.key === 'q'
            ? parsed.partial.value
            : '',
    };
    if (typeof parsed.fields.q !== 'string') {
      const boundary = Math.max(
        next.text.lastIndexOf('，'),
        next.text.lastIndexOf('。'),
        next.text.lastIndexOf('？'),
        next.text.lastIndexOf('：'),
      );
      if (boundary >= 0) next.text = next.text.slice(0, boundary + 1);
      else if (next.text.length >= 8) {
        const segments = Array.from(
          new Intl.Segmenter('zh', { granularity: 'word' }).segment(next.text),
        );
        const lastWord = segments.at(-1)!;
        next.text = next.text.slice(0, lastWord.index);
        if (next.text.length < 6) next.text = '';
      } else next.text = '';
    }
    const recovering = recoveringIntroduction(control);
    if (!isHR || recovering)
      assertExperienceQuestion(
        next.text,
        groundingFor(control),
        statusFor(control) === 'covered',
        typeof parsed.fields.q === 'string',
      );
    if (modern) {
      assertPolicyQuestion(next.text, interview.configuration);
      if (isHR)
        assertConversationQuestion(
          next.text,
          grounding.conversation,
          typeof parsed.fields.q === 'string',
        );
      if (typeof parsed.fields.q === 'string') assertQuestionIntent(next.text, last.answer_text);
    }
    assertPreview(next);
    if (next.text !== preview.text || next.acknowledgement !== preview.acknowledgement) {
      await context.preview(next);
      preview = next;
      if (next.text || next.acknowledgement) timing.onVisible();
    }
  };
}

type CompactResult = z.infer<AdvanceSchemas['schema']> & Control & { r: number[]; s: number[] };
function advanceDecision(
  plan: AdvancePlan,
  output: AdvanceSchemas,
  checks: AdvanceChecks,
  compact: CompactResult,
) {
  const { sourceOptions, anchors, goalOptions } = plan;
  const { actionNames } = output;
  const { assessed, statusFor, observedGoalsFor, recoveringIntroduction, groundingFor, check } =
    checks;
  const materialIndices = compact.r;
  check(compact);
  const responseAssessment = assessed(compact);
  const observedGoals = observedGoalsFor(compact);
  const recovering = recoveringIntroduction(compact);
  const questionGrounding = groundingFor(compact);
  const value = {
    action: actionNames[compact.a],
    goal: goalOptions[compact.g],
    evidence_id: compact.e,
    text: compact.q,
    source_ids: compact.s,
    observed: statusFor(compact),
    pending: statusFor(compact) === 'needs_probe' ? compact.q : null,
    intent: compact.q,
  };
  if (value.source_ids.some((i) => !sourceOptions[i]))
    throw new ServiceError('invalid_model_output', 502, '来源下标无效');
  const evidence =
    responseAssessment?.response_eligibility === 'non_answer' || value.evidence_id === null
      ? []
      : [anchors[value.evidence_id]];
  return {
    materialIndices,
    responseAssessment,
    observedGoals,
    recovering,
    questionGrounding,
    value,
    evidence,
  };
}
type AdvanceDecision = ReturnType<typeof advanceDecision>;
function advanceObservation(plan: AdvancePlan, decision: AdvanceDecision, observedGoal: string) {
  const { grounding, semantic, isHR } = plan;
  const { evidence, value } = decision;
  return {
    goal: observedGoal,
    state:
      grounding.conversation.last_act === 'decline_topic'
        ? 'inconclusive'
        : !semantic && !isHR && preparingBackground(grounding)
          ? 'needs_probe'
          : !semantic &&
              observedGoal === 'contribution' &&
              grounding.discovery_required &&
              grounding.missing.includes('personal_role')
            ? 'needs_probe'
            : value.observed,
    evidence_refs: evidence,
    pending:
      grounding.conversation.last_act === 'decline_topic'
        ? null
        : !semantic && !isHR && preparingBackground(grounding)
          ? value.text
          : value.pending,
  };
}
function createAdvanceMemory(
  plan: AdvancePlan,
  decision: AdvanceDecision,
  compact: CompactResult,
  clarify: boolean,
) {
  const { interview, snapshot, context, modern, grounding, last } = plan;
  const { responseAssessment, observedGoals, recovering, value, evidence } = decision;
  const memory = clarify
    ? (context.memory ?? {
        version: 0,
        focus: null,
        observations: [],
        claims: [],
        asked_intents: [],
      })
    : applyMemory(
        context.memory,
        {
          focus: value.goal,
          intent: `${value.goal}:${value.intent}:${value.text}`,
          observations: evidence.length
            ? observedGoals.map((goal) => advanceObservation(plan, decision, goal))
            : [],
          claims: (
            responseAssessment
              ? responseAssessment.response_eligibility !== 'answer'
              : grounding.conversation.last_act !== 'answer'
          )
            ? []
            : evidence.slice(0, 1).map((e) => ({ text: e.quote, evidence_refs: [e] })),
        },
        snapshot,
        interview.turns,
      );
  if (!clarify) {
    if (responseAssessment) {
      memory.response = { ...responseAssessment, turn_id: last.id, revision: last.revision };
      memory.introduction_complete = context.memory?.introduction_complete ?? false;
      memory.communication_observed =
        context.memory?.communication_observed === true ||
        responseAssessment.communication_observed === true;
      if (last.stage === 'introduction' && responseAssessment.response_eligibility === 'answer')
        memory.introduction_complete = true;
      grounding.conversation.last_act = responseAssessment.act;
      if (recovering) memory.focus = null;
    }
    if (modern) memory.decision = { reason: (compact as { d: string }).d, action: value.action };
    memory.experience = grounding.experience;
    memory.conversation = grounding.conversation;
  }
  return memory;
}
function createAdvanceQuestion(
  plan: AdvancePlan,
  output: AdvanceSchemas,
  decision: AdvanceDecision,
  compact: CompactResult,
) {
  const { interview, snapshot, semantic, modern, grounding, isHR, sourceOptions, release, last } =
    plan;
  const { goalContracts } = output;
  const { recovering, questionGrounding, value, evidence } = decision;
  const question = ['finish', 'clarify'].includes(value.action)
    ? null
    : {
        text: value.text,
        topic:
          recovering || grounding.next_step === 'introduction'
            ? '自我介绍'
            : grounding.next_step === 'alternative_experience'
              ? '学习与实践背景'
              : release.competencies.find((g) => g.id === value.goal)!.title,
        purpose: recovering
          ? '温和邀请补充尚未收到的自我介绍，不预设项目经历'
          : semantic
            ? goalContracts.find((goal) => goal.goal === value.goal)!.evidence_wanted
            : release.competencies.find((g) => g.id === value.goal)!.evidence_wanted,
        knowledge_question_id: null,
        stage: (recovering || grounding.next_step === 'introduction'
          ? 'introduction'
          : grounding.next_step === 'alternative_experience' ||
              questionGrounding.discovery_required ||
              (grounding.next_step === 'topic_transition' && value.goal === 'learning')
            ? 'experience'
            : snapshot.runtime_version === 'graph-v1' && value.goal === 'contribution'
              ? 'experience'
              : ['business', 'tradeoffs'].includes(value.goal)
                ? 'business'
                : ['understanding', 'verification'].includes(value.goal)
                  ? 'technical'
                  : 'behavioral') as
          | 'introduction'
          | 'experience'
          | 'business'
          | 'technical'
          | 'behavioral',
        acknowledgement: modern ? (compact as { b: string }).b : '',
        source_refs: value.source_ids.map((i) => sourceOptions[i]),
        evidence_refs: evidence,
      };
  if (question) {
    if (!question.text.trim()) throw new Error('Empty question');
    if (modern) {
      assertPolicyQuestion(question.text, interview.configuration);
      if (isHR) assertConversationQuestion(question.text, grounding.conversation, true);
      assertQuestionIntent(question.text, last.answer_text);
    }
    if (!isHR || recovering)
      assertExperienceQuestion(
        question.text,
        questionGrounding,
        value.observed === 'covered',
        true,
      );
    assertQuestion(question, snapshot, interview.turns);
    assertPreview(question);
  }
  return question;
}
function advanceRetrieval(plan: AdvancePlan, materialIndices: number[]) {
  const { context, snapshot, grounding } = plan;
  const retrieval = knowledgeReady(grounding)
    ? context.retrieval
    : {
        ...context.retrieval,
        chunks: [],
        mode: 'empty' as const,
        missing_reason: '依据当前对话准备阶段或已知学习背景提问，暂不使用专业检索内容',
      };
  return snapshot.runtime_version === 'graph-v1'
    ? {
        ...retrieval,
        material_refs: materialIndices.map((i) => snapshot.resume_analysis!.facts[i].evidence),
      }
    : retrieval;
}
function buildAdvanceResult(
  plan: AdvancePlan,
  output: AdvanceSchemas,
  checks: AdvanceChecks,
  compact: CompactResult,
  clarify: boolean,
) {
  const decision = advanceDecision(plan, output, checks, compact);
  const memory = createAdvanceMemory(plan, decision, compact, clarify);
  const question = createAdvanceQuestion(plan, output, decision, compact);
  const { value } = decision;
  if (value.action === 'clarify' && !value.text.trim()) throw new Error('Missing clarification');
  return {
    action: value.action,
    question,
    clarification: value.action === 'clarify' ? value.text : null,
    memory,
    retrieval: advanceRetrieval(plan, decision.materialIndices),
  };
}

export function createStreamingAgent(
  base: Pick<InterviewAgent, 'available' | 'model' | 'evaluate' | 'summarize' | 'compare'>,
  config: BackendConfig,
  log: (entry: object) => void = () => {},
  fetcher: typeof fetch = fetch,
): InterviewAgent {
  return {
    ...base,
    async advance(interview, snapshot, clarify, signal, repair, context) {
      if (!context || !snapshot.knowledge.agent_release)
        throw new ServiceError('invalid_state', 409, '面试工作流上下文缺失，请重新创建面试');
      const started = performance.now();
      let first: number | undefined, firstVisible: number | undefined;
      let code = 'ok';
      let usage: Record<string, number> | undefined;
      let usedChunks = context.retrieval.chunks;
      const timeout = AbortSignal.any([signal, AbortSignal.timeout(config.LLM_TIMEOUT_MS)]);
      try {
        const plan = prepareAdvancePlan(interview, snapshot, context);
        usedChunks = plan.knowledgeChunks;
        const output = createAdvanceSchemas(plan, clarify);
        const { semantic, modern } = plan;
        const { controlOf, schema } = output;
        const response = await fetcher(
          `${config.LLM_BASE_URL!.replace(///$/, '')}/chat/completions`,
          {
            method: 'POST',
            redirect: 'error',
            signal: timeout,
            headers: {
              authorization: `Bearer ${config.LLM_API_KEY}`,
              'content-type': 'application/json',
            },
            body: JSON.stringify({
              model: snapshot.model,
              stream: true,
              thinking: { type: 'disabled' },
              stream_options: { include_usage: true },
              max_tokens: semantic ? 650 : modern ? 450 : 300,
              temperature: 0.3,
              response_format: {
                type: 'json_schema',
                json_schema: { name: 'interview_v3', strict: true, schema: z.toJSONSchema(schema) },
              },
              messages: buildAdvanceMessages(plan, output, clarify, repair),
            }),
          },
        );
        if (!response.ok) throw new ServiceError('provider_error', 502, '模型请求失败', true);
        const checks = createAdvanceChecks(plan, output);
        const { referencesFor } = checks;
        const raw = await readChatStream(
          response,
          createPreviewHandler(plan, output, checks, {
            onText: () => {
              first ??= performance.now() - started;
            },
            onVisible: () => {
              firstVisible ??= performance.now() - started;
            },
          }),
          timeout,
          (value) => {
            usage = value;
          },
        );
        const parsedCompact = schema.parse(JSON.parse(raw));
        const compact = {
          ...parsedCompact,
          ...controlOf(parsedCompact),
          ...referencesFor(parsedCompact),
        };
        return buildAdvanceResult(plan, output, checks, compact, clarify);
      } catch (error) {
        log({
          task: 'advance_v3_validation',
          error:
            error instanceof ServiceError
              ? error.message
              : error instanceof z.ZodError
                ? error.issues.map((i) => ({ path: i.path, code: i.code }))
                : error instanceof Error
                  ? error.name
                  : 'unknown',
        });
        await context.preview({ acknowledgement: '', text: '' }).catch(() => {});
        code = signal.aborted
          ? 'task_cancelled'
          : timeout.aborted
            ? 'provider_timeout'
            : error instanceof ServiceError
              ? error.code
              : 'invalid_model_output';
        throw new ServiceError(code, 502, '面试官生成暂时失败，回答已保存', true);
      } finally {
        log({
          task: 'advance_v3',
          model: snapshot.model,
          prompt_version: snapshot.prompt_version,
          interview_id: interview.id,
          generation_id: interview.generation_id,
          queued_ms: context.queued_ms,
          retrieval_ms: context.retrieval_ms,
          retrieval_mode: usedChunks.length ? context.retrieval.mode : 'empty',
          chunk_ids: usedChunks.map((c) => c.id),
          usage,
          first_token_ms: first,
          first_visible_ms: firstVisible,
          duration_ms: performance.now() - started,
          code,
        });
      }
    },
  };
}

import { Client } from 'pg';
import type { InterviewPreview } from '@interviewlab/core';
import type { Database } from '../../database/connection';
import type { TaskRow } from '../../tasks/service';
export function createGenerationStreams(database: Database) {
  const subscribers = new Map<string, Set<() => void>>();
  let listener: Client | undefined;
  let connecting: Promise<void> | undefined;
  let closed = false;
  async function listen() {
    if (listener) return;
    if (connecting) return connecting;
    connecting = (async () => {
      const client = new Client(database.pool.options);
      await client.connect();
      if (closed) {
        await client.end();
        return;
      }
      listener = client;
      client.on('notification', (n) => {
        if (n.channel === 'interview_generation' && n.payload)
          subscribers.get(n.payload)?.forEach((fn) => fn());
      });
      client.on('error', () => {
        if (listener === client) {
          listener = undefined;
          void client.end().catch(() => {});
          connecting = undefined;
          subscribers.forEach((set) => set.forEach((fn) => fn()));
        }
      });
      await client.query('LISTEN interview_generation');
    })().finally(() => {
      connecting = undefined;
    });
    return connecting;
  }
  return {
    async subscribe(id: string, notify: () => void) {
      await listen();
      const set = subscribers.get(id) ?? new Set();
      set.add(notify);
      subscribers.set(id, set);
      return () => {
        set.delete(notify);
        if (!set.size) subscribers.delete(id);
      };
    },
    async preview(task: Readonly<TaskRow>, generation: string, value: InterviewPreview) {
      const input = task.payload as { interview_id: string };
      await database.transaction(async (tx) => {
        // Serialize against pause/delete, then verify this exact worker claim. A late producer cannot recreate private previews.
        const live = await tx.client.query(
          `SELECT i.id FROM interviews i JOIN tasks t ON t.id=i.task_id WHERE i.id=$1 AND i.owner_id=$2 AND i.generation_id=$3 AND i.generation_status='pending' AND i.status='in_progress' AND i.deleted_at IS NULL AND t.status='running' AND t.execution_token=$4 AND t.lease_until>now() FOR UPDATE OF i`,
          [input.interview_id, task.owner_id, generation, task.execution_token],
        );
        if (!live.rowCount) return;
        await tx.client.query(
          `INSERT INTO interview_generation_streams(interview_id,generation_id,execution_token,acknowledgement,text) VALUES($1,$2,$3,$4,$5) ON CONFLICT(interview_id) DO UPDATE SET generation_id=EXCLUDED.generation_id,execution_token=EXCLUDED.execution_token,acknowledgement=EXCLUDED.acknowledgement,text=EXCLUDED.text,updated_at=now()`,
          [input.interview_id, generation, task.execution_token, value.acknowledgement, value.text],
        );
        await tx.client.query("SELECT pg_notify('interview_generation',$1)", [input.interview_id]);
      });
    },
    async read(id: string, generation: string) {
      const result = await database.pool.query<{ acknowledgement: string; text: string }>(
        `SELECT acknowledgement,text FROM interview_generation_streams WHERE interview_id=$1 AND generation_id=$2 AND updated_at>now()-interval '15 minutes'`,
        [id, generation],
      );
      return result.rows[0] ?? null;
    },
    async cleanup() {
      await database.pool.query(
        "DELETE FROM interview_generation_streams s WHERE updated_at<now()-interval '15 minutes' OR NOT EXISTS(SELECT 1 FROM interviews i WHERE i.id=s.interview_id AND i.generation_id=s.generation_id AND i.generation_status='pending' AND i.status='in_progress')",
      );
    },
    async close() {
      closed = true;
      await connecting?.catch(() => {});
      if (listener) {
        await listener.query('UNLISTEN interview_generation').catch(() => {});
        await listener.end();
        listener = undefined;
      }
    },
  };
}

import type { RequestIdentity } from '@interviewlab/core';
import type { Database } from '../../../database/connection';
import { ServiceError } from '../../../foundation/errors';
import type { Executor } from '../repository';

export interface VoiceInputActivity {
  session_id: string;
  turn_id: string;
  generation_id: string;
  active: boolean;
}
type Leases = Record<
  string,
  Omit<VoiceInputActivity, 'session_id' | 'active'> & { expires_at: string }
>;

/** Private delivery state: never part of the interview version, model input or answer evidence. */
export async function setVoiceInputActivity(
  database: Database,
  identity: RequestIdentity,
  id: string,
  activity: VoiceInputActivity,
) {
  return database.transaction(async (tx) => {
    const result = await tx.client.query<{
      status: string;
      generation_id: string | null;
      generation_status: string;
      voice_activity: Leases;
      turn_id: string | null;
      answer_status: string | null;
    }>(
      `SELECT i.status,i.generation_id,i.generation_status,i.voice_activity,t.id AS turn_id,t.answer_status
       FROM interviews i LEFT JOIN LATERAL (SELECT id,answer_status FROM interview_turns WHERE interview_id=i.id ORDER BY main_question_index DESC,follow_up_index DESC LIMIT 1) t ON true
       WHERE i.id=$1 AND i.owner_id=$2 AND i.deleted_at IS NULL FOR UPDATE OF i`,
      [id, identity.owner_id],
    );
    const state = result.rows[0];
    if (!state) throw new ServiceError('not_found', 404, '面试不存在或不可访问');
    if (
      activity.active &&
      (state.status !== 'in_progress' ||
        state.generation_status !== 'pending' ||
        state.generation_id !== activity.generation_id ||
        state.turn_id !== activity.turn_id ||
        state.answer_status !== 'answered')
    )
      return false;
    const now = Date.now();
    const leases: Leases = Object.fromEntries(
      Object.entries(state.voice_activity ?? {}).filter(
        ([, lease]) => Date.parse(lease.expires_at) > now,
      ),
    );
    if (activity.active)
      leases[activity.session_id] = {
        turn_id: activity.turn_id,
        generation_id: activity.generation_id,
        expires_at: new Date(now + 5000).toISOString(),
      };
    else if (
      leases[activity.session_id]?.generation_id === activity.generation_id &&
      leases[activity.session_id]?.turn_id === activity.turn_id
    )
      delete leases[activity.session_id];
    await tx.client.query('UPDATE interviews SET voice_activity=$2::jsonb WHERE id=$1', [
      id,
      JSON.stringify(leases),
    ]);
    return true;
  });
}

export async function voicePublicationReady(
  db: Executor,
  id: string,
  generation: string,
  turnId: string,
) {
  const result = await db.query<{ ready: boolean }>(
    `SELECT NOT EXISTS (SELECT 1 FROM jsonb_each(voice_activity) AS lease WHERE lease.value->>'generation_id'=$2 AND lease.value->>'turn_id'=$3 AND (lease.value->>'expires_at')::timestamptz > clock_timestamp()) AS ready FROM interviews WHERE id=$1`,
    [id, generation, turnId],
  );
  return result.rows[0]?.ready ?? true;
}

import { z } from 'zod';
import type { FastifyInstance } from 'fastify';
import type { VoiceCapabilities, VoiceClientEvent } from '@interviewlab/core';
import { requireSameOrigin } from '../../../foundation/auth';
import { ServiceError } from '../../../foundation/errors';
import { errorSchema } from '../../../foundation/schemas';
import type { BackendConfig } from '../../../foundation/config';
import type { ModuleContext } from '../../contracts';
import type { LiveInterviewsService } from '../service';
import { createVolcengineVoice, type VoiceProvider } from './volcengine';
import { InterviewVoiceSession } from './session';

export interface VoiceOptions {
  config: BackendConfig;
  provider?: VoiceProvider;
}
const controlSchema = z.discriminatedUnion('type', [
  z
    .object({
      type: z.enum(['speech_start', 'speech_end', 'commit', 'interrupt', 'repeat', 'ping']),
    })
    .strict(),
  z.object({ type: z.literal('hold'), enabled: z.boolean() }).strict(),
  z
    .object({
      type: z.literal('playback'),
      speech_id: z.uuid(),
      played_ms: z.number().min(0).max(120000),
      interrupted: z.boolean(),
    })
    .strict(),
]);
export function registerVoiceRoutes(
  app: FastifyInstance,
  context: ModuleContext,
  ready: () => LiveInterviewsService,
  options: VoiceOptions,
) {
  const { config } = options;
  const provider = options.provider ?? createVolcengineVoice(config);
  const sessions = new Map<string, { close: () => void }>();
  app.addHook('onClose', async () => {
    for (const session of sessions.values()) session.close();
    sessions.clear();
  });
  const capabilities = (): VoiceCapabilities => ({
    available: config.VOICE_ENABLED && provider.available,
    reason: !config.VOICE_ENABLED
      ? '实时语音尚未开启，请先配置火山引擎语音服务。'
      : !provider.available
        ? '语音服务尚未配置完整，请配置 ASR 和 TTS 密钥后重启后端。'
        : null,
    input_sample_rate: 16000,
    output_sample_rate: 24000,
    silence_ms: config.VOICE_SILENCE_MS,
  });
  const params = z.object({ id: z.uuid() });
  app.get<{ Params: { id: string } }>(
    '/interviews/:id/voice/capabilities',
    {
      schema: {
        tags: ['interviews'],
        params,
        response: {
          200: z.object({
            available: z.boolean(),
            reason: z.string().nullable(),
            input_sample_rate: z.literal(16000),
            output_sample_rate: z.literal(24000),
            silence_ms: z.number(),
          }),
          401: errorSchema,
          404: errorSchema,
          501: errorSchema,
        },
      },
    },
    async (request) => {
      await ready().read(await context.requireIdentity(request), request.params.id);
      return capabilities();
    },
  );
  app.get<{ Params: { id: string } }>(
    '/interviews/:id/voice',
    {
      websocket: true,
      schema: { hide: true, params },
      preValidation: async (request) => {
        requireSameOrigin(request, config.PUBLIC_ORIGIN);
        const principal = await context.requireIdentity(request);
        await ready().read(principal, request.params.id);
        if (!capabilities().available)
          throw new ServiceError('capability_unavailable', 501, capabilities().reason!);
      },
    },
    (socket, request) => {
      let bufferedBytes = 0,
        windowStart = Date.now(),
        windowBytes = 0,
        windowControls = 0;
      const identity = () => context.requireIdentity(request);
      const session = new InterviewVoiceSession(
        request.params.id,
        identity,
        ready(),
        provider,
        config.VOICE_SILENCE_MS,
        (event) => {
          if (socket.readyState !== 1) return;
          if (socket.bufferedAmount > 2 * 1024 * 1024) {
            session.close();
            socket.close(1013, 'Audio consumer too slow');
            return;
          }
          socket.send(JSON.stringify(event));
        },
        () => socket.close(1000, 'Voice session ended'),
      );
      let key = '';
      socket.on('message', (data, binary) => {
        try {
          if (Date.now() - windowStart > 1000) {
            windowStart = Date.now();
            windowBytes = 0;
            windowControls = 0;
          }
          if (binary) {
            if (Date.now() - windowStart > 1000) {
              windowStart = Date.now();
              windowBytes = 0;
            }
            const pcm = Buffer.from(data as Buffer);
            windowBytes += pcm.byteLength;
            bufferedBytes += pcm.byteLength;
            if (windowBytes > 96000 || bufferedBytes > 32 * 1024 * 1024) throw new Error();
            session.audio(pcm);
          } else {
            if (++windowControls > 60) throw new Error();
            if (Buffer.byteLength(data.toString()) > 1024) throw new Error();
            const event = controlSchema.parse(JSON.parse(data.toString())) as VoiceClientEvent;
            session.control(event);
          }
        } catch {
          session.close();
          socket.close(1008, 'Invalid voice message');
        }
      });
      socket.on('close', () => {
        session.close();
        if (sessions.get(key)?.close === close) sessions.delete(key);
      });
      socket.on('error', () => session.close());
      const close = () => {
        session.close();
        socket.close(1000, 'Replaced voice connection');
      };
      void identity()
        .then(async (principal) => {
          if (socket.readyState !== 1) return;
          key = `${principal.owner_id}:${request.params.id}`;
          sessions.get(key)?.close();
          sessions.set(key, { close });
          await session.start();
        })
        .catch(() => {
          if (socket.readyState === 1)
            socket.send(
              JSON.stringify({
                type: 'error',
                code: 'voice_connect_failed',
                message: '无法连接语音服务，请检查语音配置并重新连接。',
                retryable: true,
              }),
            );
          session.close();
          socket.close(1011, 'Voice connection failed');
        });
    },
  );
}

import { randomUUID } from 'node:crypto';
import type {
  Interview,
  RequestIdentity,
  VoiceClientEvent,
  VoiceServerEvent,
} from '@interviewlab/core';
import { INTERVIEW_MAX_ANSWER, interviewDeadline } from '@interviewlab/core';
import type { LiveInterviewsService } from '../service';
import { ServiceError } from '../../../foundation/errors';
import type { AsrStream, VoiceProvider } from './volcengine';

export type VoiceInterviews = Pick<
  LiveInterviewsService,
  | 'read'
  | 'answer'
  | 'interruptVoice'
  | 'continueVoice'
  | 'recordVoicePlayback'
  | 'setVoiceInputActivity'
>;
/** One transport session, one authoritative interview service. No audio is persisted. */
export class InterviewVoiceSession {
  private view!: Interview;
  private asr?: AsrStream;
  private asrEpoch = 0;
  private pendingAudio: Uint8Array[] = [];
  private pendingBytes = 0;
  private closed = false;
  private initialized = false;
  private queued = 0;
  private chain = Promise.resolve();
  private poll?: ReturnType<typeof setInterval>;
  private timer?: ReturnType<typeof setTimeout>;
  private expire?: ReturnType<typeof setTimeout>;
  private speech?: { id: string; turn: string; controller: AbortController };
  private playback = new Map<string, string>();
  private spoken = new Set<string>();
  private text = '';
  private final = false;
  private talking = false;
  private hold = false;
  private manual = false;
  private flushing = false;
  private recognitionPrefix = '';
  private lastAudioVoiceAt = 0;
  private activityRevision = 0;
  private stoppedAt = 0;
  private changedAt = 0;
  private interruptedTurn: string | null = null;
  private capturedTurn: string | null = null;
  private checking = false;
  private lastAuth = 0;
  private initialOwner = '';
  private readonly sessionId = randomUUID();
  private inputActivity?: { turn: string; generation: string };
  private activityTimer?: ReturnType<typeof setInterval>;
  private activityTail?: ReturnType<typeof setTimeout>;
  private staleDraft = false;
  private staleNoticeSent = false;
  constructor(
    private readonly id: string,
    private readonly identity: () => Promise<RequestIdentity>,
    private readonly service: VoiceInterviews,
    private readonly provider: VoiceProvider,
    private readonly silenceMs: number,
    private readonly send: (event: VoiceServerEvent) => void,
    private readonly disconnect: () => void,
  ) {}
  private enqueue(work: () => Promise<void>) {
    if (this.closed) return;
    if (++this.queued > 64) {
      this.send({
        type: 'error',
        code: 'voice_backpressure',
        message: '语音处理积压，草稿仍保留，请稍后重新连接。',
        retryable: true,
      });
      this.close();
      this.disconnect();
      return;
    }
    this.chain = this.chain
      .then(async () => {
        if (!this.closed) await work();
      })
      .catch((error) => {
        if (this.closed) return;
        const safe = error instanceof ServiceError;
        this.send({
          type: 'error',
          code: safe ? error.code : 'voice_unavailable',
          message: safe ? error.message : '语音连接中断，草稿仍保留，请重新连接或使用文字。',
          retryable: true,
        });
        this.close();
        this.disconnect();
      })
      .finally(() => {
        this.queued--;
      });
  }
  async start() {
    const identity = await this.identity();
    this.initialOwner = identity.owner_id;
    this.view = await this.service.read(identity, this.id);
    if (this.view.status !== 'in_progress')
      throw new ServiceError('invalid_state', 409, '请先开始或继续面试，再开启实时语音。');
    if (
      this.view.generation_status === 'idle' &&
      this.view.turns.at(-1)?.answer_status === 'answered'
    )
      this.interruptedTurn = this.view.turns.at(-1)!.id;
    await this.resetRecognition();
    if (this.closed) return;
    this.initialized = true;
    this.send({ type: 'ready', silence_ms: this.silenceMs });
    this.publish(this.view, true);
    this.poll = setInterval(() => {
      if (this.checking || this.closed) return;
      this.checking = true;
      this.enqueue(async () => {
        try {
          let identity: RequestIdentity = { owner_id: this.initialOwner, roles: [] };
          if (Date.now() - this.lastAuth > 5000) {
            identity = await this.identity();
            this.lastAuth = Date.now();
            if (identity.owner_id !== this.initialOwner)
              throw new ServiceError('unauthorized', 401, '登录状态已变化，请重新登录。');
          }
          this.publish(await this.service.read(identity, this.id));
        } finally {
          this.checking = false;
        }
      });
    }, 500);
    this.expire = setTimeout(
      () => {
        this.close();
        this.disconnect();
      },
      Math.max(
        0,
        (this.view.deadline_at
          ? Date.parse(this.view.deadline_at)
          : interviewDeadline(this.view.started_at!, this.view.configuration.duration_minutes)) -
          Date.now(),
      ),
    );
  }
  audio(pcm: Uint8Array) {
    if (!this.initialized) return;
    if (this.closed || !['ready', 'in_progress'].includes(this.view?.status)) return;
    if (!pcm.byteLength || pcm.byteLength > 12800 || pcm.byteLength % 2) {
      this.protocolError();
      return;
    }
    if (this.speech) {
      // ASR rejects a stream with no audio packets (45000081). Keep its clock alive
      // without forwarding microphone samples or treating echo as candidate speech.
      this.asr?.write(new Uint8Array(pcm.byteLength));
      return;
    }
    const samples = new DataView(pcm.buffer, pcm.byteOffset, pcm.byteLength);
    let power = 0;
    for (let i = 0; i < pcm.byteLength; i += 2) power += (samples.getInt16(i, true) / 32768) ** 2;
    if (Math.sqrt(power / (pcm.byteLength / 2)) > 0.018) this.lastAudioVoiceAt = Date.now();
    else if (this.talking && Date.now() - this.lastAudioVoiceAt > 800) {
      // Recover if a browser VAD speech_end notification is lost.
      this.talking = false;
      this.stoppedAt = this.lastAudioVoiceAt;
      this.releaseActivityAfterTail();
      this.arm();
    }
    if (this.asr) this.asr.write(pcm);
    else {
      this.pendingBytes += pcm.byteLength;
      if (this.pendingBytes > 128000) {
        this.protocolError();
        return;
      }
      this.pendingAudio.push(pcm);
    }
  }
  private protocolError() {
    this.send({
      type: 'error',
      code: 'voice_input_invalid',
      message: '音频传输异常，请重新连接语音。',
      retryable: true,
    });
    this.close();
    this.disconnect();
  }
  control(event: VoiceClientEvent) {
    if (!this.initialized || this.closed) return;
    if (this.speech && ['speech_start', 'speech_end', 'commit'].includes(event.type)) return;
    const resumeFlushed = event.type === 'speech_start' && this.flushing;
    const activityRevision = ['speech_start', 'speech_end'].includes(event.type)
      ? ++this.activityRevision
      : this.activityRevision;
    if (event.type === 'speech_start') {
      // Invalidate an already queued endpoint BEFORE any asynchronous DB work.
      this.talking = true;
      this.lastAudioVoiceAt = Date.now();
      this.manual = false;
      this.capturedTurn ??= this.view.turns.at(-1)?.id ?? null;
      clearTimeout(this.activityTail);
      clearTimeout(this.timer);
      if (resumeFlushed) {
        ++this.asrEpoch;
        this.asr?.close();
        this.asr = undefined;
        this.flushing = false;
      }
    }
    if (event.type === 'speech_start' || event.type === 'interrupt') this.stopSpeech();
    this.enqueue(async () => {
      if (this.speech && ['speech_start', 'speech_end', 'commit'].includes(event.type)) return;
      if (event.type === 'ping') return;
      if (event.type === 'playback') {
        const turn = this.playback.get(event.speech_id);
        if (turn) {
          this.playback.delete(event.speech_id);
          if (this.speech?.id === event.speech_id) {
            this.speech.controller.abort();
            this.speech = undefined;
            this.talking = false;
            this.final = false;
            this.manual = false;
            clearTimeout(this.timer);
            if (!this.text && !this.interruptedTurn) {
              this.capturedTurn = null;
              this.staleDraft = false;
            }
            await this.resetRecognition();
          }
          await this.service.recordVoicePlayback(await this.identity(), this.id, turn, {
            speech_id: event.speech_id,
            played_ms: event.played_ms,
            interrupted: event.interrupted,
          });
        }
        return;
      }
      if (event.type === 'repeat') {
        this.say(true);
        return;
      }
      if (event.type === 'hold') {
        this.hold = event.enabled;
        this.arm();
        return;
      }
      if (event.type === 'speech_start') {
        if (resumeFlushed) await this.resetRecognition(true, true);
        await this.reserveInputActivity();
      } else if (event.type === 'speech_end') {
        if (activityRevision !== this.activityRevision) return;
        this.talking = false;
        this.stoppedAt = Date.now();
        this.releaseActivityAfterTail();
        this.arm();
      } else if (event.type === 'commit') {
        if (!this.text.trim() && !this.talking && !this.capturedTurn) {
          await this.releaseInputActivity();
          this.send({
            type: 'status',
            state: this.view.generation_status === 'pending' ? 'thinking' : 'listening',
          });
          return;
        }
        this.manual = true;
        this.hold = false;
        this.talking = false;
        this.flushing = true;
        this.asr?.finish();
        // Await the recognizer's final packet, rather than committing an unstable partial.
        clearTimeout(this.timer);
        this.timer = setTimeout(
          () =>
            this.enqueue(async () => {
              if (this.manual)
                throw new ServiceError(
                  'voice_final_timeout',
                  504,
                  '暂未收到最终转写，草稿已保留，请切回文字确认后提交。',
                  true,
                );
            }),
          8000,
        );
      }
    });
  }
  private async reserveInputActivity() {
    const turn = this.view.turns.at(-1);
    if (
      this.view.generation_status !== 'pending' ||
      turn?.answer_status !== 'answered' ||
      !this.view.generation_id
    ) {
      if (this.inputActivity) await this.releaseInputActivity();
      if (this.capturedTurn && turn?.id !== this.capturedTurn) this.staleDraft = true;
      return !this.staleDraft;
    }
    if (this.capturedTurn && this.capturedTurn !== turn.id) {
      this.staleDraft = true;
      return false;
    }
    const activity = { turn: turn.id, generation: this.view.generation_id };
    const accepted = await this.service.setVoiceInputActivity(await this.identity(), this.id, {
      session_id: this.sessionId,
      turn_id: activity.turn,
      generation_id: activity.generation,
      active: true,
    });
    if (this.closed) {
      if (accepted)
        await this.service.setVoiceInputActivity(await this.identity(), this.id, {
          session_id: this.sessionId,
          turn_id: activity.turn,
          generation_id: activity.generation,
          active: false,
        });
      return false;
    }
    if (!accepted) {
      this.staleDraft = true;
      await this.releaseInputActivity();
      return false;
    }
    this.inputActivity = activity;
    this.activityTimer ??= setInterval(
      () =>
        this.enqueue(async () => {
