  private preservePreviousDraft() {
    if (this.staleNoticeSent) return;
    this.staleNoticeSent = true;
    this.send({
      type: 'error',
      code: 'voice_previous_draft',
      message: '问题已更新，这段补充仍保留为上一题草稿，请先确认内容。',
      retryable: true,
