      this.speech ||
      this.talking ||
      this.hold ||
      this.manual ||
      (!this.text && !this.interruptedTurn)
    )
      return;
    // ASR final means a sentence boundary, not necessarily the end of an answer.
    const unfinished =
      /(?:然后|因为|所以|但是|比如|首先|其次|以及|还有|我想|让我想想)[，,。.!！?？/s]*$/.test(
        this.text,
