export interface CatalogDocument {
  id: string;
  kind: NonNullable<KnowledgeChunk['kind']>;
  text: string;
  source_refs: string[];
  evidence_level: NonNullable<KnowledgeChunk['evidence_level']>;
  bindings: {
    job: string;
    stages: string[];
    types: InterviewConfig['interview_type'][];
    goals: string[];
  }[];
}
export const contentHash = (value: unknown) =>
  createHash('sha256').update(JSON.stringify(value)).digest('hex');
/** One authored record, many applicability bindings. Original catalog IDs are never replaced. */
export function buildCatalog(): CatalogDocument[] {
  const documents: CatalogDocument[] = [];
  const allTypes = Object.keys(PROFILE_GOALS) as InterviewConfig['interview_type'][];
  for (const job of JOBS) {
    const binding = {
      job: job.id,
      stages: job.stages,
      types: allTypes,
      goals: COMPETENCIES.map((c) => c.id),
    };
    documents.push({
      id: `${job.id}:profile:${job.version}`,
      kind: 'job_profile',
      text: templateJd(job),
      source_refs: job.source_refs,
      evidence_level: 'platform_authored',
      bindings: [binding],
    });
    for (const q of job.questions.filter(isActiveQuestion))
      documents.push({
        id: q.id,
        kind: 'question',
        evidence_level: 'platform_authored',
        source_refs: q.source_refs,
        text: `${q.topic}：${q.text}/n提问目的：${q.intent}/n观察方向：${q.observation_points.join('；')}/n追问线索：${q.follow_ups.join('；')}/n平台原创提问素材，不是标准答案或已验证能力证据。`,
        bindings: [
          {
            ...binding,
            stages: q.stages,
            types: questionInterviewTypes(q),
            goals: q.competencies?.length ? [...q.competencies] : binding.goals,
          },
        ],
      });
  }
  if (PUBLIC_INTERVIEW_SUPPLEMENTS.runtime_enabled)
    for (const question of PUBLIC_INTERVIEW_SUPPLEMENTS.questions) {
      if (!question.runtime_enabled) continue;
      const bindings = question.eligible_job_ids.map((jobId) => {
        const job = getJob(jobId);
        if (!job) throw new Error(`Supplemental question targets an unavailable role: ${jobId}`);
        const stages = question.stages.filter((stage) => job.stages.includes(stage));
        if (!stages.length) throw new Error(`Supplemental question has no applicable stage: ${jobId}`);
        return {
          job: job.id,
          stages,
          types: question.interview_types,
          goals: question.competencies,
        };
      });
      documents.push({
        id: question.id,
        kind: 'question',
        evidence_level: 'source_summary',
        source_refs: question.source_refs,
        text: `${question.topic}：${question.text}/n提问目的：${question.intent}/n观察方向：${question.observation_points.join('；')}/n追问线索：${question.follow_ups.join('；')}/n来源与适用限制：${question.limitations}/n公开面经摘要，不是标准答案或已验证能力证据。`,
        bindings,
      });
    }
  for (const { job, source, questions } of teacherAgentQuestions) {
    if (!getJob(job)?.stages.includes('campus'))
      throw new Error(`Teacher question set targets an unavailable campus role: ${job}`);
    for (const q of questions) {
      const experience = q.number.startsWith('A');
      const scenario =
        (source.id === 'teacher-issue-12' && q.number.startsWith('C')) ||
        (source.id === 'teacher-issue-14' && /^[C-F]/.test(q.number));
      documents.push({
        id: `${source.id}-${q.number.toLowerCase()}-v1`,
        kind: 'question',
        evidence_level: 'source_summary',
        source_refs: [source.id],
        text: `${q.topic}（${q.difficulty}）/n题目：${q.text}${
          q.notes ? `/n面试官参考（用于追问，不向候选人提示）：/n${q.notes}` : ''
        }`,
        bindings: [
          {
            job,
            stages: ['campus'],
            types: [
              experience ? 'project_deep_dive' : scenario ? 'business_scenario' : 'technical_qa',
              'mixed',
            ],
            goals: experience
              ? ['contribution', 'motivation', 'verification']
              : scenario
                ? ['business', 'tradeoffs', 'verification']
                : ['understanding', 'tradeoffs', 'verification'],
          },
        ],
      });
    }
  }
  for (const card of professional)
    documents.push({
      id: card.id,
      kind: 'professional',
      text: `${card.title}：${card.summary}/n适用边界：${card.boundary}`,
      source_refs: [card.id],
      evidence_level: 'source_summary',
      bindings: JOBS.filter((j) => j.category_id === card.family).map((j) => ({
        job: j.id,
        stages: j.stages,
        types: ['technical_qa', 'project_deep_dive', 'business_scenario', 'mixed'],
        goals: ['understanding', 'verification', 'tradeoffs'],
      })),
    });
  for (const card of frontendReportReference.cards)
    documents.push({
      id: card.id,
      kind: 'evaluation_reference',
      evidence_level: 'platform_authored',
      text: `${card.title}：${card.key_points.join('；')}。边界：${card.boundary}。平台参考草案，未经专家校准。`,
      source_refs: CONTENT_SOURCES.filter((source) => card.source_urls.includes(source.url)).map(
        (source) => source.id,
      ),
      bindings: [
        {
          job: 'frontend',
          stages: ['internship'],
          types: allTypes,
          goals: ['understanding', 'verification'],
        },
      ],
    });
  documents.push({
    id: 'interview-method-evidence-v1',
    kind: 'interview_method',
    source_refs: [],
    evidence_level: 'platform_authored',
    text: '围绕当前岗位和候选人实际陈述，每轮只了解一个信息点。先了解本人职责与行动，再追问选择依据和验证过程。已说明的信息不重复索取，拒绝话题不推断为能力不足，没有商业指标不自动判差。',
    bindings: JOBS.map((j) => ({
      job: j.id,
      stages: j.stages,
      types: allTypes,
      goals: COMPETENCIES.map((c) => c.id),
    })),
  });
  return documents;
}
export function catalogManifest(documents = buildCatalog()) {
  const lineage = JOBS.map((j) => ({
    job: j.id,
    version: j.version,
    status: j.status,
    authorship: j.authorship,
    review_method: j.review_method,
    reviewed_at: j.reviewed_at,
    review_due_at: j.review_due_at,
    source_refs: j.source_refs,
    question_ids: j.questions.filter(isActiveQuestion).map((q) => q.id),
  }));
  return {
    format: CATALOG_FORMAT,
    jobs: JOBS.length,
    questions: documents.filter((doc) => doc.kind === 'question').length,
    families: [...new Set(JOBS.map((j) => j.category_id))],
    documents: documents.length,
    tokenizer: TOKENIZER_VERSION,
    lineage,
    sources: catalogSources,
    checksum: contentHash({
      format: CATALOG_FORMAT,
      tokenizer: TOKENIZER_VERSION,
      documents,
      lineage,
      sources: catalogSources,
    }),
    coverage: [...new Set(JOBS.map((j) => j.category_id))].map((family) => ({
