    async request(identity: RequestIdentity, id: string, body: ReportRequest, key: string) {
      await withIdempotency(
        database,
        { owner_id: identity.owner_id, operation: `reports.${id}.request`, key, input: body },
        async (tx) => {
          await interviews.lock(tx, identity, id);
          const state = await interviews.readReportState(identity, id, tx);
          if (!['completed', 'failed'].includes(state.view.status) || !state.snapshot)
            throw new ServiceError('invalid_state', 409, '请先结束面试');
          let row = await repository.reportByInterview(tx.client, identity.owner_id, id, true);
          if (!row) {
            await seal(tx, state);
            row = await repository.reportByInterview(tx.client, identity.owner_id, id);
          }
          if (!row?.result) throw new ServiceError('not_found', 404, '报告尚未请求');
          if (row.version !== body.version)
            throw new ServiceError('version_conflict', 409, '报告版本已更新');
          const results = await repository.evaluationRows(tx.client, row.id);
          const report = aggregateReport(
            state,
            {
              ...row.result,
              version: row.version,
              status: row.status as InterviewReport['status'],
            },
            results,
          );
          // A pending summary must finish before a new report version can invalidate its input.
          if (['pending', 'generating'].includes(row.status)) return { id };
          if (body.scope === 'advice') {
            if (!agent.suggest || !report.evaluations.length || report.advice_status === 'ready')
              return { id };
            if (report.advice_status === 'pending' && report.advice_task_id) {
              const task = await repository.summaryTask(tx.client, report.advice_task_id);
              if (task && !taskSettled(task)) return { id };
            }
            const next = {
              ...report,
              version: row.version + 1,
              advice_task_id: undefined,
              advice_status: undefined,
              next_steps: undefined,
            };
            await queueAdvice(tx, state, next);
            await repository.updateReport(tx.client, row.id, next.version, next);
            return { id };
          }
          if (body.scope === 'summary') {
            if (report.summary_status === 'ready' || !report.evaluations.length) return { id };
          } else if (!report.missing_turn_ids.length && row.status !== 'failed') return { id };
          const version = row.version + 1;
          const next = {
            ...report,
            version,
            advice_task_id: undefined,
            advice_status: undefined,
            next_steps: undefined,
            summary: null,
            summary_status: 'pending' as const,
            status: 'pending' as const,
          };
          if (body.scope === 'summary') await queueSummary(tx, state, next);
          else {
            await repository.setSummaryTask(tx.client, row.id, null, null);
            await queueEvaluations(
              tx,
              state,
              row.id,
              version,
              report.evaluations.map((e) => e.turn_id),
            );
          }
          await repository.updateReport(tx.client, row.id, version, next);
          return { id };
        },
      );
      return get(identity, id);
    },
    async createComparison(
      identity: RequestIdentity,
      body: {
        original_interview_id: string;
        retry_interview_id: string;
        original_turn_id: string;
        retry_turn_id: string;
        original_revision: number;
        retry_revision: number;
      },
      key: string,
    ) {
      const ref = await withIdempotency(
        database,
        { owner_id: identity.owner_id, operation: 'comparisons.create', key, input: body },
        async (tx) => {
          await lockSources(tx, identity, body.original_interview_id, body.retry_interview_id);
          const original = await interviews.lock(tx, identity, body.original_interview_id);
          const retry = await interviews.lock(tx, identity, body.retry_interview_id);
          const originalTurn = original.view.turns.find(
            (t) =>
              t.id === body.original_turn_id &&
              t.revision === body.original_revision &&
              t.answer_status === 'answered',
          );
          const retryTurn = retry.view.turns.find(
            (t) =>
              t.id === body.retry_turn_id &&
              t.revision === body.retry_revision &&
              t.answer_status === 'answered',
          );
          if (
            !['completed', 'failed'].includes(original.view.status) ||
            !['completed', 'failed'].includes(retry.view.status) ||
            !originalTurn ||
            !retryTurn ||
            retry.view.parent_interview_id !== original.view.id ||
            retry.view.parent_turn_id !== originalTurn.id ||
            retry.view.parent_revision !== originalTurn.revision ||
            retry.retryQuestion?.text !== retryTurn.text ||
            original.snapshot?.rubric_version !== retry.snapshot?.rubric_version
          )
            throw new ServiceError(
              'invalid_state',
              409,
              '只能比较同一来源的已结束单题重练与指定版本回答',
            );
          const digest = inputDigest(body);
          await tx.client.query('SELECT pg_advisory_xact_lock(hashtextextended($1,0))', [
            `comparisons:${identity.owner_id}:${digest}`,
          ]);
          const existing = await repository.comparisonByDigest(
            tx.client,
            identity.owner_id,
            digest,
          );
          if (existing) return { id: existing.id };
          const id = randomUUID();
          const value: InterviewComparison = {
            id,
            version: 1,
            task_id: null,
            ...body,
            original_text: originalTurn.answer_text!,
            retry_text: retryTurn.answer_text!,
            goal: retry.view.retry_goal ?? '回应原题并补充具体依据',
            question: originalTurn.text,
            status: 'pending',
            changes: [],
            remaining_gaps: [],
            limitations: [],
          };
          const task = await enqueueTask(tx, {
            owner_id: identity.owner_id,
            type: 'comparisons.generate.v1',
            key: `${id}:1`,
            input: {
              comparison_id: id,
              version: 1,
              original_interview_id: body.original_interview_id,
              retry_interview_id: body.retry_interview_id,
            },
          });
          value.task_id = task.id;
          await repository.insertComparison(tx.client, identity.owner_id, digest, value, task.id);
          return { id };
        },
      );
      return getComparison(identity, ref.id);
    },
    async retryComparison(
      identity: RequestIdentity,
      id: string,
      body: { version: number },
      key: string,
    ) {
      // Sources are checked before locking the comparison, preserving the publication lock order.
      const before = await repository.comparisonById(database.pool, identity.owner_id, id);
      await withIdempotency(
        database,
        { owner_id: identity.owner_id, operation: `comparisons.${id}.retry`, key, input: body },
        async (tx) => {
          await lockSources(tx, identity, before.original_interview_id, before.retry_interview_id);
          const row = await repository.comparisonById(tx.client, identity.owner_id, id, true);
          if (row.version !== body.version)
            throw new ServiceError('version_conflict', 409, '比较版本已更新');
          if (row.status !== 'failed') return { id };
          const version = row.version + 1;
          const task = await enqueueTask(tx, {
            owner_id: identity.owner_id,
            type: 'comparisons.generate.v1',
            key: `${id}:${version}`,
            input: {
              comparison_id: id,
              version,
              original_interview_id: row.original_interview_id,
              retry_interview_id: row.retry_interview_id,
            },
          });
          await repository.updateComparison(tx.client, id, version, task.id, 'pending');
          return { id };
        },
      );
      return getComparison(identity, id);
    },
    handlers: {
      'reports.evaluate.v1': evaluate,
      'reports.advice.v1': advice,
      'reports.summarize.v1': summarize,
      'comparisons.generate.v1': compare,
    },
    async maintain() {
      for (const row of await repository.pendingReports(database.pool))
        await database.transaction(async (tx) => {
          let state: InterviewState;
          try {
            state = await interviews.lock(
              tx,
              { owner_id: row.owner_id, roles: [] },
              row.interview_id,
            );
          } catch (e) {
            if (e instanceof ServiceError && e.statusCode === 404) return;
            throw e;
          }
          if (!['completed', 'failed'].includes(state.view.status)) return;
          state = await interviews.readReportState(
            { owner_id: row.owner_id, roles: [] },
            row.interview_id,
            tx,
          );
          const current = await repository.reportByInterview(
            tx.client,
            row.owner_id,
            row.interview_id,
            true,
          );
          if (
            !current ||
            !['pending', 'generating'].includes(current.status) ||
            current.input_digest !== interviewInputDigest(state)
          )
            return;
          const evaluations = await repository.evaluationRows(tx.client, row.id);
          const report = aggregateReport(
            state,
            { ...current.result!, version: current.version },
            evaluations,
          );
          if (report.analysis_progress!.pending) report.status = 'generating';
          else if (state.view.parent_interview_id) {
            await queueAdvice(tx, state, report);
            report.status = report.evaluations.length
              ? 'ready'
              : report.analysis_progress!.total
                ? 'failed'
                : 'ready';
            report.summary_status = 'not_applicable';
          } else if (!report.evaluations.length) {
            report.status = report.analysis_progress!.total ? 'failed' : 'ready';
            report.summary_status = 'not_applicable';
          } else if (
            !report.evaluations.some((e) => e.strengths.length || e.gaps.length) &&
            !reuseSingleQuestionSummary(report.evaluations, state.snapshot!, state.view.turns)
          ) {
            await queueAdvice(tx, state, report);
            report.status = 'ready';
            report.summary_status = 'not_applicable';
          } else if (!current.summary_task_id) {
            await queueSummary(tx, state, report);
          } else {
            const task = await repository.summaryTask(tx.client, current.summary_task_id);
            if (!task || taskSettled(task)) {
              // Summary publication is atomic with task success. A settled task without a summary is a failure.
              report.summary_status = report.summary ? 'ready' : 'failed';
              report.status = 'ready';
              report.is_partial ||= !report.summary;
            } else {
              report.status = 'generating';
              report.summary_status = task.task_status === 'running' ? 'generating' : 'pending';
            }
          }
          await repository.updateReport(tx.client, row.id, current.version, report);
        });
      for (const row of await repository.pendingComparisons(database.pool)) {
        const status =
          row.task_status === 'failed' &&
          (row.attempts >= row.max_attempts || row.error_code === 'unsupported_task_type')
            ? 'failed'
            : 'generating';
        // Do not overwrite a result that committed after this snapshot was read.
        await database.pool.query(
          "UPDATE interview_comparisons SET status=$2 WHERE id=$1 AND version=$3 AND status IN ('pending','generating')",
          [row.id, status, row.version],
        );
      }
    },
  };
}
export type LiveReportsService = ReturnType<typeof createReportsService>;

import { randomUUID } from 'node:crypto';
import type { PersonalMaterial, ResumeAnalysis, MaterialAnalysisStatus } from '@interviewlab/core';
import type { Database, Transaction } from '../../database/connection';
import type { BackendConfig } from '../../foundation/config';
import { inputDigest, withIdempotency } from '../../foundation/idempotency';
import { ServiceError } from '../../foundation/errors';
import { enqueueTask } from '../../tasks/service';
import type { TaskHandler } from '../../tasks/runner';
import {
  RESUME_ANALYSIS_VERSION,
  materialFields,
  type WorkflowModels,
} from '../interviews/workflow-models';

interface AnalysisRow {
  id: string;
  task_id: string;
  result: ResumeAnalysis | null;
  status: string;
  attempts: number;
  max_attempts: number;
}
export function createResumeAnalysis(
  database: Database,
  config: BackendConfig,
  models: WorkflowModels,
) {
  async function find(
    owner: string,
    material: PersonalMaterial,
    tx?: Transaction,
    model = config.LLM_MODEL,
  ) {
    return (
      await (tx?.client ?? database.pool).query<AnalysisRow>(
        `SELECT a.*,t.status,t.attempts,t.max_attempts FROM resume_analyses a JOIN tasks t ON t.id=a.task_id
      WHERE a.owner_id=$1 AND a.material_id=$2 AND a.material_version=$3 AND a.input_digest=$4 AND a.model=$5 AND a.prompt_version=$6`,
        [
          owner,
          material.id,
          material.version,
          inputDigest(materialFields(material)),
          model,
          RESUME_ANALYSIS_VERSION,
        ],
      )
    ).rows[0];
  }
  async function enqueue(
    tx: Transaction,
    owner: string,
    material: PersonalMaterial,
    retry = false,
    model = config.LLM_MODEL,
  ) {
    if (material.kind !== 'resume' || !material.confirmed || !config.LLM_API_KEY) return;
    await tx.client.query('SELECT pg_advisory_xact_lock(hashtext($1))', [
      `resume:${owner}:${material.id}:${material.version}`,
    ]);
    const existing = await find(owner, material, tx, model);
    if (
      existing?.result ||
      (existing &&
        !(retry && existing.status === 'failed' && existing.attempts >= existing.max_attempts))
    )
      return;
    const id = existing?.id ?? randomUUID(),
      run = randomUUID(),
      digest = inputDigest(materialFields(material));
    const task = await enqueueTask(tx, {
      owner_id: owner,
      type: 'resumes.analyze.v1',
      key: `${id}:${run}`,
      input: {
        analysis_id: id,
        material_id: material.id,
        material_version: material.version,
        input_digest: digest,
        model,
      },
    });
    await tx.client.query(
      `INSERT INTO resume_analyses(id,owner_id,material_id,material_version,input_digest,model,prompt_version,task_id)
      VALUES($1,$2,$3,$4,$5,$6,$7,$8) ON CONFLICT(id) DO UPDATE SET task_id=EXCLUDED.task_id,result=NULL`,
      [id, owner, material.id, material.version, digest, model, RESUME_ANALYSIS_VERSION, task.id],
    );
  }
  async function status(
    owner: string,
    material: PersonalMaterial,
  ): Promise<MaterialAnalysisStatus> {
    const row = await find(owner, material);
    if (!row) return { status: 'unavailable', task_id: null };
    return {
      status: row.result
        ? 'ready'
        : row.status === 'cancelled' ||
            (row.status === 'failed' && row.attempts >= row.max_attempts)
          ? 'failed'
          : 'pending',
      task_id: row.task_id,
    };
  }
  const handler: TaskHandler = async (task, signal) => {
    const input = task.payload as {
      analysis_id: string;
      material_id: string;
      material_version: number;
      input_digest: string;
      model: string;
    };
    const row = await database.pool.query<{ data: PersonalMaterial }>(
      `SELECT v.data FROM resume_material_versions v JOIN resume_materials m ON m.id=v.id
      WHERE m.id=$1 AND m.owner_id=$2 AND NOT m.deleted AND v.version=$3`,
      [input.material_id, task.owner_id, input.material_version],
    );
    const material = row.rows[0]?.data;
    if (!material?.confirmed || inputDigest(materialFields(material)) !== input.input_digest)
      return { result_ref: null };
    const result = await models.analyze(material, signal, task.attempts > 1, input.model);
    return {
      result_ref: { id: input.analysis_id, version: input.material_version },
      lock: async (tx) =>
        Boolean(
          (
            await tx.client.query(
              'SELECT id FROM resume_materials WHERE id=$1 AND owner_id=$2 AND NOT deleted FOR UPDATE',
              [input.material_id, task.owner_id],
            )
          ).rowCount,
        ),
      commit: async (tx) =>
        Boolean(
          (
            await tx.client.query(
              'UPDATE resume_analyses SET result=$1 WHERE id=$2 AND task_id=$3 AND input_digest=$4',
              [result, input.analysis_id, task.id, input.input_digest],
            )
          ).rowCount,
        ),
    };
  };
  return {
    enqueue,
    status,
    find,
    handlers: { 'resumes.analyze.v1': handler },
    async request(owner: string, material: PersonalMaterial, key: string) {
      if (!material.confirmed || material.kind !== 'resume')
        throw new ServiceError('unsupported_input', 400, '请先确认简历');
      if (!config.LLM_API_KEY)
        throw new ServiceError('capability_unavailable', 501, '模型尚未配置');
      await withIdempotency(
        database,
        {
          owner_id: owner,
          operation: `resume.${material.id}.analysis`,
          key,
          input: { version: material.version },
        },
        async (tx) => {
          const lock = await tx.client.query(
            'SELECT id FROM resume_materials WHERE id=$1 AND owner_id=$2 AND NOT deleted FOR UPDATE',
            [material.id, owner],
          );
          if (!lock.rowCount) throw new ServiceError('not_found', 404, '材料不存在');
          await enqueue(tx, owner, material, true);
          return { id: material.id };
        },
      );
      return status(owner, material);
    },
  };
}
export type ResumeAnalysisService = ReturnType<typeof createResumeAnalysis>;

import { extractPdf } from './pdf';
import { z } from 'zod';
import type { ZodTypeProvider } from 'fastify-type-provider-zod';
import type { BackendModule } from '../contracts';
import type { MaterialsService } from './service';
import { unavailable } from '../../foundation/errors';
const input = z
  .object({
    kind: z.enum(['resume', 'experience']),
    title: z.string().trim().min(1).max(200),
    text: z.string().trim().max(100000),
    confirmed: z.boolean(),
    structure: z.object({full_name:z.string().max(15000),phone:z.string().max(15000),email:z.string().max(15000),city:z.string().max(15000),education:z.string().max(15000),skills:z.string().max(15000),projects:z.string().max(15000),internships:z.string().max(15000),awards:z.string().max(15000),summary:z.string().max(15000)}).optional(),
  })
  .strict();
const analysisStatus=z.object({status:z.enum(['pending','ready','failed','unavailable']),task_id:z.string().nullable()});
const material = input.extend({
  analysis:analysisStatus.optional(),
  id: z.string().uuid(),
  version: z.number().int().positive(),
  created_at: z.string(),
});
const params = z.object({ id: z.string().uuid() });
export function materialsModule(service?: MaterialsService): BackendModule {
  return {
    name: 'resumes',
    async register(instance, context) {
      const app = instance.withTypeProvider<ZodTypeProvider>();
      app.post(
        '/materials/import-pdf',
        {
          bodyLimit: 8 * 1024 * 1024,
          schema: {
            body: z
              .object({
                data: z
                  .string()
                  .min(1)
                  .max(7 * 1024 * 1024),
              })
              .strict(),
            response: { 200: z.object({ text: z.string() }) },
          },
        },
        async (request) => {
          await context.requireIdentity(request);
          return { text: await extractPdf(request.body.data) };
        },
      );
      const get = () => {
        if (!service) throw unavailable('Database');
        return service;
      };
      app.post('/materials/:id/analysis', {schema:{params,headers:z.object({'idempotency-key':z.string().min(1).max(200)}).passthrough(),body:z.object({version:z.number().int().positive()}).strict(),response:{202:analysisStatus}}},async(request,reply)=>reply.code(202).send(await get().analyze((await context.requireIdentity(request)).owner_id,request.params.id,request.body.version,request.headers['idempotency-key'] as string)));
      app.get('/materials', { schema: { response: { 200: z.array(material) } } }, async (request) =>
        get().list((await context.requireIdentity(request)).owner_id),
      );
      app.get(
        '/materials/:id/versions',
        { schema: { params, response: { 200: z.array(material) } } },
        async (request) =>
          get().versions((await context.requireIdentity(request)).owner_id, request.params.id),
      );
      app.post(
        '/materials',
        { schema: { body: input, response: { 200: material } } },
        async (request) =>
          get().save((await context.requireIdentity(request)).owner_id, request.body),
      );
      app.put(
        '/materials/:id',
        {
          schema: {
            params,
            body: input.extend({ expected_version: z.number().int().positive() }),
            response: { 200: material },
          },
        },
        async (request) =>
          get().save(
            (await context.requireIdentity(request)).owner_id,
            request.body,
            request.params.id,
            request.body.expected_version,
          ),
      );
      app.delete(
        '/materials/:id',
        { schema: { params, response: { 200: z.object({ success: z.boolean() }) } } },
        async (request) => {
          await get().remove((await context.requireIdentity(request)).owner_id, request.params.id);
          return { success: true };
        },
      );
    },
  };
}

import { randomUUID } from 'node:crypto';
import type { PersonalMaterial } from '@interviewlab/core';
import type { Database } from '../../database/connection';
import type { ResumeAnalysisService } from './analysis';
import { ServiceError } from '../../foundation/errors';
export function createMaterialsService(database: Database, analysis?: ResumeAnalysisService, autoAnalyze = false) {
  async function list(owner: string): Promise<PersonalMaterial[]> {
    const result = await database.pool.query(
      `SELECT v.data FROM resume_materials m JOIN LATERAL
      (SELECT data FROM resume_material_versions WHERE id=m.id ORDER BY version DESC LIMIT 1) v ON true
      WHERE m.owner_id=$1 AND NOT m.deleted ORDER BY m.id`,
      [owner],
    );
    return Promise.all(result.rows.map(async (row) => ({...row.data, ...(analysis ? {analysis:await analysis.status(owner,row.data)} : {})})));
  }
  async function versions(owner: string, id: string): Promise<PersonalMaterial[]> {
    const result = await database.pool.query(
      `SELECT v.data FROM resume_material_versions v JOIN resume_materials m ON m.id=v.id
      WHERE m.id=$1 AND m.owner_id=$2 AND NOT m.deleted ORDER BY v.version DESC`,
      [id, owner],
    );
    if (!result.rows.length) throw new ServiceError('not_found', 404, '材料不存在');
    return Promise.all(result.rows.map(async (row) => ({...row.data, ...(analysis ? {analysis:await analysis.status(owner,row.data)} : {})})));
  }
  async function save(
    owner: string,
    input: Pick<PersonalMaterial, 'kind' | 'title' | 'text' | 'confirmed' | 'structure'>,
    id?: string,
    expected?: number,
  ) {
    if (!input.text.trim() && !Object.values(input.structure ?? {}).some(value=>value.trim())) throw new ServiceError('unsupported_input',400,'请填写简历内容');
    return database.transaction(async (tx) => {
      const {client}=tx;
      const materialId = id ?? randomUUID();
      let version = 1;
      if (id) {
        const lock = await client.query(
          'SELECT id FROM resume_materials WHERE id=$1 AND owner_id=$2 AND NOT deleted FOR UPDATE',
          [id, owner],
        );
        if (!lock.rowCount) throw new ServiceError('not_found', 404, '材料不存在');
        const latest = await client.query(
          'SELECT max(version) AS version FROM resume_material_versions WHERE id=$1',
          [id],
        );
        if (latest.rows[0].version !== expected)
          throw new ServiceError('version_conflict', 409, '材料已更新，请刷新后重试');
        const original = await client.query('SELECT kind FROM resume_materials WHERE id=$1', [id]);
        if (original.rows[0].kind !== input.kind)
          throw new ServiceError('unsupported_input', 400, '不能改变材料类型');
        version = expected! + 1;
      } else
        await client.query('INSERT INTO resume_materials(id,owner_id,kind) VALUES($1,$2,$3)', [
          materialId,
          owner,
          input.kind,
        ]);
      const data: PersonalMaterial = {
        structure: input.structure,
        kind: input.kind,
        title: input.title,
        text: input.text,
        confirmed: input.confirmed,
        id: materialId,
        version,
        created_at: new Date().toISOString(),
      };
      await client.query('INSERT INTO resume_material_versions(id,version,data) VALUES($1,$2,$3)', [
        materialId,
        version,
        JSON.stringify(data),
      ]);
      if(autoAnalyze)await analysis?.enqueue(tx,owner,data);
      return data;
    });
  }
  async function remove(owner: string, id: string) {
    await database.transaction(async(tx)=>{
      const result=await tx.client.query('UPDATE resume_materials SET deleted=true WHERE id=$1 AND owner_id=$2 AND NOT deleted RETURNING id',[id,owner]);
      if(!result.rowCount)throw new ServiceError('not_found',404,'材料不存在');
      await tx.client.query("UPDATE tasks SET status='cancelled',execution_token=NULL,lease_until=NULL WHERE owner_id=$1 AND type='resumes.analyze.v1' AND payload->>'material_id'=$2 AND status IN ('queued','running','failed')",[owner,id]);
      await tx.client.query('DELETE FROM resume_analyses WHERE owner_id=$1 AND material_id=$2',[owner,id]);
    });
  }
  async function requireResume(owner: string, id: string) {
    const [latest] = await versions(owner, id);
    if (latest.kind !== 'resume' || !latest.confirmed)
      throw new ServiceError('unsupported_input', 400, '请选择已确认的简历');
  }
  return { list, versions, save, remove, requireResume,
    async analyze(owner:string,id:string,version:number,key:string) {
      if(!analysis)throw new ServiceError('capability_unavailable',501,'简历分析未启用');
      const material=(await versions(owner,id)).find(m=>m.version===version);
      if(!material)throw new ServiceError('not_found',404,'简历版本不存在');
      return analysis.request(owner,material,key);
    },
  };
}
export type MaterialsService = ReturnType<typeof createMaterialsService>;

import { settingsModule } from '../modules/accounts/settings';
import { materialsModule } from '../modules/resumes/routes';
import { createMaterialsService } from '../modules/resumes/service';
import { randomUUID } from 'node:crypto';
import Fastify from 'fastify';
import websocket from '@fastify/websocket';
import swagger from '@fastify/swagger';
import {
  jsonSchemaTransform,
  serializerCompiler,
  validatorCompiler,
  type ZodTypeProvider,
} from 'fastify-type-provider-zod';
import { z } from 'zod';
import type { CapabilityView } from '@interviewlab/core';
import { loadConfig, type BackendConfig } from '../foundation/config';
import { installErrorHandler, unavailable } from '../foundation/errors';
import {
  requireIdentity,
  requireRole,
  requireSameOrigin,
  type IdentityProvider,
} from '../foundation/auth';
import { createAuthService } from '../modules/accounts/auth-service';
import { registerAuthRoutes } from '../modules/accounts/auth-routes';
import { createDatabase, type Database } from '../database/connection';
import { errorSchema, taskViewSchema } from '../foundation/schemas';
import { createTaskService } from '../tasks/service';
import { publicCatalogRepository } from '../modules/jobs/repository';
import { createJobsService } from '../modules/jobs/service';
import { jobsModule } from '../modules/jobs/routes';
import { validateModules, type BackendModule } from '../modules/contracts';
import { createInterviewRuntime, type InterviewRuntimeOptions } from '../modules/interview-runtime';
import { interviewsModule } from '../modules/interviews/routes';
import { reportsModule } from '../modules/reports/routes';

export interface ApplicationOptions {
  config?: BackendConfig;
  database?: Database;
  identity?: IdentityProvider;
  modules?: BackendModule[];
  logger?: boolean;
  interview?: InterviewRuntimeOptions;
}
export async function buildApp(options: ApplicationOptions = {}) {
  const config = options.config ?? loadConfig();
  const database = options.database ?? (config.DATABASE_URL ? createDatabase(config) : undefined);
  const auth = config.AUTH_ENABLED && database ? createAuthService(database, config) : undefined;
  const identity = options.identity ?? auth;
  const app = Fastify({
    logger:
      options.logger === false
        ? false
        : {
            level: config.LOG_LEVEL,
            redact: ['req.headers.authorization', 'req.headers.cookie', 'res.headers.set-cookie'],
            serializers: {
              req: (request) => ({ method: request.method, path: request.url?.split('?')[0] }),
            },
          },
    bodyLimit: config.BODY_LIMIT_BYTES,
    requestTimeout: 30000,
    genReqId: () => randomUUID(),
    // Do not trust arbitrary client request IDs or forwarded headers.
    trustProxy: false,
  });
  app.setValidatorCompiler(validatorCompiler);
  app.setSerializerCompiler(serializerCompiler);
  installErrorHandler(app);
  await app.register(websocket, { options: { maxPayload: 16384 } });
  app.addHook('onRequest', async (_request, reply) => {
    reply.header('X-InterviewLab-Mode', 'backend-foundation');
    reply.header('Cache-Control', 'no-store');
    reply.header('X-Content-Type-Options', 'nosniff');
  });
  app.addHook('onSend', async (request, reply) => {
    reply.header('X-Request-Id', request.id);
  });
  if (database && !options.database) app.addHook('onClose', () => database.close());

  try {
    const interview = database
      ? createInterviewRuntime(database, config, options.interview)
      : undefined;
    if (interview) app.addHook('onClose', () => interview.close());
    await app.register(swagger, {
      openapi: {
        openapi: '3.0.3',
        info: {
          title: 'InterviewLab Backend',
          version: '0.3.0',
          description:
            'Implemented foundation routes only. Synthetic prototype routes are separate.',
        },
      },
      transform: jsonSchemaTransform,
    });
    const materials = interview?.materials ?? (database ? createMaterialsService(database) : undefined);
    const modules = [
      ...[settingsModule(database, materials), materialsModule(materials)].filter(
        module => !options.modules?.some(custom => custom.name === module.name),
      ),
      jobsModule(createJobsService(publicCatalogRepository), database),
      ...(interview?.modules ?? [interviewsModule(undefined, { config }), reportsModule()]),
      ...(options.modules ?? []),
    ];
    validateModules(modules);
    await app.register(
      async (instance) => {
        const api = instance.withTypeProvider<ZodTypeProvider>();
        // Every real browser write, including module routes and login/logout, has one origin policy.
        instance.addHook('onRequest', async (request) => {
          if (!['GET', 'HEAD', 'OPTIONS'].includes(request.method))
            requireSameOrigin(request, config.PUBLIC_ORIGIN);
        });
        instance.addHook('onRoute', (route) => {
          const methods = Array.isArray(route.method) ? route.method : [route.method];
          if (methods.some((method) => !['GET', 'HEAD', 'OPTIONS'].includes(method))) {
            route.schema = {
              ...route.schema,
              response: {
                ...(route.schema?.response as Record<string, unknown> | undefined),
                403: errorSchema,
              },
            };
          }
        });
        const readiness = () =>
          database?.ready(config.WORKER_STALE_MS, config.AUTH_ENABLED) ??
          Promise.resolve({ database: false, worker: false });
        api.get(
          '/health',
          {
            schema: {
              tags: ['runtime'],
              response: { 200: z.object({ status: z.literal('ok') }) },
            },
          },
          async () => ({ status: 'ok' as const }),
        );
        const readinessSchema = z.object({
          status: z.enum(['ready', 'not_ready']),
          database: z.boolean(),
          worker: z.boolean(),
        });
        api.get(
          '/health/ready',
          {
            schema: {
              tags: ['runtime'],
              response: { 200: readinessSchema, 503: readinessSchema },
            },
          },
          async (_request, reply) => {
            const result = await readiness();
            const ready = result.database && result.worker;
            return reply
              .code(ready ? 200 : 503)
              .send({ status: ready ? 'ready' : 'not_ready', ...result });
          },
        );
        const capabilitySchema = z.object({
          database: z.boolean(),
          worker: z.boolean(),
          authentication: z.boolean(),
          llm: z.boolean(),
          private_storage: z.boolean(),
        }) satisfies z.ZodType<CapabilityView>;
        api.get(
          '/capabilities',
          { schema: { tags: ['runtime'], response: { 200: capabilitySchema } } },
          async () => {
            const dependencies = await readiness();
            return {
              ...dependencies,
              authentication: Boolean(identity) && (!auth || dependencies.database),
              llm: Boolean(interview?.agent.available),
              private_storage: false,
            };
          },
        );
        await registerAuthRoutes(instance, auth);
        api.get(
          '/tasks/:id',
          {
            schema: {
              tags: ['tasks'],
              params: z.object({ id: z.string().uuid() }),
              response: {
                200: taskViewSchema,
                400: errorSchema,
                401: errorSchema,
                404: errorSchema,
                501: errorSchema,
              },
            },
          },
          async (request) => {
            const principal = await requireIdentity(request, identity);
            if (!database) throw unavailable('Database');
            return createTaskService(database).get(principal, request.params.id);
          },
        );
        // The API factory registers only supplied module implementations.
        for (const module of modules) {
          await instance.register(async (scope) =>
            module.register(scope, {
              requireIdentity: (request) => requireIdentity(request, identity),
              requireRole,
            }),
          );
        }
        if (config.NODE_ENV === 'development') {
          api.get('/openapi.json', { schema: { hide: true } }, async () => app.swagger());
        }
      },
      { prefix: '/api/v1' },
    );
    await app.ready();
    return app;
  } catch (error) {
    await app.close();
    throw error;
  }
}

import { randomUUID } from 'node:crypto';
import { setTimeout as delay } from 'node:timers/promises';
import type { VersionRef } from '@interviewlab/core';
import type { Database, Transaction } from '../database/connection';
import { ServiceError } from '../foundation/errors';
import { versionRefSchema } from '../foundation/schemas';
import type { TaskRow } from './service';
export interface TaskOutcome {
  result_ref: VersionRef | null;
  /** Acquire module locks before the task lock, matching command lock order. False discards stale output. */
  lock?: (tx: Transaction) => Promise<boolean | void>;
  /** False releases the transaction and waits to publish this same result, without another model call. */
  publicationReady?: (tx: Transaction) => Promise<boolean>;
  /** Database-only publication. Runs atomically with succeeded, after checking the active claim. */
  commit?: (tx: Transaction) => Promise<boolean | void>;
}
export type TaskHandler = (task: Readonly<TaskRow>, signal: AbortSignal) => Promise<TaskOutcome>;
export type TaskHandlers = Readonly<Record<string, TaskHandler>>;
export class TaskDeliveryError extends Error {}

export async function runTask(
  database: Database,
  id: string,
  handlers: TaskHandlers,
  leaseMs = 60000,
  isCancelled?: (task: Readonly<TaskRow>) => Promise<boolean>,
) {
  const token = randomUUID();
  const claimed = await database.transaction(async (tx) => {
    const result = await tx.client.query<TaskRow>(
      'SELECT *, lease_until > clock_timestamp() AS lease_active FROM tasks WHERE id=$1 FOR UPDATE',
      [id],
    );
    const task = result.rows[0];
    if (!task || task.status === 'succeeded' || task.status === 'cancelled') return null;
    if (task.status === 'running' && task.lease_active)
      throw new TaskDeliveryError('Task is already running');
    if (!Object.hasOwn(handlers, task.type) || typeof handlers[task.type] !== 'function') {
      await tx.client.query(
        "UPDATE tasks SET status='failed',error_code='unsupported_task_type',updated_at=now() WHERE id=$1",
        [id],
      );
      return null;
    }
    if (task.attempts >= task.max_attempts) {
      await tx.client.query(
        "UPDATE tasks SET status='failed',error_code=COALESCE(error_code,'attempts_exhausted'),updated_at=now(),execution_token=NULL,lease_until=NULL WHERE id=$1",
        [id],
      );
      return null;
    }
    const update = await tx.client.query<TaskRow>(
      "UPDATE tasks SET status='running',attempts=attempts+1,execution_token=$2,lease_until=now()+$3*interval '1 millisecond',error_code=NULL,updated_at=now() WHERE id=$1 RETURNING *",
      [id, token, leaseMs],
    );
    return update.rows[0];
  });
  if (!claimed) return;
  const controller = new AbortController();
  let timer: ReturnType<typeof setTimeout> | undefined;
  let cancellationTimer: ReturnType<typeof setInterval> | undefined;
  let checking = false;
  try {
    const outcome = await Promise.race([
      handlers[claimed.type](claimed, controller.signal),
      new Promise<never>((_, reject) => {
        timer = setTimeout(() => {
          const error = new TaskDeliveryError('Task timed out');
          controller.abort(error);
          reject(error);
        }, leaseMs);
      }),
      new Promise<never>((_, reject) => {
        cancellationTimer = setInterval(() => {
          if (checking) return;
          checking = true;
          void (async () => {
            const result = await database.pool.query(
              'SELECT status,execution_token FROM tasks WHERE id=$1',
              [id],
            );
            const row = result.rows[0];
            if (
              !row ||
              row.status !== 'running' ||
              row.execution_token !== token ||
              (await isCancelled?.(claimed))
            ) {
              const error = new ServiceError('task_cancelled', 409, 'Task cancelled');
              controller.abort(error);
              reject(error);
            }
          })()
            .catch(() => {
              const error = new TaskDeliveryError('Cancellation check failed');
              controller.abort(error);
              reject(error);
            })
            .finally(() => {
              checking = false;
            });
        }, 500);
      }),
    ]);
    if (outcome.result_ref !== null) versionRefSchema.parse(outcome.result_ref);
    let publishedOutcome = false;
    while (!publishedOutcome) {
      if (controller.signal.aborted) throw controller.signal.reason;
      publishedOutcome = await database.transaction(async (tx) => {
        const validSource = await outcome.lock?.(tx);
        const current = await tx.client.query<TaskRow>(
          'SELECT *, lease_until > clock_timestamp() AS lease_active FROM tasks WHERE id=$1 FOR UPDATE',
          [id],
        );
        const row = current.rows[0];
        if (!row || row.status !== 'running' || row.execution_token !== token || !row.lease_active)
          throw new TaskDeliveryError('Task claim expired');
        if (
          validSource !== false &&
          outcome.publicationReady &&
          !(await outcome.publicationReady(tx))
        )
          return false;
        const published = validSource === false ? false : await outcome.commit?.(tx);
        await tx.client.query(
          'UPDATE tasks SET status=$3,result_ref=$2::jsonb,execution_token=NULL,lease_until=NULL,error_code=NULL,updated_at=now() WHERE id=$1',
          [
            id,
            published === false ? null : JSON.stringify(outcome.result_ref),
            published === false ? 'cancelled' : 'succeeded',
          ],
        );
        return true;
      });
      if (!publishedOutcome) await delay(50, undefined, { signal: controller.signal });
    }
  } catch (error) {
    const failure = controller.signal.aborted ? controller.signal.reason : error;
    const code =
      failure instanceof ServiceError
        ? failure.code
        : failure instanceof TaskDeliveryError
          ? 'task_timeout'
          : 'task_failed';
    const result = await database.pool.query(
      "UPDATE tasks SET status=CASE WHEN $3='task_cancelled' THEN 'cancelled' ELSE 'failed' END,error_code=$3,execution_token=NULL,lease_until=NULL,updated_at=now() WHERE id=$1 AND execution_token=$2 AND status='running' RETURNING attempts,max_attempts",
      [id, token, code],
    );
    const row = result.rows[0];
    if (row && code !== 'task_cancelled' && row.attempts < row.max_attempts)
      throw new TaskDeliveryError('Task failed; retry pending');
  } finally {
    controller.abort();
    if (timer) clearTimeout(timer);
    if (cancellationTimer) clearInterval(cancellationTimer);
  }
}

import { randomUUID } from 'node:crypto';
import type { RequestIdentity, TaskView } from '@interviewlab/core';
import type { Database, Transaction } from '../database/connection';
import { ServiceError } from '../foundation/errors';
import { assertIdempotencyKey, inputDigest } from '../foundation/idempotency';

export interface TaskInput {
  owner_id: string;
  type: string;
  key: string;
  input: unknown;
  max_attempts?: number;
}
export interface TaskRow extends Omit<TaskView, 'created_at' | 'updated_at'> {
  key: string;
  owner_id: string;
  payload: unknown;
  execution_token: string | null;
  lease_until: Date | null;
  lease_active?: boolean;
  created_at: Date;
  updated_at: Date;
}
export async function enqueueTask(tx: Transaction, input: TaskInput): Promise<TaskView> {
  assertIdempotencyKey(input.key);
  if (
    !/^[a-z][a-z0-9_.-]{0,99}$/.test(input.type) ||
    !input.owner_id ||
    !Number.isInteger(input.max_attempts ?? 2) ||
    (input.max_attempts ?? 2) < 1 ||
    (input.max_attempts ?? 2) > 5
  )
    throw new ServiceError('unsupported_input', 400, 'Invalid task configuration');
  const digest = inputDigest(input.input);
  const id = randomUUID();
  await tx.client.query(
    'INSERT INTO tasks (id,owner_id,type,key,input_digest,payload,max_attempts) VALUES ($1,$2,$3,$4,$5,$6::jsonb,$7) ON CONFLICT (owner_id,type,key) DO NOTHING',
    [
      id,
      input.owner_id,
      input.type,
      input.key,
      digest,
      JSON.stringify(input.input),
      input.max_attempts ?? 2,
    ],
  );
  const result = await tx.client.query<TaskRow>(
    'SELECT * FROM tasks WHERE owner_id=$1 AND type=$2 AND key=$3',
    [input.owner_id, input.type, input.key],
  );
  const row = result.rows[0];
  if (row.input_digest !== digest)
    throw new ServiceError('version_conflict', 409, 'Task key has different input');
  await tx.client.query(
    'INSERT INTO outbox_events (id,task_id) VALUES ($1,$2) ON CONFLICT (task_id) DO NOTHING',
    [randomUUID(), row.id],
  );
  await tx.client.query("SELECT pg_notify('interview_outbox','ready')");
  return taskView(row);
}
export function taskView(row: TaskRow): TaskView {
  return {
    id: row.id,
    type: row.type,
    status: row.status,
    input_digest: row.input_digest,
    attempts: row.attempts,
    max_attempts: row.max_attempts,
    result_ref: row.result_ref,
    error_code: row.error_code,
    created_at: row.created_at.toISOString(),
    updated_at: row.updated_at.toISOString(),
  };
}
export function createTaskService(database: Database) {
  return {
    async get(identity: RequestIdentity, id: string): Promise<TaskView> {
      const result = await database.pool.query<TaskRow>(
        'SELECT * FROM tasks WHERE id=$1 AND owner_id=$2',
        [id, identity.owner_id],
      );
      if (!result.rowCount) throw new ServiceError('not_found', 404, 'Task not found');
      return taskView(result.rows[0]);
    },
    enqueue: (input: TaskInput) => database.transaction((tx) => enqueueTask(tx, input)),
  };
}

import { Client } from 'pg';
import { randomUUID } from 'node:crypto';
import { setTimeout as delay } from 'node:timers/promises';
import type { BackendConfig } from '../foundation/config';
import { createDatabase, type Database } from '../database/connection';
import { createQueue, TASK_QUEUE, REPORT_QUEUE, PREPARATION_QUEUE } from './queue';
import { dispatchOutbox } from './outbox';
import { runTask, type TaskHandlers } from './runner';
import type { TaskRow } from './service';

export interface WorkerOptions {
  database?: Database;
  handlers?: TaskHandlers;
  onError?: (code: string) => void;
  maintain?: () => Promise<void>;
  isCancelled?: (task: Readonly<TaskRow>) => Promise<boolean>;
}
export async function startWorker(config: BackendConfig, options: WorkerOptions = {}) {
  const database = options.database ?? createDatabase(config);
  const boss = createQueue(config);
  const handlers = options.handlers ?? {};
  const id = randomUUID();
  const controller = new AbortController();
  const reportError = options.onError ?? (() => {});
  const heartbeat = async () => {
    await database.pool.query(
      'INSERT INTO worker_heartbeats (id,supported_types) VALUES ($1,$2::jsonb) ON CONFLICT (id) DO UPDATE SET last_seen_at=now(),supported_types=EXCLUDED.supported_types',
      [id, JSON.stringify(Object.keys(handlers))],
    );
    await database.pool.query(
      "DELETE FROM worker_heartbeats WHERE last_seen_at < now()-interval '1 day'",
    );
  };
  boss.on('error', () => reportError('queue_error'));
  let wakeClient: Client | undefined;
  let wakePending: Promise<unknown> | undefined;
  const wake = () => {
    wakePending ??= dispatchOutbox(database, boss)
      .catch(() => reportError('outbox_error'))
      .finally(() => {
        wakePending = undefined;
      });
  };
  let outboxLoop: Promise<void> | undefined;
  let heartbeatLoop: Promise<void> | undefined;
  let maintenanceLoop: Promise<void> | undefined;
  try {
    await database.pool.query('SELECT id FROM tasks LIMIT 0');
    await boss.start();
    for (const [queue, concurrency] of [
      [TASK_QUEUE, config.WORKER_CONCURRENCY],
      [REPORT_QUEUE, config.WORKER_REPORT_CONCURRENCY],
      [PREPARATION_QUEUE, config.WORKER_PREPARATION_CONCURRENCY],
    ] as const) {
      await boss.createQueue(queue);
      await boss.work<{ task_id: string }>(
        queue,
        { batchSize: 1, pollingIntervalSeconds: 0.5, localConcurrency: concurrency },
        async (jobs) => {
          for (const job of jobs)
            await runTask(database, job.data.task_id, handlers, 60000, options.isCancelled);
        },
      );
    }
    wakeClient = new Client(database.pool.options);
    await wakeClient.connect();
    wakeClient.on('notification', wake);
    wakeClient.on('error', () => reportError('outbox_listener_error'));
    await wakeClient.query('LISTEN interview_outbox');
    await heartbeat();
    const loop = async (interval: number, work: () => Promise<unknown>, code: string) => {
      while (!controller.signal.aborted) {
        try {
          await work();
        } catch {
          reportError(code);
        }
        await delay(interval, undefined, { signal: controller.signal }).catch(() => {});
      }
    };
    outboxLoop = loop(config.WORKER_POLL_MS, () => dispatchOutbox(database, boss), 'outbox_error');
    heartbeatLoop = loop(config.WORKER_HEARTBEAT_MS, heartbeat, 'heartbeat_error');
    if (options.maintain) maintenanceLoop = loop(1000, options.maintain, 'maintenance_error');
  } catch (error) {
    controller.abort();
    await wakeClient?.end().catch(() => {});
    await boss.stop().catch(() => {});
    await database.pool.query('DELETE FROM worker_heartbeats WHERE id=$1', [id]).catch(() => {});
    if (!options.database) await database.close();
    throw error;
  }
  let closing: Promise<void> | undefined;
  return {
    id,
    close() {
      closing ??= (async () => {
        controller.abort();
        if (wakeClient) {
          await wakeClient.query('UNLISTEN interview_outbox').catch(() => {});
          await wakeClient.end();
          wakeClient = undefined;
        }
        await wakePending;
        await Promise.all([outboxLoop, heartbeatLoop, maintenanceLoop]);
        try {
          await boss.stop({ graceful: true, timeout: 65000 });
        } finally {
          try {
            await database.pool.query('DELETE FROM worker_heartbeats WHERE id=$1', [id]);
          } finally {
            if (!options.database) await database.close();
          }
        }
      })();
      return closing;
    },
  };
}

import type { InterviewConfig, Interview } from './live-interview';
import type { InterviewMemory as Memory } from './interview-agent';
import { mainQuestionLimit } from './live-interview';

export const INTERVIEW_POLICY_VERSION = 'interview-policy-v3';
export const ACTIVE_INTERVIEW_TYPES = ['technical_qa', 'business_scenario', 'hr', 'mixed'] as const;
export interface InterviewTheme {
  goal: string;
  purpose: string;
  probe: string;
  stop: string;
}
const theme = (goal: string, purpose: string, probe: string): InterviewTheme => ({
  goal,
  purpose,
  probe,
  stop: '关键依据已清楚、明确不会或未参与、拒绝，或一次澄清后仍无新增信息时转场',
});
export function interviewPolicy(config: InterviewConfig) {
  const professional = [
    theme(
      'understanding',
      '目标岗位实际工作需要的基础知识与适用边界',
      '结合已学内容或实际参与的工作问一个岗位相关原理',
    ),
    theme(
      'contribution',
      '核对简历项目中的实际参与范围与本人行动',
      '仅询问本人承担的部分；没有项目可用课程、练习或作业',
    ),
    theme(
      'verification',
      '实际方法、验证依据与问题定位',
      '问如何发现或检验一个具体结果，不预设线上规模',
    ),
    theme('tradeoffs', '约束下的专业判断', '围绕真实选择问依据，不考与岗位无关的偏题'),
    theme('learning', '实践心得、反馈与改进', '问一次具体反思或后续尝试'),
    theme('motivation', '岗位理解与准备', '从岗位任务及所做准备了解匹配程度'),
  ];
  const business = [
    theme(
      'business',
      '目标岗位实际任务的目标、对象与成功标准',
      '结合岗位任务或实际项目，不统一套产品或商业收入指标',
    ),
    theme('contribution', '本人在任务中的职责与行动', '区分本人参与和团队成果，不深入其未参与部分'),
    theme('tradeoffs', '约束、优先级与决策依据', '针对一个实际冲突了解如何判断取舍'),
    theme(
      'understanding',
      '完成岗位任务所需的专业判断',
      '了解方法及适用边界，不转成代码或术语考试',
    ),
    theme('verification', '任务结果与验证', '问如何确认任务完成或发现偏差，接受非商业结果'),
    theme('learning', '协作、复盘与调整', '问得到反馈后具体调整了什么'),
    theme('motivation', '岗位任务理解与准备', '从任务认识及准备过程了解匹配程度'),
  ];
  const hr = [
    theme('motivation', '求职动机、岗位选择与准备', '了解选择依据，不追问专业实现'),
    theme(
      'availability',
      config.career_stage === 'internship'
        ? '到岗时间、每周可出勤天数与可持续实习时长'
        : '可到岗时间与工作地点意向',
      '每次问一个尚未说明的安排，允许跳过',
    ),
    theme('expectations', '薪资期望与求职关注点', '只了解期望，不编造企业待遇，不评价薪资高低'),
    theme('collaboration', '具体协作行为与职责边界', '可以结合项目，但只了解沟通行动与分工'),
    theme('learning', '学习反馈与反思', '了解一次具体调整，不追技术细节'),
  ];
  const themes =
    config.interview_type === 'hr'
      ? hr
      : config.interview_type === 'business_scenario'
        ? business
        : config.interview_type === 'mixed'
          ? [...professional, hr[1], hr[2], business[0]]
          : professional;
  return {
    version: INTERVIEW_POLICY_VERSION,
    themes,
    opening_seconds: config.duration_minutes === 5 ? 30 : 60,
    core_seconds:
      config.duration_minutes * 60 -
      (config.duration_minutes === 5 ? 90 : config.duration_minutes === 10 ? 150 : 180),
    closing_seconds: config.duration_minutes === 5 ? 60 : config.duration_minutes === 10 ? 90 : 120,
    core_theme_target:
      config.duration_minutes === 5
        ? [2, 3]
        : config.duration_minutes === 10
          ? [3, 4]
          : config.duration_minutes === 20
            ? [5, 6]
            : [6, 8],
    required_dimensions: config.interview_type !== 'hr',
    mixed_allocation:
      config.interview_type === 'mixed' ? { professional: 50, business: 30, hr: 20 } : null,
    focus:
      config.interview_type === 'hr'
        ? '求职动机与实际安排优先，有时间再展开协作反思；不考技术实现'
        : config.interview_type === 'business_scenario'
          ? '岗位实际工作判断；可讨论项目，重点是目标、约束、方法、结果与心得'
          : config.interview_type === 'mixed'
            ? '专业、业务和HR按时间组合；已展开的线索先收束，不机械轮换阶段'
            : '岗位相关知识与实际运用；通过项目核对参与、依据与心得，不只问项目介绍',
  };
}

export function interviewPacing(interview: Interview, memory: Memory | null, now = Date.now()) {
  const policy = interviewPolicy(interview.configuration);
  const last = interview.turns.at(-1);
  const remaining = interview.target_at
    ? Math.max(0, (Date.parse(interview.target_at) - now) / 1000)
    : interview.configuration.duration_minutes * 60;
  const closing = remaining <= policy.closing_seconds;
  const focus = memory?.observations?.find((o) => o.goal === memory.focus);
  const settled = focus && ['covered', 'inconclusive', 'not_applicable'].includes(focus.state);
  const act = memory?.conversation?.last_act;
  const previous = interview.turns
    .slice(0, -1)
    .filter(
      (t) => t.main_question_index === last?.main_question_index && t.answer_status === 'answered',
    )
    .at(-1);
  const repeated =
    !!last?.answer_text &&
    !!previous?.answer_text &&
    last.answer_text.replace(//s/g, '') === previous.answer_text.replace(//s/g, '');
  const maxFollowups = interview.configuration.interviewer_style === '深入追问' ? 2 : 1;
  const elapsedCore = Math.max(
    0,
    interview.configuration.duration_minutes * 60 - remaining - policy.opening_seconds,
  );
  const mixedFocus =
    elapsedCore >= policy.core_seconds * 0.8 ||
    (last?.main_question_index ?? 0) >=
      Math.ceil(mainQuestionLimit(interview.configuration.duration_minutes) * 0.8)
      ? 'hr'
      : elapsedCore >= policy.core_seconds * 0.5 ||
          (last?.main_question_index ?? 0) >=
            Math.ceil(mainQuestionLimit(interview.configuration.duration_minutes) * 0.6)
        ? 'business'
        : 'professional';
  return {
    remaining_seconds: Math.round(remaining),
    phase: closing ? 'closing' : 'core',
    allow_follow_up:
      !!last &&
      last.follow_up_index < maxFollowups &&
      !closing &&
      !settled &&
      !repeated &&
      act !== 'decline_topic' &&
      act !== 'dont_know',
    max_follow_ups: maxFollowups,
    preferred_goals:
      interview.configuration.interview_type === 'mixed'
        ? mixedFocus === 'hr'
          ? ['motivation', 'availability', 'expectations', 'learning', 'collaboration']
          : mixedFocus === 'business'
            ? ['business', 'tradeoffs', 'verification']
            : ['understanding', 'contribution', 'verification', 'tradeoffs']
        : policy.themes.map((t) => t.goal),
  };
}

import type {
  ContentSource,
  JobSearchQuery,
  JobTemplate,
  KnowledgeEntry,
  KnowledgeInterviewType,
  KnowledgeQuestion,
  KnowledgeRetriever,
  SupplementalQuestion,
} from './domain/knowledge';
export function templateJd(job: JobTemplate): string {
  return `${job.title}/n/n岗位职责/n${job.responsibilities.join('/n')}/n/n基础要求/n${job.requirements.join('/n')}/n/n加分项/n${job.preferred.join('/n')}`;
}
export function isActiveQuestion(question: KnowledgeQuestion): boolean {
  return question.status !== 'merged';
}

/** Every authored question remains eligible for mixed interviews; explicit types add focus. */
export function questionInterviewTypes(
  question: Pick<KnowledgeQuestion, 'question_type' | 'interview_types'>,
): KnowledgeInterviewType[] {
  const explicit = question.interview_types?.length
    ? [...question.interview_types]
    : question.question_type === 'technical'
      ? ['technical_qa' as const]
      : question.question_type === 'business_scenario'
        ? ['business_scenario' as const]
        : question.question_type === 'project' || question.question_type === 'behavioral'
          ? ['project_deep_dive' as const]
          : question.question_type === 'hr'
            ? ['hr' as const]
            : ['technical_qa' as const, 'project_deep_dive' as const];
  return [...new Set<KnowledgeInterviewType>([...explicit, 'mixed'])];
}

/** Structured retrieval view of original content, never user resumes or pasted private JDs. */
export function knowledgeEntries(job: JobTemplate): KnowledgeEntry[] {
  const common = {
    job_id: job.id,
    template_version: job.version,
    stages: job.stages,
    status: job.status,
  };
  return [
    {
      ...common,
      id: `${job.id}-profile-v${job.version}`,
      kind: 'job_profile',
      title: job.title,
      body: templateJd(job),
      topics: job.topics,
      source_refs: job.source_refs,
    },
    ...job.questions.filter(isActiveQuestion).map((q) => ({
      ...common,
      id: `${q.id}-outline-v${job.version}`,
      kind: 'preparation_outline' as const,
      title: q.topic,
      body: `${q.intent}。准备观察方向：${q.observation_points.join('、')}。追问：${q.follow_ups.join('；')}。此提纲不是完整标准答案或对用户的评价。`,
      topics: [q.topic],
      stages: q.stages,
      source_refs: q.source_refs,
    })),
  ];
}

/** Pure registry: callers supply versioned public content; no file or network access. */
export function createJobCatalog(
  templates: JobTemplate[],
  sources: ContentSource[],
  supplementalQuestions: SupplementalQuestion[] = [],
) {
  const ALL_JOB_TEMPLATES = templates;
  const JOBS = templates.filter((j) => j.status === 'published');
  const CONTENT_SOURCES = sources;
  const SUPPLEMENTAL_QUESTIONS = supplementalQuestions.filter((question) => question.runtime_enabled);
  const aliases: Record<string, string> = {
    java: 'backend',
    'java-backend': 'backend',
    'machine-learning': 'algorithm',
    'software-testing': 'testing',
  };
  function getJob(id: string): JobTemplate | undefined {
    return JOBS.find(
      (j) => j.status === 'published' && (j.id === (aliases[id] ?? id) || j.slug === id),
    );
  }
  function searchJobs(query: JobSearchQuery = {}) {
    const text = query.search?.trim().toLowerCase();
    return JOBS.filter(
      (j) =>
        j.status === 'published' &&
        (!query.category || j.category_id === query.category) &&
        (!query.primary_class || j.primary_class_id === query.primary_class) &&
        (!query.stage || j.stages.includes(query.stage)) &&
        (!text ||
          [j.title, j.description, ...j.tags, ...j.topics].join(' ').toLowerCase().includes(text)),
    );
  }
  const localKnowledgeRetriever: KnowledgeRetriever = {
    async retrieve(query) {
      const job = getJob(query.job_id);
      if (!job) throw new Error('岗位模板未发布或已不可用。');
      const supplementalQuestions = SUPPLEMENTAL_QUESTIONS.filter(
        (question) =>
          question.eligible_job_ids.includes(job.id) &&
          (!query.stage || question.stages.includes(query.stage)) &&
          (!query.topic || question.topic === query.topic) &&
          (!query.difficulty || question.difficulty === query.difficulty) &&
          (!query.interview_type || question.interview_types.includes(query.interview_type)),
      );
      const sourceRefs = new Set([
        ...job.source_refs,
        ...supplementalQuestions.flatMap((question) => question.source_refs),
      ]);
      return {
        template_id: job.id,
        template_version: job.version,
        knowledge: knowledgeEntries(job).filter(
          (e) =>
            (!query.stage || e.stages.includes(query.stage)) &&
            (!query.topic || e.topics.includes(query.topic)) &&
            (!query.difficulty || query.difficulty === '基础'),
        ),
        items: job.questions.filter(
          (q) =>
            isActiveQuestion(q) &&
            (!query.stage || q.stages.includes(query.stage)) &&
            (!query.topic || q.topic === query.topic) &&
            (!query.difficulty || q.difficulty === query.difficulty) &&
            (!query.interview_type || questionInterviewTypes(q).includes(query.interview_type)),
        ),
        supplemental_questions: supplementalQuestions,
        sources: CONTENT_SOURCES.filter((source) => sourceRefs.has(source.id)),
      };
    },
  };

  return { ALL_JOB_TEMPLATES, JOBS, getJob, searchJobs, localKnowledgeRetriever };
}

import type { InterviewReport } from './live-interview';
import { FEEDBACK_DIMENSIONS } from './feedback-template';
import { reportFeedback } from './question-scoring';
export function summarizePerformance(reports: InterviewReport[]) {
  const ready = reports.filter(
    (r) =>
      r.status === 'ready' &&
      !r.needs_refresh &&
      (reportFeedback(r)?.assessments.some(
        (a) => Number.isFinite(a.score) && a.score >= 0 && a.score <= 100,
      ) ||
        Object.values(r.dimensions ?? {}).some(
          (d) =>
            d.status === 'observed' &&
            d.score !== null &&
            Number.isFinite(d.score) &&
            d.evidence_refs.length,
        )),
  );
  const rubric =
    ready[0]?.question_scoring_version ??
    ready[0]?.analysis_metadata?.scoring_rubric_version ??
    ready[0]?.analysis_metadata?.rubric_version;
  const comparable = ready.filter(
    (r) =>
      (r.question_scoring_version ??
        r.analysis_metadata?.scoring_rubric_version ??
        r.analysis_metadata?.rubric_version) === rubric,
  );
  const modern = Boolean(ready[0] && reportFeedback(ready[0])?.assessments.length);
  const keys = modern
    ? FEEDBACK_DIMENSIONS.map((d) => d.key)
    : ([
        'technical_knowledge',
        'project_communication',
        'logical_expression',
        'coding_ability',
      ] as const);
  const dimensions = keys.map((key) => {
    const values = comparable.flatMap((r) => {
      if (modern) {
        const a = reportFeedback(r)?.assessments.find((a) => a.dimension === key);
        return a && Number.isFinite(a.score) && a.score >= 0 && a.score <= 100
          ? [{ score: a.score, interview_id: r.interview_id, explanation: a.text }]
          : [];
      }
      const d = r.dimensions[key as keyof InterviewReport['dimensions']];
      return d?.status === 'observed' &&
        d.score !== null &&
        Number.isFinite(d.score) &&
        d.evidence_refs.length
        ? [{ score: d.score, interview_id: r.interview_id, explanation: d.explanation }]
        : [];
    });
    return {
      key,
      count: values.length,
      score: values.length ? values.reduce((a, b) => a + b.score, 0) / values.length : null,
      sources: values,
    };
  });
  return {
    rubric,
    count: comparable.length,
    excluded: ready.length - comparable.length,
    dimensions,
  };
}

import {
  FEEDBACK_DIMENSIONS,
  type FeedbackAssessment,
  type FeedbackObservation,
} from './feedback-template';
import type { InterviewResponseAssessment } from './interview-response';
import { evidenceMatches } from './live-interview';
import type { InterviewEvaluation, InterviewTurn, InterviewReport } from './live-interview';

export const QUESTION_SCORING_VERSION = 'question-six-v1';
export const HR_SCORING_VERSION = 'question-observed-v2';
export const EVIDENCE_SCORING_VERSION = 'question-evidence-v3';
export const WHOLE_INTERVIEW_SCORING_VERSION = 'whole-interview-six-v1';
export const isQuestionScoringVersion = (version: string | undefined) =>
  version === QUESTION_SCORING_VERSION ||
  version === HR_SCORING_VERSION ||
  version === EVIDENCE_SCORING_VERSION;
export interface AssessedResponse extends InterviewResponseAssessment {
  turn_id: string;
  revision: number;
  question_scope: ScoringQuestionScope;
  knowledge_evidence?: 'demonstrated' | 'claim_only' | 'not_present' | 'unclear';
}
export const QUESTION_SCOPE_KINDS = [
  'closed_fact',
  'explanation',
  'experience_detail',
  'decision_process',
  'reflection',
  'motivation',
  'administrative',
  'protocol',
] as const;
export interface ScoringQuestionScope {
  kind: (typeof QUESTION_SCOPE_KINDS)[number];
  dimensions: import('./feedback-template').FeedbackDimensionKey[];
  expectation: string;
}
export function validQuestionScope(scope: ScoringQuestionScope): boolean {
  if (new Set(scope.dimensions).size !== scope.dimensions.length) return false;
  if (['administrative', 'protocol'].includes(scope.kind)) return scope.dimensions.length === 0;
  if (scope.kind === 'closed_fact')
    return (
      scope.dimensions.length <= 1 &&
      scope.dimensions.every((d) => ['professional_foundation', 'project_reflection'].includes(d))
    );
  return true;
}
export function responseCanSupportScore(response: InterviewResponseAssessment): boolean {
  return (
    response.response_eligibility === 'answer' &&
    response.relevance !== 'nonresponsive' &&
    response.sufficiency !== 'not_applicable' &&
    ['answer', 'dont_know'].includes(response.act)
  );
}
export function validObservedScores(
  values: FeedbackAssessment[] | undefined,
): values is FeedbackAssessment[] {
  return (
    !!values &&
    values.length <= 6 &&
    new Set(values.map((a) => a.dimension)).size === values.length &&
    values.every(
      (a) =>
        FEEDBACK_DIMENSIONS.some((d) => d.key === a.dimension) &&
        Number.isFinite(a.score) &&
        a.score >= 0 &&
        a.score <= 100,
    )
  );
}
export function weightedObservedScore(values: FeedbackAssessment[]): number | null {
  if (!validObservedScores(values)) throw new Error('Invalid observed dimension scores');
  const weight = values.reduce(
    (sum, a) => sum + FEEDBACK_DIMENSIONS.find((d) => d.key === a.dimension)!.weight,
    0,
  );
  return weight
    ? values.reduce(
        (sum, a) => sum + a.score * FEEDBACK_DIMENSIONS.find((d) => d.key === a.dimension)!.weight,
        0,
      ) / weight
    : null;
}
export interface QuestionScore {
  turn_id: string;
  main_question_index: number;
  turn_ids: string[];
  score: number;
  assessments: FeedbackAssessment[];
}
export function completeSixScores(
  values: FeedbackAssessment[] | undefined,
): values is FeedbackAssessment[] {
  return (
    !!values &&
    values.length === 6 &&
    new Set(values.map((a) => a.dimension)).size === 6 &&
    FEEDBACK_DIMENSIONS.every((d) =>
      values.some(
        (a) => a.dimension === d.key && Number.isFinite(a.score) && a.score >= 0 && a.score <= 100,
      ),
    )
  );
}
/** Preserve precision until display; every dimension uses its fixed weight. */
export function weightedQuestionScore(values: FeedbackAssessment[]): number {
  if (!completeSixScores(values)) throw new Error('Six complete dimension scores are required');
  return (
    FEEDBACK_DIMENSIONS.reduce(
      (sum, d) => sum + values.find((a) => a.dimension === d.key)!.score * d.weight,
      0,
    ) / 100
  );
}
export function questionScores(
  turns: InterviewTurn[],
  evaluations: InterviewEvaluation[],
): QuestionScore[] {
  const groups = new Map<number, InterviewTurn[]>();
  for (const turn of turns) {
    if (turn.answer_status === 'answered')
      groups.set(turn.main_question_index, [...(groups.get(turn.main_question_index) ?? []), turn]);
  }
  return [...groups]
    .sort(([a], [b]) => a - b)
    .flatMap(([index, group]) => {
      group.sort((a, b) => a.follow_up_index - b.follow_up_index);
      // The last cumulative evaluation includes earlier answers; a failed last answer must not use an earlier score.
      const last = group.at(-1)!;
      const e = evaluations.find(
        (v) =>
          v.turn_id === last.id &&
          v.revision === last.revision &&
          isQuestionScoringVersion(v.question_scoring_version),
      );
      if (
        !e ||
        !e.feedback_assessments ||
        !([HR_SCORING_VERSION, EVIDENCE_SCORING_VERSION].includes(e.question_scoring_version ?? '')
          ? validObservedScores(e.feedback_assessments)
          : completeSixScores(e.feedback_assessments)) ||
        !e.feedback_assessments.length
      )
        return [];
      if (
        e.question_scoring_version === EVIDENCE_SCORING_VERSION &&
        e.feedback_assessments.some(
          (a) =>
            !a.evidence_refs.length ||
            a.evidence_refs.some(
              (ref) =>
                !evidenceMatches(ref, group) ||
                !e.response_assessments?.some(
                  (r) =>
                    r.turn_id === ref.turn_id &&
                    r.revision === ref.revision &&
                    responseCanSupportScore(r),
                ),
            ),
        )
      )
        return [];
      return [
        {
          turn_id: group[0].id,
          main_question_index: index,
          turn_ids: group.map((t) => t.id),
          score: weightedObservedScore(e.feedback_assessments)!,
          assessments: e.feedback_assessments,
        },
      ];
    });
}
export function aggregateQuestionAssessments(questions: QuestionScore[]): FeedbackAssessment[] {
  if (!questions.length) return [];
  return FEEDBACK_DIMENSIONS.flatMap((d) => {
    const values = questions.flatMap((q) => q.assessments.filter((a) => a.dimension === d.key));
    if (!values.length) return [];
    if (values.length === 1) return values;
    return [
      {
        dimension: d.key,
        score: values.reduce((sum, a) => sum + a.score, 0) / values.length,
        text: `按 ${values.length} 道已考察本维度的主问题等权平均；${d.short}评价本场回答展示。`,
        evidence_refs: [
          ...new Map(
            values.flatMap((a) => a.evidence_refs).map((r) => [JSON.stringify(r), r]),
          ).values(),
        ].slice(0, 2),
      },
    ];
  });
}
/** Whole-session display scores: absent demonstrations earn zero, never invented evidence. */
export function completeInterviewAssessments(values: FeedbackAssessment[]): FeedbackAssessment[] {
  if (!validObservedScores(values)) throw new Error('Invalid dimension scores');
  return FEEDBACK_DIMENSIONS.map(
    (d) =>
      values.find((a) => a.dimension === d.key) ?? {
        dimension: d.key,
        score: 0,
        text: `本场回答未体现${d.short}，按本场展示计0分。`,
        evidence_refs: [],
      },
  );
}
export function reportFeedback(report: InterviewReport) {
  const existing = report.summary?.feedback_template;
  if (!validObservedScores(report.feedback_assessments)) return existing;
  return {
    version: existing?.version ?? ('interview-feedback-v2' as const),
    assessments: report.feedback_assessments,
    action_plan: existing?.action_plan ?? [],
    next_expectation: existing?.next_expectation ?? '',
  };
}

export function aggregateFeedbackObservations(
  evaluations: InterviewEvaluation[],
  assessments: FeedbackAssessment[],
): FeedbackObservation[] {
  return FEEDBACK_DIMENSIONS.map((d) => {
    const score = assessments.find((a) => a.dimension === d.key);
    if (score)
      return {
        dimension: d.key,
        status: 'observed',
        text: score.text,
        evidence_refs: score.evidence_refs,
      };
    const related = evaluations.flatMap(
      (e) => e.feedback_observations?.filter((o) => o.dimension === d.key) ?? [],
    );
    const insufficient = related.some((o) => o.status === 'insufficient_evidence');
    return {
      dimension: d.key,
      status: insufficient ? 'insufficient_evidence' : 'not_observed',
      text: insufficient
        ? '本场回答未提供足够的可评分依据。'
        : '本场没有形成此维度的实际考察证据。',
      evidence_refs: [],
    };
  });
}

