interface Props {
  jobTitle: string;
  typeLabel: string;
  interviewerLabel: string;
  interviewerStatus: string;
  seconds: number;
  durationMinutes: number;
  turns: WorkspaceTurn[];
  current?: WorkspaceTurn;
  draft: string;
