'use client';
import { useCallback, useEffect, useRef, useState } from 'react';
import { INTERVIEW_MAX_ANSWER, type Interview } from '@interviewlab/core';
import { useRouter } from 'next/navigation';
import { interviewsApi } from '../../lib/api/interviews';
import { useSession } from '../../components/session-provider';
import { Brand, Header, Loading, Modal } from '../../components/shared';
import { CommandNotice, ErrorNotice, SessionGate, useLiveCommand, useLiveResource } from './common';

import { useInterviewStream } from './stream';
import { InterviewWorkspace } from '../../components/interview-workspace';
import { Button } from '../../components/ui/button';
import { useInterviewFlow } from './flow-provider';
import { PreparationScreen } from './preparation';
import { TransitionScreen } from './transition-screen';
import { VoiceControls } from './voice/controls';
import { VideoInterviewWorkspace } from '../video-interview/room';
import { useQuestionPresentation } from './use-question-presentation';
import { interviewPresentation } from './interview-presentation';
import { InterviewProgressNotice, InterviewGenerationNotice } from './interview-notices';

function InterviewBody({ id, videoRoom = false }: { id: string; videoRoom?: boolean }) {
  const flow = useInterviewFlow();
  const router = useRouter();
  const Workspace = videoRoom ? VideoInterviewWorkspace : InterviewWorkspace;
  const { state: account } = useSession();
  const load = useCallback((signal: AbortSignal) => interviewsApi.read(id, signal), [id]);
  const [streamConnected, setStreamConnected] = useState(false);
  const resource = useLiveResource(
    load,
    (v) =>
      (v.generation_status === 'pending' && !streamConnected) ||
      ['pending', 'waiting_material'].includes(v.preparation?.status ?? ''),
  );
  const stream = useInterviewStream(id, resource.value, resource.accept, resource.refresh);
  useEffect(() => setStreamConnected(stream.connected), [stream.connected]);
  const command = useLiveCommand(() => void resource.refresh());
  const [draft, setDraft] = useState({ key: '', text: '' });
  const [storageError, setStorageError] = useState('');
  const [finish, setFinish] = useState(false);
  const restoreVoice = useRef<(() => void) | null>(null);
  const [now, setNow] = useState(Date.now());
  const deadlineChecked = useRef(false);
  const v = resource.value;
  const presentation = useQuestionPresentation(v);
  const turn = v?.turns.at(-1);
  const terminal = v?.status === 'completed' || v?.status === 'failed';
  const userId = account.status === 'signed_in' ? account.session.user.id : '';
  const draftKey = userId && turn ? `interviewlab:live:${userId}:${id}:${turn.id}` : '';
  useEffect(() => {
    if (!draftKey) return;
    try {
      setDraft({ key: draftKey, text: sessionStorage.getItem(draftKey) ?? '' });
    } catch {
      setDraft({ key: draftKey, text: '' });
      setStorageError('浏览器无法保存草稿，请保持页面打开。');
    }
  }, [draftKey]);
  useEffect(() => {
    if (!v?.started_at || terminal) return;
    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(timer);
  }, [v?.started_at, terminal]);
  useEffect(() => {
    if (
      v?.deadline_at &&
      now >= Date.parse(v.deadline_at) &&
      !terminal &&
      !deadlineChecked.current
    ) {
      deadlineChecked.current = true;
      void resource.refresh();
    }
  }, [now, v?.deadline_at, terminal, resource.refresh]);
  function setText(text: string) {
    setDraft({ key: draftKey, text });
    try {
      sessionStorage.setItem(draftKey, text);
    } catch {
      setStorageError('草稿仅保留在当前页面，刷新可能丢失。');
    }
  }
  const text = draft.key === draftKey ? draft.text : '';
  function accepted(result: Interview, submitted?: { turnId: string; text: string; key: string }) {
    if (
      submitted &&
      result.turns.some(
        (t) =>
          t.id === submitted.turnId &&
          t.answer_status === 'answered' &&
          t.answer_text === submitted.text,
      )
    ) {
      try {
        sessionStorage.removeItem(submitted.key);
      } catch {}
      setDraft({ key: submitted.key, text: '' });
    }
    resource.accept(result);
    setNow(Date.now());
    restoreVoice.current = null;
    setFinish(false);
  }
  function act(
    action: string,
    body: object,
    submitted?: { turnId: string; text: string; key: string },
  ) {
    const input = { version: v!.version, ...body };
    command.run(
      (key) => interviewsApi.command(id, action, input, key),
      (result) => accepted(result, submitted),
    );
  }
  const voice = flow.voice;
  function changeFinish(open: boolean) {
    if (open) restoreVoice.current = voice.suspend();
    else {
      restoreVoice.current?.();
      restoreVoice.current = null;
    }
    setFinish(open);
  }
  useEffect(
    () => flow.bind({ id, draft: text, onDraft: setText, onView: resource.accept }),
    [id, text, draftKey],
  );
  useEffect(() => {
    if (!v) return;
    if (flow.view !== v) flow.accept(v);
    if (terminal) {
      flow.release();
      router.replace(`/interview/${id}/analysis`);
    } else if (
      v.status === 'ready' ||
      (v.status === 'in_progress' &&
        v.configuration.interaction_mode !== 'text_fallback' &&
        flow.phase === 'idle')
    )
      router.replace(`/interview/${id}/prepare`);
  }, [v?.id, v?.version, v?.status]);
  if (!v)
    return (
      <>
        <header className="session-header">
          <Brand />
        </header>
        <main className="session-main" id="main-content">
          <ErrorNotice message={resource.error} retry={() => void resource.refresh()} />
          {!resource.error && <Loading />}
        </main>
      </>
    );
  if (v.status === 'ready') return <PreparationScreen view={v} />;
  if (terminal)
    return (
      <TransitionScreen
        kind="analysis"
        title="恭喜你完成面试"
        description="回答已保存，正在为你准备复盘。"
        steps={[
          { label: '保存回答', state: 'done' },
          { label: '读取分析进度', state: 'active' },
        ]}
      />
    );
  const waiting = turn?.answer_status === 'waiting';
  const continuation =
    turn?.answer_status === 'answered' &&
    v.generation_status === 'idle' &&
    v.status === 'in_progress';
  const canAnswer =
    (waiting || continuation) &&
    v.status === 'in_progress' &&
    v.generation_status !== 'pending' &&
    !command.blocked;
  const targetReached = v.target_at && now >= Date.parse(v.target_at);
  const workspace = interviewPresentation(v, now, stream.preview);
  const submit = () => {
    if (voice.active) {
      voice.commit();
      return;
    }
    if (continuation)
      act(
        'voice/continue',
        { turn_id: turn!.id, text },
        {
          turnId: turn!.id,
          text: [turn!.answer_text, text].filter(Boolean).join('/n'),
          key: draftKey,
        },
      );
    else act(`turns/${turn!.id}/answer`, { text }, { turnId: turn!.id, text, key: draftKey });
  };

  return (
    <>
      <Workspace
        voice={voice}
        initialCamera={flow.camera}
        onCameraChange={flow.setCamera}
        jobTitle={v.job_title}
        typeLabel={workspace.typeLabel}
        interviewerLabel="AI 面试官"
        interviewerStatus={workspace.interviewerStatus}
        seconds={workspace.seconds}
        durationMinutes={v.configuration.duration_minutes}
        turns={workspace.turns}
        current={workspace.current}
        draft={text}
        maxAnswer={INTERVIEW_MAX_ANSWER}
        canAnswer={Boolean(canAnswer)}
        blocked={
          command.blocked ||
          voice.connecting ||
          Boolean(v.preparation && !['ready', 'fallback'].includes(v.preparation.status))
        }
        paused={v.status === 'paused'}
        ended={Boolean(terminal)}
        saveLabel={workspace.saveLabel}
        draftHint={
          storageError ||
          (terminal && text
            ? '此草稿尚未提交，你仍可复制保存。'
            : '草稿保留在当前标签页，提交确认后清除。')
        }
        explanation={v.clarification}
        voiceActive={voice.active}
        voiceView={voice.display}
        workspace={
          <VoiceControls
            voice={voice}
            preferred={v.configuration.interaction_mode === 'realtime_voice'}
            disabled={v.status !== 'in_progress' || command.blocked || finish}
          />
        }
        notice={
          <>
            <ErrorNotice message={resource.error} retry={() => void resource.refresh()} />
            <ErrorNotice message={presentation.error} retry={presentation.retry} />
            <CommandNotice command={command} refresh={() => void resource.refresh()} />
            <InterviewProgressNotice
              view={v}
              continuation={Boolean(continuation)}
              targetReached={Boolean(targetReached)}
              canContinue={!command.blocked && !voice.active}
              onContinue={() => act('voice/continue', { turn_id: turn!.id, text: '' })}
            />
          </>
        }
        conversationNotice={
          <InterviewGenerationNotice
            view={v}
            preview={stream.preview}
            blocked={command.blocked}
            onRetry={(fallback) => act('generation/retry', { fallback })}
          />
        }
        interviewerNote={
          <>
            结合自己的实际经历回答，不熟悉的内容可以直接说明。
            <br />
            面试中不展示评价和参考答案。
          </>
        }
        recordsHref="/me/interviews"
        reportHref={`/reports/${id}`}
        onText={setText}
        onSubmit={submit}
        onSkip={() => {
          voice.stop();
          if (text.trim()) setStorageError('请先提交或清空当前草稿，再跳过本题。');
          else act(`turns/${turn!.id}/actions`, { action: 'skip' });
        }}
        onRepeat={() => act(`turns/${turn!.id}/actions`, { action: 'repeat_question' })}
        onClarify={() => act(`turns/${turn!.id}/actions`, { action: 'clarify_question' })}
        onPause={() => {
          voice.stop();
          act(v.status === 'paused' ? 'resume' : 'pause', {});
        }}
        onFinish={() => changeFinish(true)}
      />
      {finish && (
        <Modal
          open
          onOpenChange={(open) => {
            if (!command.blocked) changeFinish(open);
          }}
          title="确定提前结束面试？"
          description={
            text.trim()
              ? '当前回答会一并提交，随后为你呈现本场分析报告。'
              : '结束后将为你呈现本场分析报告。'
          }
        >
          <div className="dialog-actions">
            <Button
              variant="outline"
              disabled={command.blocked}
              onClick={() => changeFinish(false)}
            >
              继续面试
            </Button>
            <Button
              disabled={command.blocked}
              onClick={() => {
                const finalText = text.trim();
                act(
                  'finish',
                  {
                    reason: 'user_finished',
                    ...(finalText && turn
                      ? { final_answer: { turn_id: turn.id, text: finalText } }
                      : {}),
                  },
                  finalText && turn
                    ? {
                        turnId: turn.id,
                        text: continuation
                          ? [turn.answer_text, finalText].filter(Boolean).join('/n')
                          : finalText,
                        key: draftKey,
                      }
                    : undefined,
                );
              }}
            >
              结束面试并查看报告
            </Button>
          </div>
          <CommandNotice command={command} refresh={() => void resource.refresh()} />
        </Modal>
      )}
    </>
  );
}
export default function LiveInterview({
  id,
  videoRoom = false,
}: {
  id: string;
  videoRoom?: boolean;
}) {
  const { state } = useSession();
  if (state.status !== 'signed_in')
    return (
      <>
        <Header />
        <main className="container page-body" id="main-content">
          <SessionGate>{null}</SessionGate>
        </main>
      </>
    );
  return <InterviewBody key={`${state.session.user.id}:${id}`} id={id} videoRoom={videoRoom} />;
}

'use client';

import { useCallback, useEffect, useRef } from 'react';
import { useRouter } from 'next/navigation';
import { LIVE_TYPE_LABELS, type Interview } from '@interviewlab/core';
import { interviewsApi } from '../../lib/api/interviews';
import { Button } from '../../components/ui/button';
import { useInterviewFlow } from './flow-provider';
import { SessionGate, useLiveCommand, useLiveResource } from './common';
import { TransitionScreen, type TransitionStep } from './transition-screen';

export function PreparationScreen({
  view,
  error = '',
  refresh,
}: {
  view?: Interview | null;
  error?: string;
  refresh?: () => void;
}) {
  const flow = useInterviewFlow();
  const router = useRouter();
  const command = useLiveCommand(refresh);
  const config = view?.configuration ?? flow.configuration;
  const preparation = view?.preparation;
  const ready = !preparation || ['ready', 'fallback'].includes(preparation.status);
  const failed = preparation?.status === 'failed';
  const message =
    error ||
    flow.error ||
    (view && flow.isAbandoned(view.id) ? '本次准备已取消，你可以重试或返回配置。' : '') ||
    (failed ? '本场面试规划暂未完成，你的配置和简历仍已保存。' : '');
  const steps: TransitionStep[] = [
    {
      label: '检查设备',
      state: flow.deviceReady ? 'done' : message && !failed ? 'error' : 'active',
    },
    {
      label: config?.resume_ref ? '准备岗位与简历' : '准备岗位信息',
      state: preparation?.status === 'waiting_material' ? 'active' : view ? 'done' : 'pending',
    },
    {
      label: '规划本场面试',
      state: failed
        ? 'error'
        : view && ready
          ? 'done'
          : view && preparation?.status !== 'waiting_material'
            ? 'active'
            : 'pending',
    },
    {
      label: '进入面试房间',
      state: flow.phase === 'running' ? 'done' : flow.phase === 'connecting' ? 'active' : 'pending',
    },
  ];
  const returnToConfig = () => {
    flow.abandon();
    router.replace('/interview/setup');
  };
  const retry = () => {
    if (failed && view)
      command.run(
        (key) =>
          interviewsApi.command(
            view.id,
            'prepare',
            { version: view.version, mode: 'personalized' },
            key,
          ),
        (next) => {
          flow.accept(next);
          flow.retry();
          refresh?.();
        },
      );
    else if (view) {
      flow.retry(view);
      refresh?.();
    } else if (config) void flow.begin(config);
    else refresh?.();
  };
  return (
    <TransitionScreen
      kind="preparing"
      title="正在准备面试"
      description={
        flow.phase === 'connecting'
          ? '正在连接面试官'
          : flow.phase === 'devices'
            ? '请允许浏览器使用所选设备'
            : preparation?.status === 'waiting_material'
              ? '正在阅读你的简历'
              : view && !ready
                ? '正在规划本场提问'
                : view
                  ? '即将进入面试'
                  : '正在准备岗位信息'
      }
      context={
        config
          ? `${view?.job_title ?? config.job} · ${LIVE_TYPE_LABELS[config.interview_type]} · ${config.duration_minutes} 分钟`
          : undefined
      }
      steps={steps}
      error={message || command.error}
    >
      <div className="transition-actions">
        {message && (
          <Button disabled={command.blocked} onClick={retry}>
            {failed ? '重试准备' : '重试设备'}
          </Button>
        )}
        {message && !flow.textMode && config?.interaction_mode !== 'text_fallback' && (
          <Button
            variant="outline"
            onClick={() => {
              flow.useText();
              if (!view && config) void flow.begin(config);
              else refresh?.();
            }}
          >
            改用文字
          </Button>
        )}
        {failed && view && (
          <Button
            variant="outline"
            disabled={command.blocked}
            onClick={() =>
              command.run(
                (key) =>
                  interviewsApi.command(
                    view.id,
                    'prepare',
                    { version: view.version, mode: 'fallback' },
                    key,
                  ),
                (next) => {
                  flow.accept(next);
                  flow.retry();
                  refresh?.();
                },
              )
            }
          >
            使用简化准备
          </Button>
        )}
        <Button variant="ghost" onClick={returnToConfig}>
          返回配置
        </Button>
      </div>
    </TransitionScreen>
  );
}

function PreparationBody({ id }: { id: string }) {
  const flow = useInterviewFlow();
  const router = useRouter();
  const load = useCallback((signal: AbortSignal) => interviewsApi.read(id, signal), [id]);
  const resource = useLiveResource(
    load,
    (v) => ['pending', 'waiting_material'].includes(v.preparation?.status ?? ''),
    { retryReadErrors: true },
  );
  const view = resource.value;
  const requested = useRef(new Set<number>());
  const command = useLiveCommand(() => void resource.refresh());
  useEffect(() => {
    if (!view) return;
    flow.accept(view);
    if (['completed', 'failed'].includes(view.status)) {
      flow.release();
      router.replace(`/interview/${id}/analysis`);
      return;
    }
    if (view.status === 'paused') {
      flow.release();
      router.replace(flow.roomPath(view));
      return;
    }
    if (
      view.status === 'ready' &&
      view.preparation?.status === 'pending' &&
      !view.preparation.task_id &&
      !requested.current.has(view.version)
    ) {
      requested.current.add(view.version);
      command.run(
        (key) =>
          interviewsApi.command(
            id,
            'prepare',
            { version: view.version, mode: 'personalized' },
            key,
          ),
        resource.accept,
      );
    }
  }, [view?.id, view?.version, view?.status]);
  useEffect(() => {
    if (!view || flow.phase === 'error' || resource.error) return;
    if (
      view.status !== 'in_progress' &&
      !(
        view.status === 'ready' &&
        (!view.preparation || ['ready', 'fallback'].includes(view.preparation.status))
      )
    )
      return;
    let alive = true;
    void flow
      .enter(view)
      .then((next) => {
        if (alive) router.replace(flow.roomPath(next));
      })
      .catch(() => {});
    return () => {
      alive = false;
    };
  }, [
    view?.id,
    view?.version,
    view?.status,
    view?.preparation?.status,
    flow.phase,
    resource.error,
  ]);
  return (
    <PreparationScreen
      view={view}
      error={resource.error || command.error}
      refresh={() => void resource.refresh()}
    />
  );
}
export default function InterviewPreparation({ id }: { id: string }) {
  return (
    <SessionGate>
      <PreparationBody id={id} />
    </SessionGate>
  );
}

import type { Interview } from '@interviewlab/core';
import { ApiClientError } from '../../lib/api/http';
import { interviewsApi } from '../../lib/api/interviews';

function canRecoverPresentation(error: unknown): boolean {
  return (
    error instanceof ApiClientError &&
    (error.status === 0 ||
      error.status === 409 ||
      error.status >= 500 ||
      error.detail.code === 'invalid_response')
  );
}

function waitingForPresentation(view: Interview, turnId: string): boolean {
  const turn = view.turns.at(-1);
  return view.status === 'in_progress' && turn?.id === turnId && turn.answer_status === 'waiting';
}

/** An uncertain receipt is recovered before one bounded retry with the current version. */
export async function confirmQuestionPresentation(
  view: Interview,
  turnId: string,
  isCurrent: () => boolean,
  api: Pick<typeof interviewsApi, 'read' | 'command'> = interviewsApi,
): Promise<boolean> {
  const action = `turns/${turnId}/presented`;
  let key = crypto.randomUUID();
  try {
    await api.command(view.id, action, { version: view.version }, key);
    return true;
  } catch (error) {
    if (!canRecoverPresentation(error)) throw error;
  }
  if (!isCurrent()) return false;
  const fresh = await api.read(view.id);
  if (!isCurrent()) return false;
  const turn = fresh.turns.at(-1);
  if (turn?.id === turnId && turn.presented_at) return true;
  if (!waitingForPresentation(fresh, turnId)) return false;
  if (fresh.version !== view.version) key = crypto.randomUUID();
  await api.command(view.id, action, { version: fresh.version }, key);
  return true;
}

