import { z } from 'zod';

const optionalUrl = z.preprocess(
  (value) => (value === '' ? undefined : value),
  z.string().url().optional(),
);
const environmentSchema = z.object({
  NODE_ENV: z.enum(['development', 'test', 'production']).default('development'),
  API_HOST: z.string().min(1).default('127.0.0.1'),
  API_PORT: z.coerce.number().int().min(1).max(65535).default(3001),
  PUBLIC_ORIGIN: z.string().url().default('http://127.0.0.1:3000'),
  AUTH_ENABLED: z
    .enum(['true', 'false'])
    .default('false')
    .transform((value) => value === 'true'),
  BETTER_AUTH_SECRET: z.preprocess(
    (value) => (value === '' ? undefined : value),
    z.string().min(32).optional(),
  ),
  LOG_LEVEL: z.enum(['fatal', 'error', 'warn', 'info', 'debug', 'trace', 'silent']).default('info'),
  DATABASE_URL: optionalUrl,
  KNOWLEDGE_DATABASE_URL: optionalUrl,
  KNOWLEDGE_PREVIEW: z
    .enum(['true', 'false'])
    .default('false')
    .transform((v) => v === 'true'),
  EMBEDDING_MODEL: z.literal('ecnu-embedding-small').default('ecnu-embedding-small'),
  DATABASE_POOL_SIZE: z.coerce.number().int().min(1).max(50).default(10),
  DATABASE_CONNECT_TIMEOUT_MS: z.coerce.number().int().min(100).max(30000).default(3000),
  BODY_LIMIT_BYTES: z.coerce.number().int().min(1024).max(10485760).default(1048576),
  WORKER_CONCURRENCY: z.coerce.number().int().min(1).max(32).default(3),
  WORKER_PREPARATION_CONCURRENCY: z.coerce.number().int().min(1).max(8).default(1),
  WORKER_REPORT_CONCURRENCY: z.coerce.number().int().min(1).max(32).default(3),
  WORKER_POLL_MS: z.coerce.number().int().min(100).max(60000).default(1000),
  WORKER_HEARTBEAT_MS: z.coerce.number().int().min(100).max(30000).default(5000),
  WORKER_STALE_MS: z.coerce.number().int().min(1000).max(300000).default(30000),
  LLM_BASE_URL: optionalUrl.default('https://chat.ecnu.edu.cn/open/api/v1'),
  LLM_API_KEY: z
    .string()
    .optional()
    .transform((value) => value?.trim()),
  LLM_MODEL: z.string().min(1).max(200).default('ecnu-plus'),
  LLM_OUTPUT_MODE: z.enum(['json_object', 'json_schema']).default('json_object'),
  LLM_TIMEOUT_MS: z.coerce.number().int().min(100).max(45000).default(25000),
  VOICE_ENABLED: z
    .enum(['true', 'false'])
    .default('false')
    .transform((v) => v === 'true'),
  VOLC_ASR_API_KEY: z
    .string()
    .optional()
    .transform((v) => v?.trim()),
  VOLC_TTS_API_KEY: z
    .string()
    .optional()
    .transform((v) => v?.trim()),
  VOLC_ASR_RESOURCE_ID: z.string().min(1).default('volc.seedasr.sauc.duration'),
  VOLC_TTS_RESOURCE_ID: z.string().min(1).default('seed-tts-2.0'),
  VOLC_TTS_SPEAKER: z.string().min(1).default('zh_male_m191_uranus_bigtts'),
  VOICE_SILENCE_MS: z.coerce.number().int().min(1200).max(6000).default(1800),
});
export type BackendConfig = z.infer<typeof environmentSchema>;
export class ConfigurationError extends Error {}

export function loadConfig(env: Record<string, unknown> = process.env): BackendConfig {
  const parsed = environmentSchema.safeParse(env);
  // Never include environment values or Zod input objects in configuration errors.
  if (!parsed.success)
    throw new ConfigurationError(
      'Invalid configuration: ' +
        parsed.error.issues.map((issue) => issue.path.join('.') + ' ' + issue.message).join('; '),
    );
  const config = parsed.data;
  if (config.KNOWLEDGE_PREVIEW && config.NODE_ENV === 'production')
    throw new ConfigurationError('Knowledge preview is unavailable in production');
  if (config.KNOWLEDGE_DATABASE_URL && !/^postgres(ql)?://///.test(config.KNOWLEDGE_DATABASE_URL))
    throw new ConfigurationError('Knowledge database requires PostgreSQL');
  if (config.LLM_BASE_URL) {
    const endpoint = new URL(config.LLM_BASE_URL);
    if (
      !['https:', 'http:'].includes(endpoint.protocol) ||
      endpoint.username ||
      endpoint.password ||
      endpoint.search ||
      endpoint.hash
    )
      throw new ConfigurationError(
        'Invalid configuration: LLM_BASE_URL must be an HTTP API base URL without credentials, query or fragment',
      );
  }
  const origin = new URL(config.PUBLIC_ORIGIN);
  if (!['http:', 'https:'].includes(origin.protocol) || origin.origin !== config.PUBLIC_ORIGIN) {
    throw new ConfigurationError(
      'Invalid configuration: PUBLIC_ORIGIN must be an HTTP origin without a path',
    );
  }
  if (config.AUTH_ENABLED && (!config.DATABASE_URL || !config.BETTER_AUTH_SECRET)) {
    throw new ConfigurationError(
      'Invalid configuration: authentication requires DATABASE_URL and BETTER_AUTH_SECRET',
    );
  }
  if (config.AUTH_ENABLED && config.NODE_ENV === 'production' && origin.protocol !== 'https:') {
    throw new ConfigurationError('Invalid configuration: production authentication requires HTTPS');
  }
  if (config.DATABASE_URL && !/^postgres(ql)?://///.test(config.DATABASE_URL)) {
    throw new ConfigurationError('Invalid configuration: DATABASE_URL must use PostgreSQL');
  }
  if (config.WORKER_STALE_MS <= config.WORKER_HEARTBEAT_MS * 2) {
    throw new ConfigurationError(
      'Invalid configuration: WORKER_STALE_MS must exceed two heartbeat intervals',
    );
  }
  return config;
}

import { betterAuth } from 'better-auth/minimal';
import { drizzleAdapter } from '@better-auth/drizzle-adapter';
import type { AuthSession, SignInInput, SignUpInput } from '@interviewlab/core';
import { eq } from 'drizzle-orm';
import type { FastifyRequest } from 'fastify';
import type { IdentityProvider } from '../../foundation/auth';
import type { BackendConfig } from '../../foundation/config';
import type { Database } from '../../database/connection';
import { ServiceError } from '../../foundation/errors';
import { authAccount, authRateLimit, authSession, authUser, authVerification } from './auth-schema';

export function createAuthService(database: Database, config: BackendConfig) {
  if (!config.AUTH_ENABLED || !config.BETTER_AUTH_SECRET)
    throw new Error('Authentication is not configured');
  const auth = betterAuth({
    appName: 'InterviewLab',
    baseURL: config.PUBLIC_ORIGIN,
    basePath: '/api/v1/auth',
    secret: config.BETTER_AUTH_SECRET,
    database: drizzleAdapter(database.db, {
      provider: 'pg',
      transaction: true,
      schema: {
        user: authUser,
        session: authSession,
        account: authAccount,
        verification: authVerification,
        rateLimit: authRateLimit,
      },
    }),
    emailAndPassword: {
      enabled: true,
      disableSignUp: false,
      autoSignIn: true,
      minPasswordLength: 9,
      maxPasswordLength: 20,
    },
    trustedOrigins: [config.PUBLIC_ORIGIN],
    user: {
      additionalFields: {
        role: {
          type: ['student', 'content_maintainer', 'operator'],
          defaultValue: 'student',
          input: false,
        },
      },
    },
    session: {
      expiresIn: 60 * 60 * 24 * 7,
      disableSessionRefresh: true,
      cookieCache: { enabled: false },
    },
    advanced: {
      cookiePrefix: 'interviewlab',
      useSecureCookies: config.PUBLIC_ORIGIN.startsWith('https://'),
      defaultCookieAttributes: { httpOnly: true, sameSite: 'lax', path: '/' },
      ipAddress: { ipAddressHeaders: ['x-interviewlab-client-ip'] },
    },
    rateLimit: {
      enabled: true,
      storage: 'database',
      window: 60,
      max: 100,
      customRules: {
        '/sign-in/email': { window: 60, max: 10 },
        '/sign-up/email': { window: 60, max: 5 },
      },
    },
    // Provider failures may contain private data. Our HTTP layer logs only a safe error type.
    logger: { disabled: true },
    telemetry: { enabled: false },
  });
  const session = async (headers: FastifyRequest['headers']): Promise<AuthSession | null> => {
    const cookieHeaders = new Headers();
    if (headers.cookie) cookieHeaders.set('cookie', headers.cookie);
    try {
      const result = await auth.api.getSession({
        headers: cookieHeaders,
        query: { disableCookieCache: true },
      });
      if (!result) return null;
      return {
        user: { id: result.user.id, name: result.user.name, email: result.user.email },
        roles: [result.user.role],
        expires_at: result.session.expiresAt.toISOString(),
      };
    } catch {
      throw new ServiceError(
        'dependency_unavailable',
        503,
        'Authentication is temporarily unavailable',
        true,
      );
    }
  };
  const invoke = async (
    path: 'sign-in/email' | 'sign-up/email' | 'sign-out',
    request: FastifyRequest,
    body: unknown,
  ) => {
    const headers = new Headers({
      'content-type': 'application/json',
      'x-interviewlab-client-ip': request.ip,
    });
    if (request.headers.cookie) headers.set('cookie', request.headers.cookie);
    if (request.headers.origin) headers.set('origin', request.headers.origin);
    let response: Response;
    try {
      response = await auth.handler(
        new Request(`${config.PUBLIC_ORIGIN}/api/v1/auth/${path}`, {
          method: 'POST',
          headers,
          body: JSON.stringify(body),
        }),
      );
    } catch {
      throw new ServiceError(
        'dependency_unavailable',
        503,
        'Authentication is temporarily unavailable',
        true,
      );
    }
    if (!response.ok) {
      const status = response.status;
      if (path === 'sign-up/email' && status === 422) {
        // Concurrent signups can hit the unique constraint inside Better Auth's transaction.
        const result = (await response.json().catch(() => null)) as { code?: string } | null;
        if (result?.code === 'USER_ALREADY_EXISTS_USE_ANOTHER_EMAIL')
          throw new ServiceError('email_already_exists', 409, '该邮箱已注册，请登录。');
        if (result?.code === 'FAILED_TO_CREATE_USER') {
          try {
            const existing = await database.db
              .select({ id: authUser.id })
              .from(authUser)
              .where(eq(authUser.email, (body as SignUpInput).email))
              .limit(1);
            if (existing.length)
              throw new ServiceError('email_already_exists', 409, '该邮箱已注册，请登录。');
          } catch (error) {
            if (error instanceof ServiceError) throw error;
          }
          throw new ServiceError(
            'dependency_unavailable',
            503,
            '注册暂时不可用，请稍后重试。',
            true,
          );
        }
      }
      if (status === 401)
        throw new ServiceError('unauthorized', 401, 'Email or password is incorrect');
      if (status === 429)
        throw new ServiceError('rate_limited', 429, 'Too many attempts; try again later', true);
      if (status === 403)
        throw new ServiceError('forbidden', 403, 'Authentication request forbidden');
      if (status >= 500)
        throw new ServiceError(
          'dependency_unavailable',
          503,
          'Authentication is temporarily unavailable',
          true,
        );
      throw new ServiceError('unsupported_input', 400, 'Invalid authentication request');
    }
    // Never return Better Auth's token-bearing JSON to the browser.
    return response.headers.getSetCookie();
  };
  return {
    session,
    authenticate: async (headers) => {
      const current = await session(headers);
      return current ? { owner_id: current.user.id, roles: current.roles } : null;
    },
    signIn: (request: FastifyRequest, input: SignInInput) =>
      invoke('sign-in/email', request, input),
    signUp: (request: FastifyRequest, input: SignUpInput) =>
      invoke('sign-up/email', request, input),
    signOut: (request: FastifyRequest) => invoke('sign-out', request, {}),
  } satisfies IdentityProvider & Record<string, unknown>;
}
export type AuthService = ReturnType<typeof createAuthService>;

import { createAllRoleKnowledge } from './knowledge/all-roles';
import { createResumeAnalysis } from './resumes/analysis';
import { createWorkflowModels, type WorkflowModels } from './interviews/workflow-models';
import { createInterviewPreparation } from './interviews/preparation';
import { createInterviewAgent } from './interviews/agent';
import { createMaterialsService } from './resumes/service';
import type { InterviewKnowledgeProvider, InterviewKnowledgeRuntime } from '@interviewlab/core';
import type { Database } from '../database/connection';
import type { BackendConfig } from '../foundation/config';
import { ServiceError } from '../foundation/errors';
import type { InterviewAgent } from './interviews/model-analysis';
import { createInterviewsService, type InterviewReportHooks } from './interviews/service';
import { createReportsService } from './reports/service';
import { interviewsModule } from './interviews/routes';
import { reportsModule } from './reports/routes';
import type { TaskRow } from '../tasks/service';
import type { VoiceProvider } from './interviews/voice/volcengine';

export interface InterviewRuntimeOptions {
  workflowModels?: WorkflowModels;
  voiceProvider?: VoiceProvider;
  agent?: InterviewAgent;
  knowledge?: InterviewKnowledgeProvider;
  realtimeKnowledge?: InterviewKnowledgeRuntime;
  log?: (entry: object) => void;
  onFinalize?: InterviewReportHooks['seal'];
}
export function createInterviewRuntime(
  database: Database,
  config: BackendConfig,
  options: InterviewRuntimeOptions = {},
) {
  const knowledge = createAllRoleKnowledge(config);
  const content = options.knowledge ?? options.realtimeKnowledge ?? knowledge;
  const models = options.workflowModels ?? createWorkflowModels(config, fetch, options.log);
  const resumeAnalysis = createResumeAnalysis(database, config, models);
  const materials = createMaterialsService(database, resumeAnalysis, true);
  const agent =
    options.agent ??
    createInterviewAgent(config, options.log);
  const interviews = createInterviewsService(
    database,
    content,
    agent,
    {
      prepare: options.onFinalize ? undefined : (tx, state) => reports.prepare(tx, state),
      seal: options.onFinalize ?? ((tx, state) => reports.seal(tx, state)),
      erase: (tx, owner, id) => reports.erase(tx, owner, id),
    },
    options.realtimeKnowledge ?? {
      ...knowledge,
      read: (c) => knowledge.read(c),
      profiles: (c) => knowledge.profiles(c),
      prefetch: (c,k,m) => knowledge.prefetch(c,k,m),
      context: (c,k,m,a,s) => knowledge.context(c,k,m,a,s),
    },
    async (owner,id,version)=>{const versions=await materials.versions(owner,id);const material=versions.find(v=>v.version===version&&v.kind==='resume'&&v.confirmed);if(!material)throw new ServiceError('unsupported_input',400,'请选择本人已确认的简历版本');return material;},
    {
      initialize: (identity,id) => preparation.initialize(identity,id),
      request: (identity,id,body,key) => preparation.request(identity,id,body,key),
    },
  );
  const preparation=createInterviewPreparation(database,config,content,materials,resumeAnalysis,models);
  const reports = createReportsService(database, interviews, agent);
  return {
    agent,
    materials,
    close: async () => {
      await interviews.streams.close();
      await knowledge.close();
    },
    interviews,
    reports,
    modules: [
      interviewsModule(interviews, { config, provider: options.voiceProvider }),
      reportsModule(reports),
    ],
    handlers: { ...interviews.handlers, ...reports.handlers, ...resumeAnalysis.handlers, ...preparation.handlers },
    async maintain() {
      await preparation.maintain();
      await interviews.maintain();
      await reports.maintain();
    },
    async isCancelled(task: Readonly<TaskRow>) {
      const input = task.payload as {
        interview_id?: string;
        generation_id?: string;
        report_id?: string;
        report_version?: number;
        comparison_id?: string;
        version?: number;
      };
      try {
        if (task.type === 'preparation.plan.v1' && input.interview_id) {
          const state=await interviews.read({owner_id:task.owner_id,roles:[]},input.interview_id);
          return state.status !== 'ready' || state.preparation?.task_id !== task.id;
        }
        if (input.interview_id) {
          if (task.type === 'reports.evaluate.v1') return await reports.isEvaluationCancelled(task);
          const current = await interviews.read(
            { owner_id: task.owner_id, roles: [] },
            input.interview_id,
          );
          if (input.report_id) {
            const report = await reports.get(
              { owner_id: task.owner_id, roles: [] },
              input.interview_id,
            );
            return report.id !== input.report_id || report.version !== input.report_version;
          }
          return Boolean(
            input.generation_id &&
              (current.generation_id !== input.generation_id || current.status !== 'in_progress'),
          );
        }
        if (input.comparison_id) {
          const current = await reports.getComparison(
            { owner_id: task.owner_id, roles: [] },
            input.comparison_id,
          );
          return current.version !== input.version;
        }
        return false;
      } catch (error) {
        if (error instanceof ServiceError && error.statusCode === 404) return true;
        throw error;
      }
    },
  };
}

import type {
  Interview,
  InterviewTurn,
  InterviewTopic,
  InterviewConversationState,
  InterviewReplyAct,
  InterviewTopicBoundary,
} from '@interviewlab/core';
import { ServiceError } from '../../foundation/errors';
const refusal =
  /不方便|不想(?:回答|说|聊|谈|透露|介绍)|不愿(?:回答|说|聊|谈|透露)|不便(?:回答|说|聊|谈|透露)|不(?:聊|谈).{0,8}(?:这个|背景|学校|项目)|(?:这个问题|这个话题|这题).{0,6}(?:跳过|不答|保密)|换(?:个|一个)话题|涉及保密|别(?:再)?(?:问|聊|谈)(?:这个|这题)|这个不说了|跳过这个问题/;
export function replyAct(text: string): InterviewReplyAct {
  const value = text.replace(/[/s，,。.!！?？～~、]/g, '').toLowerCase();
  if (!/没有不方便|不是不方便/.test(text) && refusal.test(text)) return 'decline_topic';
  if (/^(?:你好|您好|老师好|面试官好|面试官你好|hi|hello|哈喽)+$/.test(value)) return 'greeting';
  if (
    /^(?:嗯|恩|好的|好|可以|ok|开始吧|准备好了|有|是的|对|会一点|一点点|继续|继续吧)+$/.test(value)
  )
    return 'acknowledgement';
  if (
    /^(?:我)?(?:不太|完全)?(?:不知道|不清楚|不会|不懂|没学过|没接触过|没了解过|想不起来)/.test(
      value,
    ) &&
    !/(?:但|不过|只是|然而)/.test(value)
  )
    return 'dont_know';
  return 'answer';
}
export function questionTopic(
  turn: Pick<InterviewTurn, 'text' | 'stage' | 'topic'>,
): InterviewTopic {
  const sentences = turn.text
    .split(/[。！!；;]/)
    .map((s) => s.trim())
    .filter(Boolean);
  const text = (sentences.at(-1) ?? turn.text).replace(
    /^.{0,35}(?:跳过|不展开|先放下|不再聊)[，,：:]/s*/,
    '',
  );
  if (/薪资|薪酬|待遇|期望收入/.test(text)) return 'expectations';
  if (/到岗|入职|出勤|实习.{0,6}(?:时长|多久|几个月)|工作地点|城市意向/.test(text))
    return 'availability';
  if (
    /学校|学历|毕业院校|教育背景|学习背景|自我介绍|介绍.{0,5}自己/.test(text) ||
    turn.stage === 'introduction'
  )
    return 'personal_background';
  if (
    /(?:应聘|岗位|方向).{0,10}(?:原因|动机)|为什么.{0,10}(?:应聘|选择|前端)|岗位动机/.test(
      text + ' ' + turn.topic,
    )
  )
    return 'motivation';
