  const anchor = facts[0]?.fact.evidence.quote;
  if (!anchor || switches.test(anchor)) return;
  policy.missing = policy.missing.filter(
    (slot) => !(slot === 'project_description' ? hasDescription(anchor) : hasRole(anchor)),
  );
