    };
    const state = await loadInterview(database.pool, task.owner_id, input.interview_id);
    if (
      !state.snapshot ||
      state.view.status !== 'in_progress' ||
      state.view.generation_id !== input.generation_id ||
      interviewInputDigest(state) !== input.input_digest
