    const retrieval =
      (state.snapshot.prompt_version === INTERVIEW_V3 ||
        state.snapshot.runtime_version === 'graph-v1') &&
      realtimeKnowledge
        ? !knowledgeReady(experiencePolicy(state.view)) &&
