      .catch(() => {
        if (!this.closed && !controller.signal.aborted) {
          this.stopSpeech();
          this.send({
            type: 'error',
            code: 'voice_tts_failed',
            message: '语音播报失败，题目已保留在页面，可继续回答或切回文字。',
            retryable: true,
