/** Applicability is decided from the question and frozen reference, never from a fluent answer. */
export function applicableReportIndicators(
  turn: InterviewTurn,
  snapshot: InterviewSnapshot,
): ReportRubricIndicator[] {
  const question = turn.text;
  const reference = snapshot.knowledge.questions.some(
    (q) =>
      (q.id === turn.knowledge_question_id || q.topic === turn.topic) &&
      q.report_reference?.cards.length,
  );
  return REPORT_INDICATORS.filter((i) => {
    if (i.id === 'relevance' || i.id === 'structure') return true;
    if (turn.stage === 'introduction') return false;
    if (i.id === 'personal_ownership')
      return (
        /负责|职责|贡献|你(?:具体)?做了|本人|你如何|你怎么/.test(question) &&
        turn.stage === 'experience'
      );
    if (i.id === 'verification')
      return (
        turn.stage === 'experience' && /验证|测试|结果|效果|指标|对比|复盘|证明|衡量/.test(question)
      );
    if (i.id === 'technical_accuracy') return reference && turn.stage === 'technical';
    return (
      reference &&
      ['technical', 'business'].includes(turn.stage ?? '') &&
      /为什么|为何|原因|取舍|选择|比较|对比|权衡|适合|方案|设计/.test(question)
    );
  });
}

/** Equal indicators within dimensions; repeated follow-ups do not increase an indicator's weight. */
export function aggregateIndicatorScores(evaluations: InterviewEvaluation[]) {
  return REPORT_INDICATORS.flatMap((indicator) => {
    const ratings = evaluations
      .filter((e) => e.scoring_rubric_version === FRONTEND_RUBRIC_VERSION)
      .flatMap((e) =>
        (e.indicator_assessments ?? []).filter(
          (a) =>
            a.indicator_id === indicator.id &&
            a.status === 'scored' &&
            a.level !== null &&
            Number.isInteger(a.level) &&
            a.level >= 0 &&
            a.level <= 4 &&
            a.evidence_refs.length,
        ),
      );
    if (!ratings.length) return [];
    return [
      {
        ...indicator,
        score: ratings.reduce((sum, a) => sum + a.level! * 25, 0) / ratings.length,
        evidence_refs: ratings.flatMap((a) => a.evidence_refs),
        observations: ratings.length,
      },
    ];
  });
}

export const RESUME_FIELDS = {"full_name": "姓名", "phone": "联系电话", "email": "邮箱", "city": "所在城市", "education": "教育背景", "skills": "专业技能", "projects": "项目经历（职责、行动、技术取舍、结果）", "internships": "实习与工作经历", "awards": "竞赛与荣誉", "summary": "个人优势与自我介绍"} as const;
export type ResumeTemplate = Record<keyof typeof RESUME_FIELDS,string>;
export const emptyResumeTemplate = (): ResumeTemplate => Object.fromEntries(Object.keys(RESUME_FIELDS).map(k=>[k,''])) as ResumeTemplate;
export function extractResumeTemplate(text: string): ResumeTemplate {
 const result = emptyResumeTemplate();
 const normalized = text.replace(//r/n?/g, '/n').replace(//u00a0/g, ' ');
 result.email = normalized.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+/.[A-Za-z]{2,}/)?.[0] ?? '';
 result.phone = normalized.match(/(?<!/d)(?:/+86[ -]?)?1[3-9](?:[ -]?/d){9}(?!/d)/)?.[0] ?? '';
 const sections: [RegExp, keyof ResumeTemplate][] = [
  [/^(教育背景|教育经历|学历信息|教育|education(?: background)?)$/i, 'education'],
  [/^(专业技能|技术技能|技能清单|技能特长|个人技能|技能|skills|technical skills)$/i, 'skills'],
  [/^(项目经历|项目经验|个人项目|科研经历|项目|projects|project experience)$/i, 'projects'],
  [/^(实习经历|工作经历|工作经验|实习与工作经历|实践经历|实习|experience|work experience|internships?)$/i, 'internships'],
  [/^(竞赛与荣誉|荣誉奖项|获奖经历|获奖情况|竞赛经历|荣誉|奖项|awards|honors)$/i, 'awards'],
  [/^(个人优势|自我评价|个人简介|自我介绍|个人总结|summary|profile)$/i, 'summary'],
 ];
 let current: keyof ResumeTemplate | undefined;
 for (const raw of normalized.split('/n')) {
  const line = raw.trim();
  if (!line) {
   if (current && result[current] && !result[current].endsWith('/n')) result[current] += '/n';
   continue;
  }
  const candidate = line.replace(/^[/s•●■◆#一二三四五六七八九十0-9、.（）()]+/, '').trim();
  const colon = candidate.search(/[:：]/);
  const title = (colon < 0 ? candidate : candidate.slice(0, colon)).replace(//s/g, '');
  const section = sections.find(([pattern]) => pattern.test(title));
  if (section) {
   current = section[1];
   const rest = colon < 0 ? '' : candidate.slice(colon + 1).trim();
   if (rest) result[current] += (result[current] ? '/n' : '') + rest;
   continue;
  }
  const name = line.match(/(?:^|[|｜])/s*(?:姓名|名字)/s*[:：]/s*([^|｜,，;；/s]{2,30})/);
  if (name) result.full_name = name[1];
  const city = line.match(/(?:^|[|｜])/s*(?:城市|所在城市|现居地|所在地|现居)/s*[:：]/s*([^|｜;；]{2,40})/);
  if (city) result.city = city[1].trim();
  if (current) result[current] += (result[current] ? '/n' : '') + line;
 }
 return result;
}

'use client';
import { useEffect, useState } from 'react';
import { usePathname, useRouter } from 'next/navigation';
import { businessTarget, loginDestination, requiresLogin } from '../lib/access';
import { useSession } from './session-provider';
import { AuthForm } from './auth-form';
import { Header, Loading, Modal } from './shared';
import { Button } from './ui/button';

export function AccountAccess({ children }: { children: React.ReactNode }) {
  const { state, refresh } = useSession();
  const path = usePathname();
  const router = useRouter();
  const [target, setTarget] = useState<string | null>(null);
  const protectedPage = requiresLogin(path);
  useEffect(() => {
    if (protectedPage && state.status === 'signed_out') {
      setTarget(
        businessTarget(window.location.pathname + window.location.search + window.location.hash) ??
          '/me',
      );
      router.replace('/');
    }
  }, [protectedPage, path, state.status, router]);
  useEffect(() => {
    if (target && state.status === 'signed_in' && path === '/') {
      setTarget(null);
      router.push(target);
    }
  }, [target, state.status, path, router]);
  const content =
    !protectedPage || state.status === 'signed_in' ? (
      children
    ) : state.status === 'loading' || state.status === 'signed_out' ? (
      <>
        <Header />
        <main id="main-content" className="container section">
          <Loading />
        </main>
      </>
    ) : (
      <>
        <Header />
        <main id="main-content" className="container section">
          <p role="alert">无法确认登录状态，业务内容暂不可用。</p>
          <Button onClick={() => void refresh()}>重新连接</Button>
        </main>
      </>
    );
  return (
    <div
      onClickCapture={(event) => {
        if (
          state.status === 'signed_in' ||
          event.button !== 0 ||
          event.metaKey ||
          event.ctrlKey ||
          event.shiftKey ||
          event.altKey
        )
          return;
        const anchor = (event.target as Element).closest('a[href]');
        if (
          !(anchor instanceof HTMLAnchorElement) ||
          anchor.target === '_blank' ||
          anchor.hasAttribute('download')
        )
          return;
        const url = new URL(anchor.href);
        if (url.origin !== window.location.origin) return;
        const next = businessTarget(url.pathname + url.search + url.hash);
        if (!next && (url.pathname !== '/login' || path !== '/')) return;
        event.preventDefault();
        event.stopPropagation();
        setTarget(
          next ??
            loginDestination(
              url.searchParams.get('next') ??
                window.location.pathname + window.location.search + window.location.hash,
            ),
        );
      }}
    >
      <div key={state.status === 'signed_in' ? state.session.user.id : 'guest'}>{content}</div>
      <Modal
        open={Boolean(target) && path === '/' && state.status !== 'signed_in'}
        onOpenChange={(open) => {
          if (!open) setTarget(null);
        }}
        title="登录或注册"
        description="登录后使用当前账号的真实面试和记录。"
      >
        {state.status === 'loading' ? <Loading /> : <AuthForm />}
      </Modal>
    </div>
  );
}

'use client';
import { useState } from 'react';
import { authClient } from '../lib/api/auth';
import { ApiClientError } from '../lib/api/http';
import { useSession } from './session-provider';
import { Button } from './ui/button';

export function AuthForm({ onSuccess }: { onSuccess?: () => void }) {
  const { state, refresh } = useSession();
  const [mode, setMode] = useState<'login' | 'register'>('login');
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState('');
  async function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    const form = event.currentTarget;
    const values = new FormData(form);
    const password = String(values.get('password'));
    if (mode === 'register' && password !== values.get('confirmation')) {
      setMessage('两次输入的密码不一致。');
      return;
    }
    setBusy(true);
    setMessage('');
    try {
      const email = String(values.get('email')).trim();
      if (mode === 'register')
        await authClient.signUp({ email, password, name: String(values.get('name')).trim() });
      else
        await authClient.signIn({ email, password, rememberMe: values.get('remember') === 'on' });
      form.reset();
      const session = await refresh();
      if (!session) {
        setMessage('操作已完成，但无法确认登录状态。请重试登录或重新连接。');
        return;
      }
      onSuccess?.();
    } catch (error) {
      setMessage(
        error instanceof ApiClientError && error.status === 401
          ? '邮箱或密码不正确。'
          : error instanceof ApiClientError && error.status === 429
            ? '操作过于频繁，请稍后重试。'
            : error instanceof Error
              ? error.message
              : '操作失败，请重试。',
      );
    } finally {
      setBusy(false);
    }
  }
  if (state.status === 'unavailable' || state.status === 'error')
    return (
      <div role="alert">
        <p>账号服务暂时不可用，请检查服务配置或稍后重试。</p>
        <Button onClick={() => void refresh()}>重新连接</Button>
      </div>
    );
  return (
    <>
      <div className="row-actions" role="group" aria-label="账号操作">
        <Button
          type="button"
          variant={mode === 'login' ? 'default' : 'outline'}
          disabled={busy}
          aria-pressed={mode === 'login'}
          onClick={() => {
            setMode('login');
            setMessage('');
          }}
        >
          登录
        </Button>
        <Button
          type="button"
          variant={mode === 'register' ? 'default' : 'outline'}
          disabled={busy}
          aria-pressed={mode === 'register'}
          onClick={() => {
            setMode('register');
            setMessage('');
          }}
        >
          注册
        </Button>
      </div>
      <form key={mode} onSubmit={submit} className="auth-form">
        {mode === 'register' && (
          <label>
            显示名
            <input
              name="name"
              autoComplete="nickname"
              minLength={1}
              maxLength={100}
              required
              disabled={busy}
            />
          </label>
        )}
        <label>
          邮箱
          <input
            name="email"
            type="email"
            autoComplete="username"
            maxLength={254}
            required
            disabled={busy}
          />
        </label>
        <label>
          密码
          <input
            name="password"
            type="password"
            autoComplete={mode === 'register' ? 'new-password' : 'current-password'}
            minLength={mode === 'register' ? 9 : 1}
            maxLength={mode === 'register' ? 20 : 128}
            required
            disabled={busy}
          />
        </label>
        {mode === 'register' ? (
          <>
            <label>
              确认密码
              <input
                name="confirmation"
                type="password"
                autoComplete="new-password"
                minLength={9}
                maxLength={mode === 'register' ? 20 : 128}
                required
                disabled={busy}
              />
            </label>
            <p className="muted">密码为 9–20 个字符。暂不支持找回密码。</p>
          </>
        ) : (
          <label className="row-actions">
            <input name="remember" type="checkbox" disabled={busy} />
            记住登录状态
          </label>
        )}
        <Button type="submit" disabled={busy || state.status === 'loading'}>
          {busy ? '正在处理…' : mode === 'register' ? '注册并登录' : '登录账号'}
        </Button>
      </form>
      {message && <p role="alert">{message}</p>}
    </>
  );
}

'use client';
