                    <div
                      className={`message message-interviewer ${t.status === 'waiting' ? 'message-current' : ''}`}
                    >
                      <span className="avatar avatar-mint">面</span>
                      <div>
                        <small>{t.status === 'waiting' ? '当前问题' : t.label}</small>
                        {t.acknowledgement && <p>{t.acknowledgement}</p>}
                        <p>{t.text}</p>
