            {p.workspace}
            {!p.voiceView && (
              <form
                className="answer-composer"
                onSubmit={(e) => {
                  e.preventDefault();
                  if (p.canAnswer && p.draft.trim()) p.onSubmit();
                }}
              >
                <div className="composer-heading">
                  <label htmlFor="answer">你的回答</label>
                  <span>{p.voiceActive ? '语音转写 · 麦克风已开启' : '文字作答 · 麦克风关闭'}</span>
                </div>
                <textarea
                  id="answer"
                  maxLength={p.maxAnswer}
                  disabled={!p.canAnswer && !p.ended}
                  readOnly={p.ended || p.voiceActive}
                  value={p.draft}
                  onChange={(e) => p.onText(e.target.value)}
                  placeholder={
                    p.paused
                      ? '继续面试后即可作答'
                      : p.voiceActive
                        ? '请直接说话，实时转写将显示在这里…'
                        : p.onStart
                          ? '点击右上角“开始面试”后即可作答'
                          : '在这里输入回答，结合自己的经历和理解说明…'
                  }
                  onKeyDown={(e) => {
                    if (
                      (e.ctrlKey || e.metaKey) &&
                      e.key === 'Enter' &&
                      !e.nativeEvent.isComposing
                    ) {
                      e.preventDefault();
                      if (p.canAnswer && p.draft.trim()) p.onSubmit();
                    }
                  }}
                />
                {p.draftHint && (
                  <p className="field-help" role="status">
                    {p.draftHint}
                  </p>
                )}
                <div className="composer-bottom">
                  <span>
                    {p.draft.length}/{p.maxAnswer} <kbd>Ctrl + Enter</kbd>
                  </span>
                  <div>
                    {p.onClarify && (
                      <Button
                        type="button"
                        variant="ghost"
                        size="sm"
                        disabled={!p.canAnswer}
                        onClick={p.onClarify}
                      >
                        澄清题意
                      </Button>
                    )}
                    <Button
                      type="button"
                      variant="ghost"
                      size="sm"
                      disabled={!p.canAnswer}
                      onClick={p.onSkip}
                    >
                      <SkipForward size={14} />
                      跳过
                    </Button>
                    <Button type="submit" size="sm" disabled={!p.canAnswer || !p.draft.trim()}>
                      提交回答
                      <ArrowUp size={15} />
                    </Button>
                  </div>
                </div>
