      view = current.current.view;
    return runInterviewEntry(view.id, enterWork, () => enterSession(view), {
      activeId: enteredInterview.current ?? current.current.view?.id,
      cancel: () => {
        binding.current = null;
        startRequest.current = null;
        release();
        setDraft('');
