      },
    });
  }
  async function enterSession(view: Interview): Promise<Interview> {
    if (
      current.current.phase === 'running' &&
      enteredInterview.current === view.id &&
      current.current.view?.id === view.id
    )
      return current.current.view;
    const generation = epoch.current;
    try {
      accept(view);
      update({ error: '', phase: 'preparing' });
      if (!['ready', 'in_progress'].includes(view.status))
        throw new Error('本场面试暂不能自动开始。');
      await prepareSession(view);
      if (generation !== epoch.current) throw new Error('本次准备已取消。');
      update({ phase: 'connecting' });
      if (current.current.textMode || view.configuration.interaction_mode === 'text_fallback')
        await startOnce(view);
      else
        await voiceRef.current.connectPrepared(async () => {
          await startOnce(view);
        });
      if (generation !== epoch.current) throw new Error('本次准备已取消。');
      devices.current?.camera?.getVideoTracks().forEach((t) => {
        t.enabled = true;
      });
      update({ phase: 'running' });
      enteredInterview.current = view.id;
      return current.current.view!;
    } catch (error) {
      if (generation === epoch.current) {
        clearDevices();
        update({
          phase: 'error',
          deviceReady: false,
          camera: null,
          error: error instanceof Error ? error.message : '面试准备失败，请重试。',
        });
      }
      throw error;
    }
  }
  function begin(config: InterviewConfig): Promise<void> {
    if (createWork.current) return createWork.current;
    if (
      current.current.view ||
      !creation.current ||
      JSON.stringify(creation.current.config) !== JSON.stringify(config)
    ) {
      release();
      creation.current = { config, key: crypto.randomUUID() };
      try {
        const saved = JSON.parse(sessionStorage.getItem(`interviewlab:create:${owner}`) ?? 'null');
        if (
          typeof saved?.key === 'string' &&
          JSON.stringify(saved.config) === JSON.stringify(config)
        )
          creation.current.key = saved.key;
      } catch {}
      update({ view: null, textMode: false });
      setDraft('');
    }
    const request = creation.current;
    const generation = epoch.current;
    try {
      sessionStorage.setItem(`interviewlab:create:${owner}`, JSON.stringify(request));
    } catch {}
    update({ configuration: config, error: '', phase: 'devices' });
    const devicePromise = prepareDevices(config);
    const work = (async () => {
      try {
        await devicePromise;
        if (generation !== epoch.current || !alive.current) return;
        update({ phase: 'creating' });
        const view = await interviewsApi.create(request.config, request.key);
        if (generation !== epoch.current || !alive.current) return;
        abandoned.current.delete(view.id);
        try {
          sessionStorage.removeItem(`interviewlab:create:${owner}`);
        } catch {}
        accept(view);
        update({ phase: 'preparing' });
        router.push(`/interview/${view.id}/prepare`);
        void prepareSession(view).catch((error) => {
          if (generation !== epoch.current || !alive.current) return;
          clearDevices();
          update({
            phase: 'error',
            error: error instanceof Error ? error.message : '设备检查失败。',
          });
        });
      } catch (error) {
        if (generation !== epoch.current || !alive.current) return;
        clearDevices();
        update({
          phase: 'error',
          camera: null,
          deviceReady: false,
          error: error instanceof Error ? error.message : '面试创建失败，请重试。',
        });
      }
    })();
    createWork.current = work;
    void work.finally(() => {
      if (createWork.current === work) createWork.current = null;
    });
    return work;
  }
  function useText() {
    release();
    update({
      textMode: true,
      deviceReady: true,
      error: '',
      phase: current.current.view ? 'preparing' : 'idle',
    });
    voiceRef.current.switchToText();
  }
  function abandon() {
    if (current.current.view) abandoned.current.add(current.current.view.id);
    release();
    creation.current = null;
    startRequest.current = null;
    createWork.current = null;
    update({ ...initial, configuration: current.current.configuration });
  }
  const value = {
    ...state,
    voice,
    begin,
    enter,
    accept,
    release,
    useText,
    abandon,
    busy: !['idle', 'error', 'running'].includes(state.phase),
    isAbandoned(id: string) {
      return abandoned.current.has(id);
    },
    retry(view?: Interview) {
      if (view) {
        abandoned.current.delete(view.id);
        accept(view);
      }
      update({ error: '', phase: 'preparing' });
      const config = current.current.configuration;
      if (config) {
        const generation = epoch.current;
        void prepareDevices(config).catch((error) => {
          if (generation !== epoch.current) return;
          clearDevices();
          update({
            phase: 'error',
            error: error instanceof Error ? error.message : '设备检查失败。',
          });
        });
      }
    },
    bind(next: Binding) {
      binding.current = next;
      setDraft(next.draft);
      return () => {
        if (binding.current === next) binding.current = null;
      };
    },
    setCamera(camera: MediaStream | null) {
      if (devices.current) devices.current.camera = camera;
      update({ camera });
    },
    roomPath(view: Interview) {
      return `/interview/${view.id}${!current.current.textMode && view.configuration.interaction_mode === 'realtime_video' ? '/video' : ''}`;
    },
  };
  return <FlowContext.Provider value={value}>{children}</FlowContext.Provider>;
}
interface Flow extends FlowState {
  voice: ReturnType<typeof useInterviewVoice>;
  busy: boolean;
  begin(config: InterviewConfig): Promise<void>;
  enter(view: Interview): Promise<Interview>;
  accept(view: Interview): void;
  release(): void;
  useText(): void;
  abandon(): void;
  retry(view?: Interview): void;
  isAbandoned(id: string): boolean;
  bind(binding: Binding): () => void;
  setCamera(camera: MediaStream | null): void;
  roomPath(view: Interview): string;
}
const FlowContext = createContext<Flow | null>(null);
export function useInterviewFlow() {
  const flow = useContext(FlowContext);
  if (!flow) throw new Error('InterviewFlowProvider is required');
  return flow;
}
export function useOptionalInterviewFlow() {
  return useContext(FlowContext);
}

'use client';
import Link from 'next/link';
import { liveInterviewPath } from '@interviewlab/core';
import { useCallback, useState } from 'react';
import { STATUS_LABELS, LIVE_TYPE_LABELS, type Interview } from '@interviewlab/core';
import { EmptyState, Loading, Modal, formatDate } from '../../components/shared';
import { Button } from '../../components/ui/button';
import { WorkspaceFrame } from '../personal-center/workspace-frame';
import { interviewsApi } from '../../lib/api/interviews';
import { CommandNotice, ErrorNotice, SessionGate, useLiveCommand, useLiveResource } from './common';
function HistoryBody() {
  const [status, setStatus] = useState('');
  const [job, setJob] = useState('');
  const [cursor, setCursor] = useState('');
  const [deletion, setDeletion] = useState<Interview | null>(null);
  const command = useLiveCommand();
  const load = useCallback(
    (signal: AbortSignal) => {
      const query = new URLSearchParams({ limit: '20' });
      if (status) query.set('status', status);
      if (job) query.set('job', job);
      if (cursor) query.set('cursor', cursor);
      return interviewsApi.list(`?${query}`, signal);
    },
    [status, job, cursor],
  );
  const resource = useLiveResource(load, () => false);
  const jobsLoad = useCallback((signal: AbortSignal) => interviewsApi.jobs(signal), []);
  const jobs = useLiveResource(jobsLoad, () => false);
  return (
    <>
      <div className="workspace-heading">
        <h1>面试记录</h1>
        <Button asChild>
          <Link href="/interview/setup">开始 AI 面试</Link>
        </Button>
      </div>
      <section className="library-panel">
        <div className="record-filters">
          <label>
            状态
            <select
              value={status}
              onChange={(e) => {
                setStatus(e.target.value);
                setCursor('');
              }}
            >
              <option value="">全部状态</option>
              {Object.entries(STATUS_LABELS).map(([key, title]) => (
                <option key={key} value={key}>
                  {title}
                </option>
              ))}
            </select>
          </label>
          <label>
            岗位
            <select
              value={job}
              onChange={(e) => {
                setJob(e.target.value);
                setCursor('');
              }}
            >
              <option value="">全部岗位</option>
              {jobs.value?.items.map((j) => (
                <option key={j.id} value={j.id}>
                  {j.title}
                </option>
              ))}
            </select>
          </label>
          <Button variant="outline" size="sm" onClick={() => void resource.refresh()}>
            刷新记录
          </Button>
        </div>
        <ErrorNotice message={resource.error} retry={() => void resource.refresh()} />
        <CommandNotice command={command} refresh={() => void resource.refresh()} />
        {!resource.value && !resource.error && <Loading />}
        {resource.value && (
          <>
            {!resource.value.items.length ? (
              <EmptyState
                title="暂无面试记录"
                description="选择岗位开始练习，记录会保存在当前账号中。"
                href="/interview/setup"
                action="开始一次文字面试"
              />
            ) : (
              <div className="table-scroll">
                <table className="library-table">
                  <thead>
                    <tr>
                      <th scope="col">岗位 / 面试类型</th>
                      <th scope="col">创建时间</th>
                      <th scope="col">状态</th>
                      <th scope="col">操作</th>
                    </tr>
                  </thead>
                  <tbody>
                    {resource.value.items.map((v) => (
                      <tr key={v.id}>
                        <td>
                          <strong>{v.job_title}</strong>
                          <span>
                            {LIVE_TYPE_LABELS[v.configuration.interview_type]}
                            {v.parent_interview_id ? ' · 单题重练' : ''}
                          </span>
                        </td>
                        <td>
                          <time dateTime={v.created_at}>{formatDate(v.created_at)}</time>
                        </td>
                        <td>
                          <span
                            className={`status-chip ${v.status === 'completed' ? 'success' : ''}`}
                          >
                            {STATUS_LABELS[v.status]}
                          </span>
                        </td>
                        <td>
                          <div className="row-actions">
                            <Link
                              className="text-link"
                              href={
                                ['completed', 'failed'].includes(v.status)
                                  ? `/reports/${v.id}`
                                  : liveInterviewPath(v)
                              }
                            >
                              {['completed', 'failed'].includes(v.status) ? '查看报告' : '继续面试'}
                            </Link>
                            <Button
                              size="sm"
                              variant="ghost"
                              disabled={command.blocked}
                              onClick={() => setDeletion(v)}
                              aria-label={`删除${v.job_title}面试记录`}
                            >
                              删除
                            </Button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
            <div className="library-pagination">
              {cursor && (
                <Button variant="outline" size="sm" onClick={() => setCursor('')}>
                  回到最新
                </Button>
              )}
              {resource.value.next_cursor && (
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => setCursor(resource.value!.next_cursor!)}
                >
                  下一页
                </Button>
              )}
            </div>
          </>
        )}
      </section>
      {deletion && (
        <Modal
          open={Boolean(deletion)}
          onOpenChange={(open) => {
            if (!open && !command.blocked) setDeletion(null);
          }}
          title="删除面试及关联复盘"
        >
          <p>
            会删除本场问题、回答、报告和包含本场内容的比较。独立重练的回答会保留，来源关联将解除。此操作无法撤销。
          </p>
          <Button
            variant="danger"
            disabled={command.blocked}
            onClick={() =>
              command.run(
                (key) => interviewsApi.remove(deletion.id, deletion.version, key),
                () => {
                  setDeletion(null);
                  void resource.refresh();
                },
              )
            }
          >
            确认删除
          </Button>
          <CommandNotice
            command={command}
            refresh={() => {
              setDeletion(null);
              void resource.refresh();
            }}
          />
        </Modal>
      )}
    </>
  );
}
export default function LiveHistory() {
  return (
    <WorkspaceFrame section="interviews">
      <SessionGate>
        <HistoryBody />
      </SessionGate>
    </WorkspaceFrame>
  );
}

'use client';
import { useCallback, useEffect, useRef, useState } from 'react';
import { INTERVIEW_MAX_ANSWER, type Interview } from '@interviewlab/core';
import { useRouter } from 'next/navigation';
import { interviewsApi } from '../../lib/api/interviews';
import { useSession } from '../../components/session-provider';
import { Brand, Header, Loading, Modal } from '../../components/shared';
import { CommandNotice, ErrorNotice, SessionGate, useLiveCommand, useLiveResource } from './common';

import { useInterviewStream } from './stream';
import { InterviewWorkspace } from '../../components/interview-workspace';
import { Button } from '../../components/ui/button';
import { useInterviewFlow } from './flow-provider';
import { PreparationScreen } from './preparation';
import { TransitionScreen } from './transition-screen';
import { VoiceControls } from './voice/controls';
import { VideoInterviewWorkspace } from '../video-interview/room';
import { useQuestionPresentation } from './use-question-presentation';
import { interviewPresentation } from './interview-presentation';
import { InterviewProgressNotice, InterviewGenerationNotice } from './interview-notices';

function InterviewBody({ id, videoRoom = false }: { id: string; videoRoom?: boolean }) {
  const flow = useInterviewFlow();
  const router = useRouter();
  const Workspace = videoRoom ? VideoInterviewWorkspace : InterviewWorkspace;
  const { state: account } = useSession();
  const load = useCallback((signal: AbortSignal) => interviewsApi.read(id, signal), [id]);
  const [streamConnected, setStreamConnected] = useState(false);
  const resource = useLiveResource(
    load,
    (v) =>
      (v.generation_status === 'pending' && !streamConnected) ||
      ['pending', 'waiting_material'].includes(v.preparation?.status ?? ''),
  );
  const stream = useInterviewStream(id, resource.value, resource.accept, resource.refresh);
  useEffect(() => setStreamConnected(stream.connected), [stream.connected]);
  const command = useLiveCommand(() => void resource.refresh());
  const [draft, setDraft] = useState({ key: '', text: '' });
  const [storageError, setStorageError] = useState('');
  const [finish, setFinish] = useState(false);
  const restoreVoice = useRef<(() => void) | null>(null);
  const [now, setNow] = useState(Date.now());
  const deadlineChecked = useRef(false);
  const v = resource.value;
  const presentation = useQuestionPresentation(v);
  const turn = v?.turns.at(-1);
  const terminal = v?.status === 'completed' || v?.status === 'failed';
  const userId = account.status === 'signed_in' ? account.session.user.id : '';
  const draftKey = userId && turn ? `interviewlab:live:${userId}:${id}:${turn.id}` : '';
  useEffect(() => {
    if (!draftKey) return;
    try {
      setDraft({ key: draftKey, text: sessionStorage.getItem(draftKey) ?? '' });
    } catch {
      setDraft({ key: draftKey, text: '' });
      setStorageError('浏览器无法保存草稿，请保持页面打开。');
    }
  }, [draftKey]);
  useEffect(() => {
    if (!v?.started_at || terminal) return;
    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(timer);
  }, [v?.started_at, terminal]);
  useEffect(() => {
    if (
      v?.deadline_at &&
      now >= Date.parse(v.deadline_at) &&
      !terminal &&
      !deadlineChecked.current
    ) {
      deadlineChecked.current = true;
      void resource.refresh();
    }
  }, [now, v?.deadline_at, terminal, resource.refresh]);
  function setText(text: string) {
    setDraft({ key: draftKey, text });
    try {
      sessionStorage.setItem(draftKey, text);
    } catch {
      setStorageError('草稿仅保留在当前页面，刷新可能丢失。');
    }
  }
  const text = draft.key === draftKey ? draft.text : '';
  function accepted(result: Interview, submitted?: { turnId: string; text: string; key: string }) {
    if (
      submitted &&
      result.turns.some(
        (t) =>
          t.id === submitted.turnId &&
          t.answer_status === 'answered' &&
          t.answer_text === submitted.text,
      )
    ) {
      try {
        sessionStorage.removeItem(submitted.key);
      } catch {}
      setDraft({ key: submitted.key, text: '' });
    }
    resource.accept(result);
    setNow(Date.now());
    restoreVoice.current = null;
    setFinish(false);
  }
  function act(
    action: string,
    body: object,
    submitted?: { turnId: string; text: string; key: string },
  ) {
    const input = { version: v!.version, ...body };
    command.run(
      (key) => interviewsApi.command(id, action, input, key),
      (result) => accepted(result, submitted),
    );
  }
  const voice = flow.voice;
  function changeFinish(open: boolean) {
    if (open) restoreVoice.current = voice.suspend();
    else {
      restoreVoice.current?.();
      restoreVoice.current = null;
    }
    setFinish(open);
  }
  useEffect(
    () => flow.bind({ id, draft: text, onDraft: setText, onView: resource.accept }),
    [id, text, draftKey],
  );
  useEffect(() => {
    if (!v) return;
    if (flow.view !== v) flow.accept(v);
    if (terminal) {
      flow.release();
      router.replace(`/interview/${id}/analysis`);
    } else if (
      v.status === 'ready' ||
      (v.status === 'in_progress' &&
        v.configuration.interaction_mode !== 'text_fallback' &&
        flow.phase === 'idle')
    )
      router.replace(`/interview/${id}/prepare`);
  }, [v?.id, v?.version, v?.status]);
  if (!v)
    return (
      <>
        <header className="session-header">
          <Brand />
        </header>
        <main className="session-main" id="main-content">
          <ErrorNotice message={resource.error} retry={() => void resource.refresh()} />
          {!resource.error && <Loading />}
        </main>
      </>
    );
  if (v.status === 'ready') return <PreparationScreen view={v} />;
  if (terminal)
    return (
      <TransitionScreen
        kind="analysis"
        title="恭喜你完成面试"
        description="回答已保存，正在为你准备复盘。"
        steps={[
          { label: '保存回答', state: 'done' },
          { label: '读取分析进度', state: 'active' },
        ]}
      />
    );
  const waiting = turn?.answer_status === 'waiting';
  const continuation =
    turn?.answer_status === 'answered' &&
    v.generation_status === 'idle' &&
    v.status === 'in_progress';
  const canAnswer =
    (waiting || continuation) &&
    v.status === 'in_progress' &&
    v.generation_status !== 'pending' &&
    !command.blocked;
  const targetReached = v.target_at && now >= Date.parse(v.target_at);
  const workspace = interviewPresentation(v, now, stream.preview);
  const submit = () => {
    if (voice.active) {
      voice.commit();
      return;
    }
    if (continuation)
      act(
        'voice/continue',
        { turn_id: turn!.id, text },
        {
          turnId: turn!.id,
          text: [turn!.answer_text, text].filter(Boolean).join('/n'),
          key: draftKey,
        },
      );
    else act(`turns/${turn!.id}/answer`, { text }, { turnId: turn!.id, text, key: draftKey });
  };

  return (
    <>
      <Workspace
        voice={voice}
        initialCamera={flow.camera}
        onCameraChange={flow.setCamera}
        jobTitle={v.job_title}
        typeLabel={workspace.typeLabel}
        interviewerLabel="AI 面试官"
        interviewerStatus={workspace.interviewerStatus}
        seconds={workspace.seconds}
        durationMinutes={v.configuration.duration_minutes}
        turns={workspace.turns}
        current={workspace.current}
        draft={text}
        maxAnswer={INTERVIEW_MAX_ANSWER}
        canAnswer={Boolean(canAnswer)}
        blocked={
          command.blocked ||
          voice.connecting ||
          Boolean(v.preparation && !['ready', 'fallback'].includes(v.preparation.status))
        }
        paused={v.status === 'paused'}
        ended={Boolean(terminal)}
        saveLabel={workspace.saveLabel}
        draftHint={
          storageError ||
          (terminal && text
            ? '此草稿尚未提交，你仍可复制保存。'
            : '草稿保留在当前标签页，提交确认后清除。')
        }
        explanation={v.clarification}
        voiceActive={voice.active}
        voiceView={voice.display}
        workspace={
          <VoiceControls
            voice={voice}
            preferred={v.configuration.interaction_mode === 'realtime_voice'}
            disabled={v.status !== 'in_progress' || command.blocked || finish}
          />
        }
        notice={
          <>
            <ErrorNotice message={resource.error} retry={() => void resource.refresh()} />
            <ErrorNotice message={presentation.error} retry={presentation.retry} />
            <CommandNotice command={command} refresh={() => void resource.refresh()} />
            <InterviewProgressNotice
              view={v}
              continuation={Boolean(continuation)}
              targetReached={Boolean(targetReached)}
              canContinue={!command.blocked && !voice.active}
              onContinue={() => act('voice/continue', { turn_id: turn!.id, text: '' })}
            />
          </>
        }
        conversationNotice={
          <InterviewGenerationNotice
            view={v}
            preview={stream.preview}
            blocked={command.blocked}
            onRetry={(fallback) => act('generation/retry', { fallback })}
          />
        }
        interviewerNote={
          <>
            结合自己的实际经历回答，不熟悉的内容可以直接说明。
            <br />
            面试中不展示评价和参考答案。
          </>
        }
        recordsHref="/me/interviews"
        reportHref={`/reports/${id}`}
        onText={setText}
        onSubmit={submit}
        onSkip={() => {
          voice.stop();
          if (text.trim()) setStorageError('请先提交或清空当前草稿，再跳过本题。');
          else act(`turns/${turn!.id}/actions`, { action: 'skip' });
        }}
        onRepeat={() => act(`turns/${turn!.id}/actions`, { action: 'repeat_question' })}
        onClarify={() => act(`turns/${turn!.id}/actions`, { action: 'clarify_question' })}
        onPause={() => {
          voice.stop();
          act(v.status === 'paused' ? 'resume' : 'pause', {});
        }}
        onFinish={() => changeFinish(true)}
      />
      {finish && (
        <Modal
          open
          onOpenChange={(open) => {
            if (!command.blocked) changeFinish(open);
          }}
          title="确定提前结束面试？"
          description={
            text.trim()
              ? '当前回答会一并提交，随后为你呈现本场分析报告。'
              : '结束后将为你呈现本场分析报告。'
          }
        >
          <div className="dialog-actions">
            <Button
              variant="outline"
              disabled={command.blocked}
              onClick={() => changeFinish(false)}
            >
              继续面试
            </Button>
            <Button
              disabled={command.blocked}
              onClick={() => {
                const finalText = text.trim();
                act(
                  'finish',
                  {
                    reason: 'user_finished',
                    ...(finalText && turn
                      ? { final_answer: { turn_id: turn.id, text: finalText } }
                      : {}),
                  },
                  finalText && turn
                    ? {
                        turnId: turn.id,
                        text: continuation
                          ? [turn.answer_text, finalText].filter(Boolean).join('/n')
                          : finalText,
                        key: draftKey,
                      }
                    : undefined,
                );
              }}
            >
              结束面试并查看报告
            </Button>
          </div>
          <CommandNotice command={command} refresh={() => void resource.refresh()} />
        </Modal>
      )}
    </>
  );
}
