                    await resource.refresh();
                  } catch (e) {
                    setError(e instanceof Error ? e.message : '取消失败');
                  } finally {
                    setBusy('');
                  }
                }}
              >
                <Trash2 size={19} />
              </Button>
            </div>
          </article>
        ))}
      </div>
    </WorkspaceFrame>
  );
}

