import type { ApiError } from '@interviewlab/core';

export class ApiClientError extends Error {
  constructor(
    public readonly status: number,
    public readonly detail: ApiError,
  ) {
    super(detail.message);
    this.name = 'ApiClientError';
  }
}
export const SESSION_CHANGED = 'interviewlab:session-changed';
export const SESSION_INVALIDATED = 'interviewlab:session-invalidated';
export function notifySessionChanged() {
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new Event(SESSION_CHANGED));
    if (typeof BroadcastChannel !== 'undefined') {
      const channel = new BroadcastChannel(SESSION_CHANGED);
      channel.postMessage('refresh');
      channel.close();
    }
  }
}
export interface ApiRequestOptions {
  method?: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
  body?: unknown;
  headers?: HeadersInit;
  idempotencyKey?: string;
  signal?: AbortSignal;
  timeoutMs?: number;
}
function isApiError(value: unknown): value is ApiError {
  if (!value || typeof value !== 'object') return false;
  const error = value as Record<string, unknown>;
  return (
    typeof error.code === 'string' &&
    typeof error.message === 'string' &&
    typeof error.retryable === 'boolean' &&
    typeof error.request_id === 'string'
  );
}
/** Browser-only HTTP transport. No token storage, redirects or automatic write retries. */
export function createApiClient(fetcher: typeof fetch = (...args) => fetch(...args)) {
  return async function request<T>(path: string, options: ApiRequestOptions = {}): Promise<T> {
    const target = new URL('/api/v1' + path, 'http://same-origin.invalid');
    if (
      !path.startsWith('/') ||
      path.startsWith('//') ||
      path.includes('//') ||
      target.hash ||
      !target.pathname.startsWith('/api/v1/')
    )
      throw new Error('Use a path relative to /api/v1');
    const headers = new Headers(options.headers);
    headers.set('accept', 'application/json');
    if (options.body !== undefined) headers.set('content-type', 'application/json');
    if (options.idempotencyKey) headers.set('Idempotency-Key', options.idempotencyKey);
    const timeout = AbortSignal.timeout(options.timeoutMs ?? 10000);
    const signal = options.signal ? AbortSignal.any([options.signal, timeout]) : timeout;
    let response: Response | undefined;
    let data: unknown;
    try {
      response = await fetcher(target.pathname + target.search, {
        method: options.method ?? 'GET',
        headers,
        body: options.body === undefined ? undefined : JSON.stringify(options.body),
        credentials: 'same-origin',
        cache: 'no-store',
        redirect: 'error',
        signal,
      });
      if (response.status === 204) return undefined as T;
      if (response.headers.get('content-type')?.includes('application/json'))
        data = await response.json().catch((error) => {
          if (signal.aborted) throw error;
          return undefined;
        });
    } catch {
      if (options.signal?.aborted) throw options.signal.reason;
      throw new ApiClientError(response?.status ?? 0, {
        code: timeout.aborted ? 'request_timeout' : 'backend_unavailable',
        message: timeout.aborted ? '请求超时，请稍后重试。' : '暂时无法连接服务，请稍后重试。',
        retryable: true,
        request_id: response?.headers.get('x-request-id') ?? '',
      });
    }
    if (!response.ok) {
      if (response.status === 401 && !path.startsWith('/auth/') && typeof window !== 'undefined')
        window.dispatchEvent(new Event(SESSION_INVALIDATED));
      throw new ApiClientError(
        response.status,
        isApiError(data)
          ? data
          : {
              code: 'http_error',
              message: '请求未能完成，请稍后重试。',
              retryable: response.status >= 500 || response.status === 429,
              request_id: response.headers.get('x-request-id') ?? '',
            },
      );
    }
    if (data === undefined)
      throw new ApiClientError(response.status, {
        code: 'invalid_response',
        message: '服务返回了无法识别的响应。',
        retryable: false,
        request_id: response.headers.get('x-request-id') ?? '',
      });
    return data as T;
  };
}
export const apiRequest = createApiClient();

/** Same-origin cookie transport for server events; no separate identity or token client. */
export function apiEvents(path: string): EventSource {
  const url = new URL('/api/v1' + path, window.location.origin);
  if (
    !path.startsWith('/') ||
    path.startsWith('//') ||
    path.includes('//') ||
    url.origin !== window.location.origin ||
    !url.pathname.startsWith('/api/v1/')
  )
    throw new Error('Use a relative API event path');
  return new EventSource(url.pathname + url.search);
}

/** Same-origin Cookie-authenticated voice channel, through the existing API proxy. */
export function apiVoiceSocket(path: string): WebSocket {
  const url = new URL('/api/v1' + path, window.location.origin);
  if (
    !path.startsWith('/') ||
    path.startsWith('//') ||
    path.includes('//') ||
    url.hash ||
    url.origin !== window.location.origin ||
    !url.pathname.startsWith('/api/v1/')
  )
    throw new Error('Use a relative API voice path');
  url.protocol = url.protocol === 'https:' ? 'wss:' : 'ws:';
  return new WebSocket(url);
}

import { Pool, type PoolClient } from 'pg';
import { drizzle, type NodePgDatabase } from 'drizzle-orm/node-postgres';
import type { BackendConfig } from '../foundation/config';
import * as foundationSchema from './schema';
import * as authSchema from '../modules/accounts/auth-schema';
import * as interviewSchema from '../modules/interviews/schema';
import * as materialSchema from '../modules/resumes/schema';
import * as reportSchema from '../modules/reports/schema';
const schema = { ...foundationSchema, ...authSchema, ...interviewSchema, ...reportSchema, ...materialSchema };
export interface Transaction {
  client: PoolClient;
  db: NodePgDatabase<typeof schema>;
}
export function createDatabase(config: BackendConfig) {
  if (!config.DATABASE_URL) throw new Error('DATABASE_URL is required');
  const pool = new Pool({
    connectionString: config.DATABASE_URL,
    max: config.DATABASE_POOL_SIZE,
    connectionTimeoutMillis: config.DATABASE_CONNECT_TIMEOUT_MS,
    idleTimeoutMillis: 10000,
    statement_timeout: 10000,
  });
  // Idle clients can fail independently; prevent an unhandled EventEmitter error.
  pool.on('error', () => {
    /* Readiness probes and subsequent operations report failure. */
  });
  const db = drizzle(pool, { schema });
  return {
    pool,
    db,
    async transaction<T>(work: (tx: Transaction) => Promise<T>): Promise<T> {
      const client = await pool.connect();
      try {
        await client.query('BEGIN');
        const result = await work({ client, db: drizzle(client, { schema }) });
        await client.query('COMMIT');
        return result;
      } catch (error) {
        await client.query('ROLLBACK').catch(() => {});
        throw error;
      } finally {
        client.release();
      }
    },
    async ready(workerStaleMs: number, authentication = false) {
      try {
        // Missing migrations are not considered ready.
        await pool.query('SELECT id FROM tasks LIMIT 0');
        if (authentication) {
          for (const table of [
            'auth_users',
            'auth_sessions',
            'auth_accounts',
            'auth_verifications',
            'auth_rate_limits',
          ])
            await pool.query(`SELECT id FROM ${table} LIMIT 0`);
        }
        const result = await pool.query(
          "SELECT EXISTS (SELECT 1 FROM worker_heartbeats WHERE last_seen_at > now() - $1 * interval '1 millisecond') AS worker",
          [workerStaleMs],
        );
        return { database: true, worker: Boolean(result.rows[0].worker) };
      } catch {
        return { database: false, worker: false };
      }
    },
    close: () => pool.end(),
  };
}
export type Database = ReturnType<typeof createDatabase>;

