  assertConversationQuestion(text, policy.conversation, true);
  if (policy.next_step === 'introduction') {
    if (project.test(text) || !/介绍|学习背景|专业|学习经历|应聘|选择.{0,8}方向/.test(text))
      throw new ServiceError('invalid_model_output', 502, '打招呼尚未完成自我介绍，应先了解背景');
    return;
  }
  if (policy.next_step === 'alternative_experience') {
    if (
      !/课程|练习|作业|学过|学习|接触|其他.{0,8}(?:项目|经历)|别的.{0,8}(?:项目|经历)/.test(text) ||
      /你(?:做过|完成|参与)的(?:课程|练习|作业|其他)/.test(text)
    )
      throw new ServiceError(
        'invalid_model_output',
        502,
        '没有项目信息时应先了解可替代的学习或实践背景',
      );
    return;
  }
  if (!policy.discovery_required) return;
  const scope = policy.missing.includes('project_description') && scopeQuestion.test(text);
  const role = policy.missing.includes('personal_role') && roleQuestion.test(text);
  if (!scope && !role)
    throw new ServiceError('invalid_model_output', 502, '应先了解项目内容或本人职责');
}

export function preparingBackground(policy: ExperiencePolicy) {
  return [
    'introduction',
    'alternative_experience',
    'project_discovery',
    'motivation',
    'topic_transition',
  ].includes(policy.next_step);
}
export function knowledgeReady(policy: ExperiencePolicy) {
  return policy.next_step === 'interview';
}

import { Annotation, StateGraph, START, END } from '@langchain/langgraph';
import { ServiceError } from '../../foundation/errors';

/** A graph is a single bounded task execution; database task claims own durable recovery. */
export async function checkedGraph<I, C, O>(
  name: string,
  input: I,
  steps: {
    prepare: (input: I) => Promise<C> | C;
    generate: (context: C) => Promise<unknown>;
    validate: (raw: unknown, context: C) => O;
  },
  signal: AbortSignal,
  log: (entry: object) => void = () => {},
): Promise<O> {
  const State = Annotation.Root({
    input: Annotation<I>(),
    context: Annotation<C>(),
    raw: Annotation<unknown>(),
    result: Annotation<O>(),
  });
  const timed = async <T>(node: string, work: () => Promise<T> | T) => {
    const started = performance.now();
    if (signal.aborted) throw new ServiceError('task_cancelled', 409, '任务已取消');
    try {
      return await work();
    } finally {
      log({ workflow: name, node, duration_ms: Math.round(performance.now() - started) });
    }
  };
  const graph = new StateGraph(State)
    .addNode('prepare_context', async (s) => ({
      context: await timed('prepare_context', () => steps.prepare(s.input)),
    }))
    .addNode('model', async (s) => ({ raw: await timed('model', () => steps.generate(s.context)) }))
    .addNode('validate', async (s) => ({
      result: await timed('validate', () => steps.validate(s.raw, s.context)),
    }))
    .addEdge(START, 'prepare_context')
    .addEdge('prepare_context', 'model')
    .addEdge('model', 'validate')
    .addEdge('validate', END)
    .compile();
  const result = await graph.invoke({ input }, { signal, recursionLimit: 8 });
  if (signal.aborted) throw new ServiceError('task_cancelled', 409, '任务已取消');
  return result.result;
}

import { z } from 'zod';
import type {
  InterviewMemory,
  InterviewMemoryDelta,
  InterviewSnapshot,
  InterviewTurn,
} from '@interviewlab/core';
import { evidenceMatches } from '@interviewlab/core';
import { ServiceError } from '../../foundation/errors';
const evidence = z
  .object({
    turn_id: z.string(),
    revision: z.number().int().positive(),
    quote: z.string().min(1).max(300),
  })
  .strict();
export const memoryDeltaSchema = z
  .object({
    focus: z.string().max(50),
    intent: z.string().min(1).max(120),
    observations: z
      .array(
        z
          .object({
            goal: z.string(),
            state: z.enum(['needs_probe', 'covered', 'inconclusive', 'not_applicable']),
            evidence_refs: z.array(evidence).min(1).max(2),
            pending: z.string().max(180).nullable(),
          })
          .strict(),
      )
      .max(3),
    claims: z
      .array(
        z
          .object({
            text: z.string().min(1).max(300),
            evidence_refs: z.array(evidence).min(1).max(2),
          })
          .strict(),
      )
      .max(3),
  })
  .strict();
export function initialMemory(): InterviewMemory {
  return { version: 0, focus: null, observations: [], claims: [], asked_intents: [] };
}
export function applyMemory(
  memory: InterviewMemory | null,
  delta: InterviewMemoryDelta,
  snapshot: InterviewSnapshot,
  turns: InterviewTurn[],
): InterviewMemory {
  const base = memory ?? initialMemory();
  const goals = new Set(snapshot.knowledge.agent_release?.competencies.map((g) => g.id) ?? []);
  if (!goals.has(delta.focus) || delta.observations.some((x) => !goals.has(x.goal)))
    throw new ServiceError('invalid_model_output', 502, '观察目标不可用');
  for (const row of [...delta.observations, ...delta.claims])
    if (row.evidence_refs.some((e) => !evidenceMatches(e, turns)))
      throw new ServiceError('invalid_model_output', 502, '记忆引用无效');
  // Claims are quoted statements, never model-inferred candidate facts.
  for (const claim of delta.claims)
    if (!claim.evidence_refs.some((e) => e.quote === claim.text))
      throw new ServiceError('invalid_model_output', 502, '陈述必须使用原文');
  if (base.asked_intents.includes(delta.intent))
    throw new ServiceError('invalid_model_output', 502, '重复的问题意图');
  const observations = new Map(base.observations.map((x) => [x.goal, x]));
  delta.observations.forEach((x) => observations.set(x.goal, x));
  return {
    version: base.version + 1,
    ...(base.response ? { response: base.response } : {}),
    ...(base.communication_observed !== undefined
      ? { communication_observed: base.communication_observed }
      : {}),
    ...(base.introduction_complete !== undefined
      ? { introduction_complete: base.introduction_complete }
      : {}),
    ...(base.experience ? { experience: base.experience } : {}),
    ...(base.conversation ? { conversation: base.conversation } : {}),
    focus: delta.focus,
    observations: [...observations.values()],
    claims: [...base.claims, ...delta.claims]
      .filter((x, i, a) => a.findIndex((v) => v.text === x.text) === i)
      .slice(-24),
    asked_intents: [...base.asked_intents, delta.intent].slice(-18),
  };
}

