          tx.client,
          state.view.id,
          input.generation_id,
          state.view.turns.at(-1)!.id,
        ),
      lock: async (tx) => {
        try {
          await loadInterview(tx.client, task.owner_id, input.interview_id, true);
          return true;
        } catch (e) {
          if (e instanceof ServiceError && e.statusCode === 404) return false;
