  alternative: '尊重边界，选择尚未覆盖的适用目标',
}));
export const PROFILE_GOALS: Record<InterviewConfig['interview_type'], string[]> = {
  technical_qa: [
    'understanding',
    'contribution',
    'verification',
    'tradeoffs',
    'learning',
    'motivation',
  ],
  project_deep_dive: ['contribution', 'tradeoffs', 'verification', 'collaboration'],
  business_scenario: [
    'business',
    'contribution',
    'tradeoffs',
    'understanding',
    'verification',
    'learning',
    'motivation',
    'collaboration',
  ],
  hr: ['motivation', 'availability', 'expectations', 'collaboration', 'learning', 'contribution'],
  mixed: COMPETENCIES.map((c) => c.id),
};
export function catalogProfile(type: InterviewConfig['interview_type']): InterviewProfile {
  return {
    id: type,
    type,
    version: CATALOG_FORMAT,
    label: LIVE_TYPE_LABELS[type],
    goals: PROFILE_GOALS[type],
  };
}
export function planningRoleContext(config: InterviewConfig): InterviewRoleContext {
  const job = getJob(config.job);
  if (!job || !job.stages.includes(config.career_stage))
    throw new ServiceError('unsupported_input', 400, '岗位或招聘阶段不可用');
  return {
    job_id: job.id,
    job_title: job.title,
    job_version: job.version,
    description: job.description,
    responsibilities: [...job.responsibilities],
    requirements: [...job.requirements],
    topics: [...job.topics],
    source_refs: [...job.source_refs],
    usage: 'role_requirements_not_candidate_evidence',
  };
}
export interface CatalogDocument {
  id: string;
  kind: NonNullable<KnowledgeChunk['kind']>;
  text: string;
  source_refs: string[];
  evidence_level: NonNullable<KnowledgeChunk['evidence_level']>;
  bindings: {
    job: string;
    stages: string[];
    types: InterviewConfig['interview_type'][];
    goals: string[];
  }[];
}
export const contentHash = (value: unknown) =>
  createHash('sha256').update(JSON.stringify(value)).digest('hex');
/** One authored record, many applicability bindings. Original catalog IDs are never replaced. */
export function buildCatalog(): CatalogDocument[] {
  const documents: CatalogDocument[] = [];
  const allTypes = Object.keys(PROFILE_GOALS) as InterviewConfig['interview_type'][];
  for (const job of JOBS) {
    const binding = {
      job: job.id,
      stages: job.stages,
      types: allTypes,
      goals: COMPETENCIES.map((c) => c.id),
    };
    documents.push({
      id: `${job.id}:profile:${job.version}`,
      kind: 'job_profile',
      text: templateJd(job),
      source_refs: job.source_refs,
      evidence_level: 'platform_authored',
      bindings: [binding],
    });
    for (const q of job.questions.filter(isActiveQuestion))
      documents.push({
        id: q.id,
        kind: 'question',
        evidence_level: 'platform_authored',
        source_refs: q.source_refs,
        text: `${q.topic}：${q.text}/n提问目的：${q.intent}/n观察方向：${q.observation_points.join('；')}/n追问线索：${q.follow_ups.join('；')}/n平台原创提问素材，不是标准答案或已验证能力证据。`,
        bindings: [
          {
            ...binding,
            stages: q.stages,
            types: questionInterviewTypes(q),
            goals: q.competencies?.length ? [...q.competencies] : binding.goals,
          },
        ],
      });
  }
  if (PUBLIC_INTERVIEW_SUPPLEMENTS.runtime_enabled)
    for (const question of PUBLIC_INTERVIEW_SUPPLEMENTS.questions) {
      if (!question.runtime_enabled) continue;
      const bindings = question.eligible_job_ids.map((jobId) => {
        const job = getJob(jobId);
        if (!job) throw new Error(`Supplemental question targets an unavailable role: ${jobId}`);
        const stages = question.stages.filter((stage) => job.stages.includes(stage));
        if (!stages.length) throw new Error(`Supplemental question has no applicable stage: ${jobId}`);
        return {
          job: job.id,
          stages,
          types: question.interview_types,
          goals: question.competencies,
        };
      });
      documents.push({
        id: question.id,
        kind: 'question',
        evidence_level: 'source_summary',
        source_refs: question.source_refs,
        text: `${question.topic}：${question.text}/n提问目的：${question.intent}/n观察方向：${question.observation_points.join('；')}/n追问线索：${question.follow_ups.join('；')}/n来源与适用限制：${question.limitations}/n公开面经摘要，不是标准答案或已验证能力证据。`,
        bindings,
      });
    }
  for (const { job, source, questions } of teacherAgentQuestions) {
    if (!getJob(job)?.stages.includes('campus'))
      throw new Error(`Teacher question set targets an unavailable campus role: ${job}`);
    for (const q of questions) {
      const experience = q.number.startsWith('A');
      const scenario =
        (source.id === 'teacher-issue-12' && q.number.startsWith('C')) ||
        (source.id === 'teacher-issue-14' && /^[C-F]/.test(q.number));
      documents.push({
        id: `${source.id}-${q.number.toLowerCase()}-v1`,
        kind: 'question',
        evidence_level: 'source_summary',
        source_refs: [source.id],
        text: `${q.topic}（${q.difficulty}）/n题目：${q.text}${
          q.notes ? `/n面试官参考（用于追问，不向候选人提示）：/n${q.notes}` : ''
        }`,
        bindings: [
          {
            job,
