interface Props {
  jobTitle: string;
  typeLabel: string;
  interviewerLabel: string;
  interviewerStatus: string;
  seconds: number;
  durationMinutes: number;
  turns: WorkspaceTurn[];
  current?: WorkspaceTurn;
  draft: string;
  maxAnswer: number;
  canAnswer: boolean;
  blocked?: boolean;
  paused: boolean;
  ended: boolean;
  saveLabel: string;
  draftHint?: string;
